{
  "name": "MintFlow - Gestione Spese AI",
  "description": "Un'applicazione moderna per la gestione delle spese mensili con insight intelligenti basati su Gemini API, caratterizzata da un design pulito bianco e verde menta.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Category {
  Alimentari = 'Alimentari',
  Trasporti = 'Trasporti',
  Casa = 'Casa',
  Svago = 'Svago',
  Salute = 'Salute',
  Shopping = 'Shopping',
  Utenze = 'Utenze',
  Altro = 'Altro'
}

export interface Expense {
  id: string;
  date: string;
  description: string;
  amount: number;
  category: Category;
}

export interface MonthlyBudget {
  month: string; // YYYY-MM
  limit: number;
}

export interface AiInsight {
  title: string;
  advice: string;
  type: 'saving' | 'warning' | 'tip';
}

import React, { useState, useEffect, useMemo } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { Expense, Category } from './types';
import { Plus, LayoutDashboard, List, BrainCircuit } from 'lucide-react';

const App: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('mintflow_expenses');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ai'>('dashboard');
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    localStorage.setItem('mintflow_expenses', JSON.stringify(expenses));
  }, [expenses]);

  const addExpense = (expense: Omit<Expense, 'id'>) => {
    const newExpense = { ...expense, id: crypto.randomUUID() };
    setExpenses(prev => [newExpense, ...prev]);
    setShowForm(false);
  };

  const deleteExpense = (id: string) => {
    setExpenses(prev => prev.filter(e => e.id !== id));
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {activeTab === 'dashboard' && (
          <Dashboard expenses={expenses} />
        )}

        {activeTab === 'list' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <h1 className="text-2xl font-bold text-gray-800">Le tue spese</h1>
              <button 
                onClick={() => setShowForm(true)}
                className="bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 transition-colors shadow-sm"
              >
                <Plus size={20} />
                Nuova Spesa
              </button>
            </div>
            <ExpenseList expenses={expenses} onDelete={deleteExpense} />
          </div>
        )}

        {activeTab === 'ai' && (
          <AiInsights expenses={expenses} />
        )}

        {/* Floating Action Button for Mobile */}
        <button 
          onClick={() => setShowForm(true)}
          className="fixed bottom-24 right-6 bg-emerald-500 text-white p-4 rounded-full shadow-lg lg:hidden hover:bg-emerald-600 transition-transform active:scale-95"
        >
          <Plus size={24} />
        </button>

        {/* Modal Form */}
        {showForm && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-md p-6 shadow-2xl relative">
              <button 
                onClick={() => setShowForm(false)}
                className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
              >
                ✕
              </button>
              <h2 className="text-xl font-bold mb-6 text-gray-800">Aggiungi Spesa</h2>
              <ExpenseForm onSubmit={addExpense} onCancel={() => setShowForm(false)} />
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default App;

