import React, { useMemo } from 'react';
import { Expense, Category } from '../types';
import { 
  PieChart, Pie, Cell, ResponsiveContainer, Tooltip, 
  BarChart, Bar, XAxis, YAxis, CartesianGrid 
} from 'recharts';
import { TrendingDown, TrendingUp, Wallet, Calendar } from 'lucide-react';
import { format, startOfMonth, endOfMonth, isWithinInterval, subMonths } from 'date-fns';
import { it } from 'date-fns/locale';

interface DashboardProps {
  expenses: Expense[];
}

export const Dashboard: React.FC<DashboardProps> = ({ expenses }) => {
  const currentMonth = new Date();
  const currentMonthStart = startOfMonth(currentMonth);
  const currentMonthEnd = endOfMonth(currentMonth);

  const currentMonthExpenses = useMemo(() => {
    return expenses.filter(e => 
      isWithinInterval(new Date(e.date), { start: currentMonthStart, end: currentMonthEnd })
    );
  }, [expenses]);

  const totalCurrentMonth = currentMonthExpenses.reduce((sum, e) => sum + e.amount, 0);

  const lastMonthStart = startOfMonth(subMonths(currentMonth, 1));
  const lastMonthEnd = endOfMonth(subMonths(currentMonth, 1));
  const totalLastMonth = expenses
    .filter(e => isWithinInterval(new Date(e.date), { start: lastMonthStart, end: lastMonthEnd }))
    .reduce((sum, e) => sum + e.amount, 0);

  const diff = totalLastMonth > 0 ? ((totalCurrentMonth - totalLastMonth) / totalLastMonth) * 100 : 0;

  const categoryData = useMemo(() => {
    const data: Record<string, number> = {};
    currentMonthExpenses.forEach(e => {
      data[e.category] = (data[e.category] || 0) + e.amount;
    });
    return Object.entries(data).map(([name, value]) => ({ name, value }));
  }, [currentMonthExpenses]);

  const COLORS = [
    '#10b981', '#34d399', '#6ee7b7', '#a7f3d0', 
    '#059669', '#047857', '#065f46', '#064e3b'
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row gap-4">
        {/* Main Stats Card */}
        <div className="flex-1 bg-emerald-500 p-8 rounded-[2rem] text-white shadow-xl shadow-emerald-200/50 relative overflow-hidden">
          <div className="absolute -right-8 -top-8 w-32 h-32 bg-white/10 rounded-full blur-3xl"></div>
          <div className="absolute -left-8 -bottom-8 w-32 h-32 bg-white/10 rounded-full blur-3xl"></div>

          <div className="flex justify-between items-start mb-6">
            <div>
              <p className="text-emerald-50 text-sm font-medium uppercase tracking-wider">Totale Mensile</p>
              <h2 className="text-4xl font-bold mt-1">€{totalCurrentMonth.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</h2>
            </div>
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm">
              <Wallet size={24} />
            </div>
          </div>

          <div className="flex items-center gap-4 text-emerald-50">
            <div className={`flex items-center gap-1 text-sm font-bold px-3 py-1 rounded-full ${diff <= 0 ? 'bg-emerald-400' : 'bg-red-400'}`}>
              {diff <= 0 ? <TrendingDown size={14} /> : <TrendingUp size={14} />}
              {Math.abs(diff).toFixed(1)}%
            </div>
            <span className="text-sm opacity-80">rispetto a {format(subMonths(currentMonth, 1), 'MMMM', { locale: it })}</span>
          </div>
        </div>

        {/* Date Card */}
        <div className="bg-white p-8 rounded-[2rem] border border-emerald-100 flex flex-col justify-center gap-2 min-w-[200px]">
          <div className="text-emerald-600 bg-emerald-50 self-start p-3 rounded-2xl">
            <Calendar size={24} />
          </div>
          <p className="text-gray-500 text-sm">Oggi è il</p>
          <p className="text-xl font-bold text-gray-800">{format(currentMonth, "d MMMM yyyy", { locale: it })}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Category breakdown */}
        <div className="bg-white p-6 rounded-[2rem] border border-emerald-100 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 mb-6 px-2">Ripartizione Categorie</h3>
          <div className="h-64">
            {categoryData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={categoryData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    {categoryData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip 
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                  />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex items-center justify-center text-gray-400">
                Nessun dato per questo mese
              </div>
            )}
          </div>
          <div className="mt-4 grid grid-cols-2 gap-2">
            {categoryData.map((entry, index) => (
              <div key={entry.name} className="flex items-center gap-2 text-xs">
                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                <span className="text-gray-600 truncate">{entry.name}</span>
                <span className="font-bold text-gray-800 ml-auto">€{entry.value.toFixed(0)}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Weekly Trend */}
        <div className="bg-white p-6 rounded-[2rem] border border-emerald-100 shadow-sm">
           <h3 className="text-lg font-bold text-gray-800 mb-6 px-2">Trend Settimanale</h3>
           <div className="h-64">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={categoryData.slice(0, 5)}>
                 <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                 <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#64748b' }} />
                 <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#64748b' }} />
                 <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} />
                 <Bar dataKey="value" fill="#10b981" radius={[10, 10, 0, 0]} />
               </BarChart>
             </ResponsiveContainer>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Category, Expense } from '../types';
import { SmartCategorizer } from './SmartCategorizer';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => void;
  onCancel: () => void;
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ onSubmit, onCancel }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<Category>(Category.Altro);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    onSubmit({
      description,
      amount: parseFloat(amount),
      category,
      date
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">Descrizione</label>
        <input
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Cosa hai comprato?"
          className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition-all outline-none"
          required
        />
        <SmartCategorizer description={description} onSuggest={setCategory} />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Importo (€)</label>
          <input
            type="number"
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="0.00"
            className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition-all outline-none"
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Data</label>
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition-all outline-none"
            required
          />
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">Categoria</label>
        <select
          value={category}
          onChange={(e) => setCategory(e.target.value as Category)}
          className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition-all outline-none bg-white appearance-none"
        >
          {Object.values(Category).map((cat) => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      <div className="flex gap-3 pt-4">
        <button
          type="button"
          onClick={onCancel}
          className="flex-1 px-4 py-3 rounded-xl border border-gray-200 text-gray-600 font-medium hover:bg-gray-50 transition-colors"
        >
          Annulla
        </button>
        <button
          type="submit"
          className="flex-1 px-4 py-3 rounded-xl bg-emerald-500 text-white font-bold hover:bg-emerald-600 transition-all shadow-lg shadow-emerald-100"
        >
          Salva
        </button>
      </div>
    </form>
  );
};

import React, { useEffect, useState } from 'react';
import { Category } from '../types';
import { Sparkles } from 'lucide-react';

interface SmartCategorizerProps {
  description: string;
  onSuggest: (category: Category) => void;
}

export const SmartCategorizer: React.FC<SmartCategorizerProps> = ({ description, onSuggest }) => {
  const [suggestion, setSuggestion] = useState<Category | null>(null);

  useEffect(() => {
    if (description.length < 3) {
      setSuggestion(null);
      return;
    }

    const d = description.toLowerCase();
    let suggested: Category | null = null;

    if (d.includes('pizza') || d.includes('pasta') || d.includes('spesa') || d.includes('conad') || d.includes('esselunga') || d.includes('cibo')) {
      suggested = Category.Alimentari;
    } else if (d.includes('benzina') || d.includes('treno') || d.includes('bus') || d.includes('taxi') || d.includes('parcheggio')) {
      suggested = Category.Trasporti;
    } else if (d.includes('affitto') || d.includes('mutuo') || d.includes('mobili') || d.includes('ikea')) {
      suggested = Category.Casa;
    } else if (d.includes('netflix') || d.includes('cinema') || d.includes('bar') || d.includes('aperitivo') || d.includes('birra')) {
      suggested = Category.Svago;
    } else if (d.includes('luce') || d.includes('gas') || d.includes('acqua') || d.includes('bolletta') || d.includes('internet')) {
      suggested = Category.Utenze;
    } else if (d.includes('vestiti') || d.includes('amazon') || d.includes('scarpe')) {
      suggested = Category.Shopping;
    } else if (d.includes('farmacia') || d.includes('dentista') || d.includes('visita')) {
      suggested = Category.Salute;
    }

    setSuggestion(suggested);
  }, [description]);

  if (!suggestion) return null;

  return (
    <div 
      onClick={() => onSuggest(suggestion)}
      className="mt-2 flex items-center gap-2 text-xs text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-lg cursor-pointer hover:bg-emerald-100 transition-colors border border-emerald-100 animate-in slide-in-from-top-1"
    >
      <Sparkles size={12} />
      <span>Sugerimento AI: <strong>{suggestion}</strong>. Clicca per impostare.</span>
    </div>
  );
};

import React, { useState } from 'react';
import { Expense, Category } from '../types';
import { Trash2, Search, Filter } from 'lucide-react';
import { format } from 'date-fns';
import { it } from 'date-fns/locale';

interface ExpenseListProps {
  expenses: Expense[];
  onDelete: (id: string) => void;
}

export const ExpenseList: React.FC<ExpenseListProps> = ({ expenses, onDelete }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<Category | 'Tutti'>('Tutti');

  const filteredExpenses = expenses.filter(e => {
    const matchesSearch = e.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'Tutti' || e.category === filterCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row gap-4 mb-6">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            placeholder="Cerca tra le spese..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
          />
        </div>
        <div className="relative min-w-[160px]">
          <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <select
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value as any)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all bg-white appearance-none"
          >
            <option value="Tutti">Tutte le Categorie</option>
            {Object.values(Category).map(cat => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] border border-emerald-100 overflow-hidden shadow-sm">
        {filteredExpenses.length > 0 ? (
          <div className="divide-y divide-emerald-50">
            {filteredExpenses.map((expense) => (
              <div key={expense.id} className="group p-4 flex items-center justify-between hover:bg-emerald-50/50 transition-colors">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 rounded-2xl bg-emerald-100 flex items-center justify-center text-emerald-600 font-bold">
                    {expense.category.charAt(0)}
                  </div>
                  <div>
                    <h4 className="font-semibold text-gray-800">{expense.description}</h4>
                    <div className="flex items-center gap-2 text-xs text-gray-500">
                      <span className="bg-white px-2 py-0.5 rounded border border-gray-100">{expense.category}</span>
                      <span>•</span>
                      <span>{format(new Date(expense.date), 'dd MMM yyyy', { locale: it })}</span>
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <span className="font-bold text-gray-800 text-lg">
                    €{expense.amount.toLocaleString('it-IT', { minimumFractionDigits: 2 })}
                  </span>
                  <button 
                    onClick={() => onDelete(expense.id)}
                    className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-12 text-center flex flex-col items-center gap-4">
            <div className="bg-emerald-50 p-4 rounded-full text-emerald-200">
              <Search size={48} />
            </div>
            <p className="text-gray-500">Nessuna spesa trovata. Prova a cambiare i filtri.</p>
          </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { Expense } from "../types";

export const getGeminiInsights = async (expenses: Expense[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const expenseSummary = expenses.map(e => ({
