import React, { useState, useEffect } from 'react';
import { Category, Expense } from '../types';
import { SmartCategorizer } from './SmartCategorizer';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => void;
  onCancel: () => void;
  initialData?: Partial<Expense>;
  currency?: string;
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ onSubmit, onCancel, initialData, currency = '€' }) => {
  const [description, setDescription] = useState(initialData?.description || '');
  const [amount, setAmount] = useState(initialData?.amount?.toString() || '');
  const [category, setCategory] = useState<Category>(initialData?.category || Category.Altro);
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);

  useEffect(() => {
    if (initialData) {
      if (initialData.description) setDescription(initialData.description);
      if (initialData.amount) setAmount(initialData.amount.toString());
      if (initialData.category) setCategory(initialData.category);
      if (initialData.date) setDate(initialData.date);
    }
  }, [initialData]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    onSubmit({
      description,
      amount: parseFloat(amount),
      category,
      date
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Cosa hai comprato?</label>
        <input
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="es. Spesa Settimanale"
          className="w-full px-5 py-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-emerald-500 focus:bg-white transition-all outline-none font-medium"
          required
        />
        <SmartCategorizer description={description} onSuggest={setCategory} />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Quanto ({currency})</label>
          <input
            type="number"
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="0.00"
            className="w-full px-5 py-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-emerald-500 focus:bg-white transition-all outline-none font-bold text-emerald-600"
            required
          />
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Quando</label>
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            className="w-full px-5 py-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-emerald-500 focus:bg-white transition-all outline-none font-medium"
            required
          />
        </div>
      </div>

      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Categoria</label>
        <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto p-1">
          {Object.values(Category).map((cat) => (
            <button
              key={cat}
              type="button"
              onClick={() => setCategory(cat)}
              className={`px-4 py-3 rounded-xl text-sm font-semibold transition-all border-2 ${
                category === cat 
                  ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' 
                  : 'bg-white border-emerald-50 text-gray-500 hover:border-emerald-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="flex gap-4 pt-4">
        <button
          type="button"
          onClick={onCancel}
          className="flex-1 px-6 py-4 rounded-2xl border-2 border-gray-100 text-gray-400 font-bold hover:bg-gray-50 transition-all"
        >
          Cancella
        </button>
        <button
          type="submit"
          className="flex-1 px-6 py-4 rounded-2xl bg-emerald-500 text-white font-bold hover:bg-emerald-600 transition-all shadow-xl shadow-emerald-100"
        >
          Salva
        </button>
      </div>
    </form>
  );
};

import React, { useState } from 'react';
import { Expense, Category } from '../types';
import { Trash2, Search, Filter } from 'lucide-react';
import { format } from 'date-fns';
import { it } from 'date-fns/locale';

interface ExpenseListProps {
  expenses: Expense[];
  onDelete: (id: string) => void;
  currency?: string;
}

export const ExpenseList: React.FC<ExpenseListProps> = ({ expenses, onDelete, currency = '€' }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<Category | 'Tutti'>('Tutti');

  const filteredExpenses = expenses.filter(e => {
    const matchesSearch = e.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === 'Tutti' || e.category === filterCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row gap-4 mb-6">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            placeholder="Cerca tra le spese..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
          />
        </div>
        <div className="relative min-w-[160px]">
          <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <select
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value as any)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all bg-white appearance-none"
          >
            <option value="Tutti">Tutte le Categorie</option>
            {Object.values(Category).map(cat => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] border border-emerald-100 overflow-hidden shadow-sm">
        {filteredExpenses.length > 0 ? (
          <div className="divide-y divide-emerald-50">
            {filteredExpenses.map((expense) => (
              <div key={expense.id} className="group p-4 flex items-center justify-between hover:bg-emerald-50/50 transition-colors">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 rounded-2xl bg-emerald-100 flex items-center justify-center text-emerald-600 font-bold">
                    {expense.category.charAt(0)}
                  </div>
                  <div>
                    <h4 className="font-semibold text-gray-800">{expense.description}</h4>
                    <div className="flex items-center gap-2 text-xs text-gray-500">
                      <span className="bg-white px-2 py-0.5 rounded border border-gray-100">{expense.category}</span>
                      <span>•</span>
                      <span>{format(new Date(expense.date), 'dd MMM yyyy', { locale: it })}</span>
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <span className="font-bold text-gray-800 text-lg">
                    {currency}{expense.amount.toLocaleString('it-IT', { minimumFractionDigits: 2 })}
                  </span>
                  <button 
                    onClick={() => onDelete(expense.id)}
                    className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-12 text-center flex flex-col items-center gap-4">
            <div className="bg-emerald-50 p-4 rounded-full text-emerald-200">
              <Search size={48} />
            </div>
            <p className="text-gray-500">Nessuna spesa trovata. Prova a cambiare i filtri.</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { ReceiptScanner } from './components/ReceiptScanner';
import { SettingsView } from './components/SettingsView';
import { Expense, Category, UserSettings } from './types';
import { Plus, ScanLine, Settings as SettingsIcon } from 'lucide-react';

const App: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('mintflow_expenses');
    return saved ? JSON.parse(saved) : [];
  });

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    return saved ? JSON.parse(saved) : {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€'
    };
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ai' | 'settings'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [showQuickBudget, setShowQuickBudget] = useState(false);

  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  useEffect(() => {
    localStorage.setItem('mintflow_expenses', JSON.stringify(expenses));
  }, [expenses]);

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
  }, [userSettings]);

  const addExpense = (expense: Omit<Expense, 'id'>) => {
    const newExpense = { ...expense, id: crypto.randomUUID() };
    setExpenses(prev => [newExpense, ...prev]);
    setShowForm(false);
    setPrefill(null);
  };

  const handleReceiptDetected = (data: { description: string; amount: number; category: Category }) => {
    setPrefill({
      description: data.description,
      amount: data.amount,
      category: data.category,
      date: new Date().toISOString().split('T')[0]
    });
    setShowScanner(false);
    setShowForm(true);
  };

  const deleteExpense = (id: string) => {
    setExpenses(prev => prev.filter(e => e.id !== id));
  };

  const handleClearData = () => {
    if (confirm('Sei sicuro di voler cancellare tutte le spese? Questa azione non è reversibile.')) {
      setExpenses([]);
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {/* Header Section - Hidden on Dashboard as it has its own greeting */}
        {activeTab !== 'dashboard' && (
          <div className="flex justify-between items-center mb-6">
            <div>
               <h1 className="text-3xl font-bold text-gray-900">
                 {activeTab === 'list' ? 'Le tue Spese' : 
                  activeTab === 'ai' ? 'AI Insights' : 'Impostazioni'}
               </h1>
               <p className="text-gray-500 text-sm">
                 {activeTab === 'settings' ? 'Personalizza la tua esperienza' : 'Gestione finanziaria intelligente'}
               </p>
            </div>
            {activeTab === 'settings' && (
              <div className="flex gap-2">
                <button 
                  onClick={() => setShowQuickBudget(!showQuickBudget)}
                  className="p-3 bg-white border border-emerald-100 text-emerald-600 rounded-2xl hover:bg-emerald-50 transition-colors shadow-sm"
                >
                  <SettingsIcon size={20} />
                </button>
              </div>
            )}
          </div>
        )}

        {showQuickBudget && activeTab === 'settings' && (
          <div className="mb-8 bg-white p-6 rounded-[2rem] border-2 border-emerald-100 animate-in slide-in-from-top-4">
            <h3 className="font-bold text-gray-800 mb-4">Modifica Budget Rapida</h3>
            <div className="flex gap-4">
              <input 
                type="number"
                value={userSettings.monthlyBudget}
                onChange={(e) => setUserSettings({...userSettings, monthlyBudget: Number(e.target.value)})}
                className="flex-1 px-4 py-2 border rounded-xl outline-none focus:ring-2 focus:ring-emerald-500"
              />
              <button 
                onClick={() => setShowQuickBudget(false)}
                className="bg-emerald-500 text-white px-6 py-2 rounded-xl font-bold"
              >
                Chiudi
              </button>
            </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <Dashboard 
            expenses={expenses} 
            budget={userSettings.monthlyBudget} 
            userName={userSettings.name}
            currency={userSettings.currency}
          />
        )}

        {activeTab === 'list' && (
          <div className="space-y-6">
            <div className="flex gap-3">
              <button 
                onClick={() => { setPrefill(null); setShowForm(true); }}
                className="flex-1 bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-emerald-200"
              >
                <Plus size={20} />
                <span className="font-bold">Aggiungi</span>
              </button>
              <button 
                onClick={() => setShowScanner(true)}
                className="flex-1 bg-white border-2 border-emerald-100 text-emerald-600 px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all hover:bg-emerald-50 shadow-sm"
              >
                <ScanLine size={20} />
                <span className="font-bold">Scansiona</span>
              </button>
            </div>
            <ExpenseList expenses={expenses} onDelete={deleteExpense} currency={userSettings.currency} />
          </div>
        )}

        {activeTab === 'ai' && (
          <AiInsights expenses={expenses} />
        )}

        {activeTab === 'settings' && (
          <SettingsView 
            settings={userSettings} 
            onUpdate={setUserSettings}
            onClearData={handleClearData}
            expenseCount={expenses.length}
          />
        )}

        {/* Modals */}
        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4 overflow-y-auto">
            <div className="bg-white rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl relative my-auto animate-in zoom-in-95 duration-200">
              <button onClick={() => setShowForm(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600">✕</button>
              <h2 className="text-2xl font-bold mb-6 text-gray-800">Dettagli Spesa</h2>
              <ExpenseForm 
                onSubmit={addExpense} 
                onCancel={() => setShowForm(false)} 
                initialData={prefill || undefined}
                currency={userSettings.currency}
              />
            </div>
          </div>
        )}

        {showScanner && (
          <ReceiptScanner 
            onDetected={handleReceiptDetected} 
            onClose={() => setShowScanner(false)} 
          />
        )}
      </div>
    </Layout>
  );
};

export default App;

