        <button 
          onClick={fetchInsights}
          disabled={loading}
          className="p-3 bg-emerald-50 dark:bg-gray-800 text-emerald-600 dark:text-emerald-400 rounded-xl hover:bg-emerald-100 dark:hover:bg-gray-700 transition-colors disabled:opacity-50"
