               <h1 className="text-3xl font-bold text-gray-900 dark:text-white transition-colors">
                 {activeTab === 'list' ? 'Le tue Spese' : 
                  activeTab === 'ai' ? 'AI Insights' : 'Impostazioni'}
               </h1>
               <p className="text-gray-500 dark:text-gray-400 text-sm transition-colors">
                 {activeTab === 'settings' ? 'Personalizza la tua esperienza' : 'Gestione finanziaria intelligente'}
               </p>
            </div>
            {activeTab === 'settings' && (
              <div className="flex gap-2">
                <button 
                  onClick={() => setShowQuickBudget(!showQuickBudget)}
                  className="p-3 bg-white dark:bg-gray-800 border border-emerald-100 dark:border-gray-700 text-emerald-600 dark:text-emerald-400 rounded-2xl hover:bg-emerald-50 dark:hover:bg-gray-700 transition-colors shadow-sm"
                >
                  <SettingsIcon size={20} />
