    try {
      if (isLogin) {
        await auth.signIn(email, password);
        onSuccess();
      } else {
        await auth.signUp(email, password, username);
        setSignedUpEmail(email);
      }
    } catch (err: any) {
      if (err.message?.includes('Email not confirmed')) {
        setError("Devi confermare la tua email prima di accedere.");
