        <button
          type="submit"
          className="flex-1 px-6 py-4 rounded-2xl bg-emerald-500 text-white font-bold hover:bg-emerald-600 transition-all shadow-xl shadow-emerald-100 dark:shadow-none"
        >
          Salva
        </button>
      </div>
    </form>
  );
};

