import React from 'react';
import { UserSettings, Expense } from '../types';
import { User, Wallet, DollarSign, Trash2, Download, Info, Moon, Sun, LogOut, FileDown, Edit3 } from 'lucide-react';
import { auth } from '../services/supabase';
import { format } from 'date-fns';

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  expenses,
  email
}) => {
  const handleChange = (field: keyof UserSettings, value: any) => {
    onUpdate({ ...settings, [field]: value });
  };

  const handleRechargeLabelChange = (key: keyof UserSettings['rechargeLabels'], value: string) => {
    onUpdate({
      ...settings,
      rechargeLabels: {
        ...settings.rechargeLabels,
        [key]: value
      }
    });
  };

  const handleLogout = async () => {
    if (confirm('Sei sicuro di voler uscire?')) {
      await auth.signOut();
    }
  };

  const handleExportCSV = () => {
    if (expenses.length === 0) {
      alert("Non ci sono spese da esportare.");
      return;
    }

    // Header del CSV
    const headers = ["Data", "Descrizione", "Categoria", "Metodo Pagamento", "Importo (" + settings.currency + ")"];

    // Righe del CSV
    const rows = expenses.map(e => [
      format(new Date(e.date), 'yyyy-MM-dd'),
      `"${e.description.replace(/"/g, '""')}"`, // Gestione virgolette nella descrizione
      e.category,
      e.paymentMethod || "Non specificato",
      e.amount.toFixed(2).replace('.', ',') // Formato decimale europeo per Excel
    ]);

    const csvContent = [
      headers.join(";"), 
      ...rows.map(r => r.join(";"))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    const timestamp = format(new Date(), 'yyyyMMdd_HHmm');

    link.setAttribute("href", url);
    link.setAttribute("download", `mintflow_export_${timestamp}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {/* Account Section */}
