export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

// Helper per ottenere l'URL di redirect corretto in base all'ambiente
const getRedirectUrl = () => {
  return window.location.origin;
};

export const auth = {
  async signUp(email: string, password: string, username: string) {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { display_name: username },
        emailRedirectTo: getRedirectUrl(),
      }
    });
    if (error) throw error;
    return data;
  },

  async resendConfirmation(email: string) {
    const { error } = await supabase.auth.resend({
      type: 'signup',
      email: email,
      options: {
        emailRedirectTo: getRedirectUrl(),
      }
    });
    if (error) throw error;
  },

  async signIn(email: string, password: string) {
    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    if (error) throw error;
    return data;
  },

  async signOut() {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  },

  async getCurrentUser() {
    const { data: { user } } = await supabase.auth.getUser();
    return user;
  }
};

export const db = {
  async getExpenses(userId: string): Promise<Expense[]> {
    const { data, error } = await supabase
      .from('expenses')
      .select('*')
      .eq('user_id', userId)
      .order('date', { ascending: false });

    if (error) throw error;
    return data || [];
  },

  async addExpense(expense: Omit<Expense, 'id'>, userId: string): Promise<Expense> {
    const { data, error } = await supabase
      .from('expenses')
      .insert([{ ...expense, user_id: userId }])
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async updateExpense(id: string, expense: Partial<Omit<Expense, 'id'>>): Promise<Expense> {
    // Filtriamo l'oggetto per inviare solo chiavi che hanno un valore definito
    const updateData: any = {};
    if (expense.description !== undefined) updateData.description = expense.description;
    if (expense.amount !== undefined) updateData.amount = expense.amount;
    if (expense.category !== undefined) updateData.category = expense.category;
    if (expense.paymentMethod !== undefined) updateData.paymentMethod = expense.paymentMethod;
    if (expense.date !== undefined) updateData.date = expense.date;

    const { data, error } = await supabase
      .from('expenses')
      .update(updateData)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async deleteExpense(id: string): Promise<void> {
    const { error } = await supabase
      .from('expenses')
      .delete()
      .eq('id', id);

    if (error) throw error;
  },

  async clearAll(userId: string): Promise<void> {
    const { error } = await supabase
      .from('expenses')
      .delete()
      .eq('user_id', userId); 

    if (error) throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Category, Expense, PaymentMethod } from '../types';
import { SmartCategorizer } from './SmartCategorizer';
import { Wallet, CreditCard, Banknote, Fuel, Loader2, Save } from 'lucide-react';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => Promise<void> | void;
  onCancel: () => void;
  initialData?: Partial<Expense>;
  currency?: string;
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ onSubmit, onCancel, initialData, currency = '€' }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<Category>(Category.Altro);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.Contanti);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Sincronizzazione con i dati iniziali
  useEffect(() => {
    if (initialData) {
      if (initialData.description !== undefined) setDescription(initialData.description);
      if (initialData.amount !== undefined) setAmount(initialData.amount.toString());
      if (initialData.category !== undefined) setCategory(initialData.category);
      if (initialData.paymentMethod !== undefined) setPaymentMethod(initialData.paymentMethod);
      if (initialData.date !== undefined) setDate(initialData.date);
    }
  }, [initialData]);

  const handleFormSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (isSubmitting) return;

    // Validazione manuale
    const cleanDesc = description.trim();
    if (!cleanDesc) {
      alert("La descrizione è obbligatoria.");
      return;
    }

    const parsedAmount = parseFloat(amount.replace(',', '.'));
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      alert("Inserisci un importo valido (es: 10.50).");
      return;
    }

    setIsSubmitting(true);
    try {
      await onSubmit({
        description: cleanDesc,
        amount: parsedAmount,
        category,
        paymentMethod,
        date
      });
    } catch (err) {
      console.error("Errore durante l'invio del form:", err);
      // Lo stato isSubmitting viene resettato nel finally di App.tsx o qui
    } finally {
      setIsSubmitting(false);
    }
  };

  const getPaymentIcon = (method: PaymentMethod) => {
    switch (method) {
      case PaymentMethod.Contanti: return <Banknote size={16} />;
      case PaymentMethod.Flash: return <CreditCard size={16} />;
      case PaymentMethod.Revolut: return <Wallet size={16} />;
      case PaymentMethod.AppQ8: return <Fuel size={16} />;
      default: return <CreditCard size={16} />;
    }
  };

  return (
    <div className="space-y-5">
      <form onSubmit={handleFormSubmit} className="space-y-5">
        <div>
          <label className="block text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Cosa hai comprato?</label>
          <input
            type="text"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="es. Spesa Settimanale"
            className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:focus:border-emerald-500 focus:bg-white dark:focus:bg-gray-700 dark:text-white transition-all outline-none font-medium"
            autoFocus
          />
          <SmartCategorizer description={description} onSuggest={setCategory} />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Quanto ({currency})</label>
            <input
              type="text"
              inputMode="decimal"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="0.00"
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:focus:border-emerald-500 focus:bg-white dark:focus:bg-gray-700 dark:text-emerald-400 transition-all outline-none font-bold"
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Quando</label>
            <input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:focus:border-emerald-500 focus:bg-white dark:focus:bg-gray-700 dark:text-white transition-all outline-none font-medium"
            />
          </div>
        </div>

        <div>
          <label className="block text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Metodo di Pagamento</label>
          <div className="grid grid-cols-2 gap-2">
            {Object.values(PaymentMethod).map((method) => (
              <button
                key={method}
                type="button"
                onClick={() => setPaymentMethod(method)}
                className={`flex items-center justify-center gap-2 px-3 py-3 rounded-xl text-[10px] font-bold transition-all border-2 ${
                  paymentMethod === method 
                    ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' 
                    : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500 dark:text-gray-400 hover:border-emerald-200 dark:hover:border-emerald-900'
                }`}
              >
                {getPaymentIcon(method)}
                <span className="whitespace-nowrap">{method}</span>
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="block text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Categoria</label>
          <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto p-1 custom-scrollbar">
            {Object.values(Category).map((cat) => (
              <button
                key={cat}
                type="button"
                onClick={() => setCategory(cat)}
                className={`px-4 py-3 rounded-xl text-sm font-semibold transition-all border-2 ${
                  category === cat 
                    ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' 
                    : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500 dark:text-gray-400 hover:border-emerald-200 dark:hover:border-emerald-900'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex gap-4 pt-2">
          <button
            type="button"
            onClick={onCancel}
            disabled={isSubmitting}
            className="flex-1 px-6 py-4 rounded-2xl border-2 border-gray-100 dark:border-gray-700 text-gray-400 dark:text-gray-500 font-bold hover:bg-gray-50 dark:hover:bg-gray-700 transition-all disabled:opacity-50"
          >
            Annulla
          </button>
          <button
            type="submit"
            disabled={isSubmitting}
            className="flex-1 px-6 py-4 rounded-2xl bg-emerald-500 text-white font-bold hover:bg-emerald-600 transition-all shadow-xl shadow-emerald-100 dark:shadow-none disabled:opacity-70 flex items-center justify-center gap-2"
          >
            {isSubmitting ? (
              <Loader2 className="animate-spin" size={20} />
            ) : (
              <>
                <Save size={20} />
                Salva
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { UserSettings, Expense } from '../types';
import { User, Wallet, DollarSign, Trash2, Download, Info, Moon, Sun, LogOut, FileDown, Edit3, Save, CheckCircle2 } from 'lucide-react';
import { auth } from '../services/supabase';
import { format } from 'date-fns';

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  expenses,
  email
}) => {
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [localSettings, setLocalSettings] = useState(settings);
  const [saveFeedback, setSaveFeedback] = useState(false);

  const handleLocalChange = (field: keyof UserSettings, value: any) => {
    setLocalSettings({ ...localSettings, [field]: value });
  };

  const handleRechargeLabelChange = (key: keyof UserSettings['rechargeLabels'], value: string) => {
    const updated = {
      ...localSettings,
      rechargeLabels: {
        ...localSettings.rechargeLabels,
        [key]: value
      }
    };
    setLocalSettings(updated);
    // Le etichette ricarica le salviamo subito per comodità, o possiamo aspettare il tasto salva
    onUpdate(updated);
  };

  const saveProfile = () => {
    onUpdate(localSettings);
    setIsEditingProfile(false);
    setSaveFeedback(true);
    setTimeout(() => setSaveFeedback(false), 2000);
  };

  const toggleAppearance = () => {
    const updated = { ...settings, isDarkMode: !settings.isDarkMode };
    onUpdate(updated);
    setLocalSettings(updated);
  };

  const handleLogout = async () => {
    if (confirm('Sei sicuro di voler uscire?')) {
      await auth.signOut();
    }
  };

  const handleExportCSV = () => {
    if (expenses.length === 0) {
      alert("Non ci sono spese da esportare.");
      return;
    }

    const headers = ["Data", "Descrizione", "Categoria", "Metodo Pagamento", "Importo (" + settings.currency + ")"];
    const rows = expenses.map(e => [
      format(new Date(e.date), 'yyyy-MM-dd'),
      `"${e.description.replace(/"/g, '""')}"`,
      e.category,
      e.paymentMethod || "Non specificato",
      e.amount.toFixed(2).replace('.', ',')
    ]);

    const csvContent = [
      headers.join(";"), 
      ...rows.map(r => r.join(";"))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    const timestamp = format(new Date(), 'yyyyMMdd_HHmm');

    link.setAttribute("href", url);
    link.setAttribute("download", `mintflow_export_${timestamp}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {/* Account Section */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <div className="flex justify-between items-start mb-6">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white flex items-center gap-2">
            <User className="text-emerald-500" size={20} />
            Il tuo Profilo
          </h3>
          <div className="flex gap-2">
            {!isEditingProfile ? (
              <button 
                onClick={() => setIsEditingProfile(true)}
                className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20 rounded-xl hover:bg-emerald-100 transition-colors"
              >
                <Edit3 size={14} />
                Modifica
              </button>
            ) : (
              <button 
                onClick={saveProfile}
                className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-white bg-emerald-500 rounded-xl hover:bg-emerald-600 transition-colors shadow-lg shadow-emerald-100"
              >
                <Save size={14} />
                Salva
              </button>
            )}
            <button 
              onClick={handleLogout}
              className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-red-500 hover:bg-red-50 dark:hover:bg-red-900/10 rounded-xl transition-colors"
            >
              <LogOut size={14} />
              Esci
            </button>
          </div>
        </div>

        {saveFeedback && (
          <div className="mb-4 p-3 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-xl flex items-center gap-2 animate-in fade-in slide-in-from-top-2">
            <CheckCircle2 size={16} />
            <span className="text-xs font-bold uppercase tracking-wider">Profilo aggiornato con successo!</span>
          </div>
        )}

        <div className="space-y-4">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-1 ml-1">Email Account</label>
            <p className="px-5 py-3 rounded-2xl bg-gray-50 dark:bg-gray-700/50 text-gray-400 dark:text-gray-500 font-medium truncate text-sm border border-transparent">
              {email}
            </p>
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Nome Visualizzato</label>
            <input
              type="text"
              disabled={!isEditingProfile}
              value={localSettings.name}
              onChange={(e) => handleLocalChange('name', e.target.value)}
              className={`w-full px-5 py-3 rounded-2xl transition-all outline-none font-medium border-2 ${
                isEditingProfile 
                  ? 'bg-white dark:bg-gray-700 border-emerald-500 text-gray-800 dark:text-white' 
                  : 'bg-gray-50 dark:bg-gray-700/50 border-transparent text-gray-500'
              }`}
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Budget Mensile Target</label>
            <div className="relative">
              <input
                type="number"
                disabled={!isEditingProfile}
                value={localSettings.monthlyBudget}
                onChange={(e) => handleLocalChange('monthlyBudget', Number(e.target.value))}
                className={`w-full pl-12 pr-5 py-3 rounded-2xl transition-all outline-none font-bold border-2 ${
                  isEditingProfile 
                    ? 'bg-white dark:bg-gray-700 border-emerald-500 text-gray-800 dark:text-white' 
                    : 'bg-gray-50 dark:bg-gray-700/50 border-transparent text-gray-500'
                }`}
              />
              <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">
                {settings.currency}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Finance Prefs Section */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
          <Wallet className="text-emerald-500" size={20} />
          Preferenze Finanziarie
        </h3>
        <div className="mb-8">
            <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Valuta Principale</label>
            <div className="relative">
              <select
                value={settings.currency}
                onChange={(e) => onUpdate({ ...settings, currency: e.target.value })}
                className="w-full pl-12 pr-5 py-3 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:focus:border-emerald-500 focus:bg-white dark:focus:bg-gray-700 dark:text-white transition-all outline-none font-bold appearance-none cursor-pointer"
              >
                <option value="€">Euro (€)</option>
                <option value="$">Dollaro ($)</option>
                <option value="£">Sterlina (£)</option>
                <option value="CHF">Franco Svizzero (CHF)</option>
              </select>
              <DollarSign className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            </div>
        </div>

        {/* Recharge Menu Customization */}
        <div className="pt-6 border-t border-emerald-50 dark:border-gray-700">
          <h4 className="text-sm font-bold text-gray-800 dark:text-white mb-4 flex items-center gap-2">
            <Edit3 className="text-emerald-500" size={16} />
            Etichette Menu Ricariche
          </h4>
          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-1 ml-1">Slot 1 (Flash)</label>
              <input
                type="text"
                value={localSettings.rechargeLabels.flash}
                onChange={(e) => handleRechargeLabelChange('flash', e.target.value)}
                placeholder="es. Prepagata Flash"
                className="w-full px-4 py-2 rounded-xl bg-gray-50 dark:bg-gray-700 border border-emerald-50 dark:border-gray-600 focus:border-emerald-500 outline-none dark:text-white transition-all text-sm font-medium"
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-1 ml-1">Slot 2 (Revolut)</label>
              <input
                type="text"
                value={localSettings.rechargeLabels.revolut}
                onChange={(e) => handleRechargeLabelChange('revolut', e.target.value)}
                placeholder="es. Prepagata Revolut"
                className="w-full px-4 py-2 rounded-xl bg-gray-50 dark:bg-gray-700 border border-emerald-50 dark:border-gray-600 focus:border-emerald-500 outline-none dark:text-white transition-all text-sm font-medium"
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-1 ml-1">Slot 3 (App Q8)</label>
              <input
                type="text"
                value={localSettings.rechargeLabels.q8}
                onChange={(e) => handleRechargeLabelChange('q8', e.target.value)}
                placeholder="es. App Q8"
                className="w-full px-4 py-2 rounded-xl bg-gray-50 dark:bg-gray-700 border border-emerald-50 dark:border-gray-600 focus:border-emerald-500 outline-none dark:text-white transition-all text-sm font-medium"
              />
            </div>
          </div>
          <p className="mt-4 text-[10px] text-gray-400 leading-tight italic">
            * I nomi personalizzati vengono usati per calcolare automaticamente il saldo residuo nella Dashboard.
          </p>
        </div>
      </div>

      {/* Appearance Section */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
          {settings.isDarkMode ? <Moon className="text-emerald-500" size={20} /> : <Sun className="text-emerald-500" size={20} />}
          Personalizzazione Visiva
        </h3>
        <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700/50 rounded-2xl">
          <span className="text-sm font-bold text-gray-700 dark:text-gray-200">Modalità Notte</span>
          <button 
            onClick={toggleAppearance}
            className={`w-14 h-8 rounded-full transition-all relative ${settings.isDarkMode ? 'bg-emerald-500' : 'bg-gray-300'}`}
          >
            <div className={`absolute top-1 w-6 h-6 rounded-full bg-white shadow-sm transition-all ${settings.isDarkMode ? 'left-7' : 'left-1'}`}></div>
          </button>
        </div>
      </div>

      {/* Data Management */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
          <Download className="text-emerald-500" size={20} />
          Esportazione e Backup
        </h3>
        <div className="space-y-4">
          <div className="flex items-center justify-between p-4 bg-emerald-50 dark:bg-emerald-900/20 rounded-2xl border border-emerald-100 dark:border-emerald-900/30">
            <div className="flex items-center gap-3">
              <Info className="text-emerald-500" size={20} />
              <div>
                <p className="text-sm font-bold text-emerald-800 dark:text-emerald-400">Database Sincronizzato</p>
                <p className="text-xs text-emerald-600 dark:text-emerald-500">{expenses.length} transazioni registrate nel cloud</p>
              </div>
            </div>
          </div>

          <button 
            onClick={handleExportCSV}
            className="w-full flex items-center justify-center gap-2 p-4 bg-white dark:bg-gray-800 text-emerald-600 dark:text-emerald-400 border-2 border-emerald-100 dark:border-gray-700 hover:bg-emerald-50 dark:hover:bg-gray-700 transition-all rounded-2xl font-bold"
          >
            <FileDown size={20} />
            Scarica Report Completo (CSV)
          </button>

          <button 
            onClick={onClearData}
            className="w-full flex items-center justify-center gap-2 p-4 text-red-500 border-2 border-red-50 dark:border-red-900/20 hover:bg-red-50 dark:hover:bg-red-900/10 transition-all rounded-2xl font-bold"
          >
            <Trash2 size={20} />
            Reset Totale (Cancella tutto)
          </button>
        </div>
      </div>

      <div className="text-center text-gray-400 text-[10px] font-bold uppercase tracking-[0.2em] py-4">
        MintFlow v1.3.1 • Sincronizzazione Attiva
      </div>
    </div>
  );
};

import { createClient } from '@supabase/supabase-js';
