// Helper per ottenere l'URL di redirect corretto in base all'ambiente
const getRedirectUrl = () => {
  return window.location.origin;
};

export const auth = {
  async signUp(email: string, password: string, username: string) {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { display_name: username },
        emailRedirectTo: getRedirectUrl(),
      }
    });
    if (error) throw error;
    return data;
  },

  async resendConfirmation(email: string) {
    const { error } = await supabase.auth.resend({
      type: 'signup',
      email: email,
      options: {
        emailRedirectTo: getRedirectUrl(),
      }
    });
    if (error) throw error;
  },

  async signIn(email: string, password: string) {
    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    if (error) throw error;
    return data;
  },

  async signOut() {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  },

  async getCurrentUser() {
    const { data: { user } } = await supabase.auth.getUser();
    return user;
  },

  async updateProfile(name: string) {
    const { data, error } = await supabase.auth.updateUser({
      data: { display_name: name }
    });
    if (error) throw error;
    return data;
  },

  async updateEmail(newEmail: string) {
    const { data, error } = await supabase.auth.updateUser({
      email: newEmail
    }, {
      emailRedirectTo: getRedirectUrl()
    });
    if (error) throw error;
    return data;
  },

  async updatePassword(password: string) {
    const { data, error } = await supabase.auth.updateUser({
      password: password
    });
    if (error) throw error;
    return data;
  }
};

export const db = {
  async getExpenses(userId: string): Promise<Expense[]> {
    const { data, error } = await supabase
      .from('expenses')
      .select('*')
      .eq('user_id', userId)
      .order('date', { ascending: false });

    if (error) throw error;
    return data || [];
  },

  async addExpense(expense: Omit<Expense, 'id'>, userId: string): Promise<Expense> {
    const { data, error } = await supabase
      .from('expenses')
      .insert([{ ...expense, user_id: userId }])
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async updateExpense(id: string, expense: Partial<Omit<Expense, 'id'>>): Promise<Expense> {
    const updateData: any = {};
    if (expense.description !== undefined) updateData.description = expense.description;
    if (expense.amount !== undefined) updateData.amount = expense.amount;
    if (expense.category !== undefined) updateData.category = expense.category;
    if (expense.paymentMethod !== undefined) updateData.paymentMethod = expense.paymentMethod;
    if (expense.date !== undefined) updateData.date = expense.date;

    const { data, error } = await supabase
      .from('expenses')
      .update(updateData)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  async deleteExpense(id: string): Promise<void> {
    const { error } = await supabase
      .from('expenses')
      .delete()
      .eq('id', id);

    if (error) throw error;
  },

  async clearAll(userId: string): Promise<void> {
    const { error } = await supabase
      .from('expenses')
      .delete()
      .eq('user_id', userId); 

    if (error) throw error;
  }
};

import React, { useState } from 'react';
import { UserSettings, Expense } from '../types';
import { User, Wallet, DollarSign, Trash2, Download, Info, Moon, Sun, LogOut, FileDown, Edit3, Save, CheckCircle2, Key, Mail, ShieldCheck } from 'lucide-react';
import { auth } from '../services/supabase';
import { format } from 'date-fns';

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  expenses,
  email
}) => {
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isChangingPassword, setIsChangingPassword] = useState(false);

  const [localSettings, setLocalSettings] = useState(settings);
  const [localEmail, setLocalEmail] = useState(email || '');
  const [newPassword, setNewPassword] = useState('');

  const [feedback, setFeedback] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [loading, setLoading] = useState(false);

  const handleLocalChange = (field: keyof UserSettings, value: any) => {
    setLocalSettings({ ...localSettings, [field]: value });
  };

  const showFeedback = (msg: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ msg, type });
    setTimeout(() => setFeedback(null), 3000);
  };

  const saveProfile = async () => {
    setLoading(true);
    try {
      // 1. Update Username in Metadata
      if (localSettings.name !== settings.name) {
        await auth.updateProfile(localSettings.name);
      }

      // 2. Update Email if changed
      if (localEmail !== email) {
        await auth.updateEmail(localEmail);
        showFeedback("Email inviata per la conferma del nuovo indirizzo.");
      }

      // Sync settings to parent
      onUpdate(localSettings);
      setIsEditingProfile(false);
      showFeedback("Profilo aggiornato con successo!");
    } catch (err: any) {
      showFeedback(err.message || "Errore durante l'aggiornamento", "error");
    } finally {
      setLoading(false);
    }
  };

  const updatePassword = async () => {
    if (newPassword.length < 6) {
      showFeedback("La password deve essere di almeno 6 caratteri", "error");
      return;
    }
    setLoading(true);
    try {
      await auth.updatePassword(newPassword);
      setNewPassword('');
      setIsChangingPassword(false);
      showFeedback("Password aggiornata correttamente!");
    } catch (err: any) {
      showFeedback(err.message || "Errore cambio password", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleRechargeLabelChange = (key: keyof UserSettings['rechargeLabels'], value: string) => {
    const updated = {
      ...localSettings,
      rechargeLabels: { ...localSettings.rechargeLabels, [key]: value }
    };
    setLocalSettings(updated);
    onUpdate(updated);
  };

  const toggleAppearance = () => {
    const updated = { ...settings, isDarkMode: !settings.isDarkMode };
    onUpdate(updated);
    setLocalSettings(updated);
  };

  const handleLogout = async () => {
    if (confirm('Sei sicuro di voler uscire?')) {
      await auth.signOut();
    }
  };

  const handleExportCSV = () => {
    if (expenses.length === 0) {
      alert("Non ci sono spese da esportare.");
      return;
    }
    const headers = ["Data", "Descrizione", "Categoria", "Metodo Pagamento", "Importo (" + settings.currency + ")"];
    const rows = expenses.map(e => [
      format(new Date(e.date), 'yyyy-MM-dd'),
      `"${e.description.replace(/"/g, '""')}"`,
      e.category,
      e.paymentMethod || "Non specificato",
      e.amount.toFixed(2).replace('.', ',')
    ]);
    const csvContent = [headers.join(";"), ...rows.map(r => r.join(";"))].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `mintflow_export_${format(new Date(), 'yyyyMMdd')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {/* Alert Feedback */}
      {feedback && (
        <div className={`fixed top-20 left-1/2 -translate-x-1/2 z-[100] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in zoom-in duration-300 ${
          feedback.type === 'success' ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white'
        }`}>
          {feedback.type === 'success' ? <CheckCircle2 size={20} /> : <Info size={20} />}
          <span className="font-bold text-sm uppercase tracking-wider">{feedback.msg}</span>
        </div>
      )}

      {/* Profile Section */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <div className="flex justify-between items-start mb-6">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white flex items-center gap-2">
            <User className="text-emerald-500" size={20} />
            Identità Account
          </h3>
          <div className="flex gap-2">
            {!isEditingProfile ? (
              <button 
                onClick={() => setIsEditingProfile(true)}
                className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20 rounded-xl hover:bg-emerald-100 transition-colors"
              >
                <Edit3 size={14} /> Modifica
              </button>
            ) : (
              <button 
                onClick={saveProfile}
                disabled={loading}
                className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-white bg-emerald-500 rounded-xl hover:bg-emerald-600 transition-colors shadow-lg shadow-emerald-100 disabled:opacity-50"
              >
                {loading ? <CheckCircle2 className="animate-pulse" size={14} /> : <Save size={14} />}
                Salva
              </button>
            )}
          </div>
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Email di Accesso</label>
            <div className="relative">
              <input
                type="email"
                disabled={!isEditingProfile}
                value={localEmail}
                onChange={(e) => setLocalEmail(e.target.value)}
                className={`w-full pl-12 pr-5 py-3 rounded-2xl transition-all outline-none font-medium border-2 ${
                  isEditingProfile 
                    ? 'bg-white dark:bg-gray-700 border-emerald-500 text-gray-800 dark:text-white' 
                    : 'bg-gray-50 dark:bg-gray-700/50 border-transparent text-gray-400'
                }`}
              />
              <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            </div>
            {isEditingProfile && <p className="text-[10px] text-emerald-500 mt-1 ml-1 font-medium italic">* Cambiare l'email richiederà una nuova conferma via posta.</p>}
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Nome Visualizzato</label>
            <input
              type="text"
              disabled={!isEditingProfile}
              value={localSettings.name}
              onChange={(e) => handleLocalChange('name', e.target.value)}
              className={`w-full px-5 py-3 rounded-2xl transition-all outline-none font-medium border-2 ${
                isEditingProfile 
                  ? 'bg-white dark:bg-gray-700 border-emerald-500 text-gray-800 dark:text-white' 
                  : 'bg-gray-50 dark:bg-gray-700/50 border-transparent text-gray-400'
              }`}
            />
          </div>
        </div>
      </div>

      {/* Security Section */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
          <ShieldCheck className="text-emerald-500" size={20} />
          Sicurezza e Password
        </h3>
        {!isChangingPassword ? (
          <button 
            onClick={() => setIsChangingPassword(true)}
            className="w-full flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700/50 rounded-2xl hover:bg-emerald-50 dark:hover:bg-gray-700 transition-all border border-transparent hover:border-emerald-100"
          >
            <div className="flex items-center gap-3">
              <Key className="text-emerald-500" size={20} />
              <span className="text-sm font-bold text-gray-700 dark:text-gray-200">Cambia Password Account</span>
            </div>
            <ArrowRight size={18} className="text-gray-300" />
          </button>
        ) : (
          <div className="space-y-4 animate-in slide-in-from-top-2">
            <input
              type="password"
              placeholder="Nuova Password (min. 6 caratteri)"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="w-full px-5 py-3 rounded-2xl bg-white dark:bg-gray-700 border-2 border-emerald-500 outline-none text-gray-800 dark:text-white font-medium"
              autoFocus
            />
            <div className="flex gap-2">
              <button 
                onClick={updatePassword}
                disabled={loading}
                className="flex-1 py-3 bg-emerald-500 text-white font-bold rounded-xl text-sm"
              >
                Salva Nuova Password
              </button>
              <button 
                onClick={() => setIsChangingPassword(false)}
                className="px-6 py-3 bg-gray-100 dark:bg-gray-700 text-gray-400 font-bold rounded-xl text-sm"
              >
                Annulla
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Finance Prefs Section */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
          <Wallet className="text-emerald-500" size={20} />
          Preferenze Finanziarie
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-2 ml-1">Valuta Principale</label>
            <div className="relative">
              <select
                value={settings.currency}
                onChange={(e) => onUpdate({ ...settings, currency: e.target.value })}
                className="w-full pl-12 pr-5 py-3 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:focus:border-emerald-500 focus:bg-white dark:focus:bg-gray-700 dark:text-white transition-all outline-none font-bold appearance-none cursor-pointer"
              >
