            />
          </div>
        </div>

        {/* Recharge Menu Customization */}
        <div className="pt-6 mt-6 border-t border-emerald-50 dark:border-gray-700">
          <h4 className="text-sm font-bold text-gray-800 dark:text-white mb-4 flex items-center gap-2">
            <Edit3 className="text-emerald-500" size={16} />
            Etichette Menu Ricariche
