                onChange={(e) => handleRechargeLabelChange('flash', e.target.value)}
                className="w-full px-4 py-2 rounded-xl bg-gray-50 dark:bg-gray-700 border border-emerald-50 dark:border-gray-600 focus:border-emerald-500 outline-none dark:text-white transition-all text-sm font-medium"
