import React, { useState } from 'react';
import { UserSettings, Expense } from '../types';
// Fix: removed ChevronRight from lucide-react imports as it is defined locally at the end of this file to allow custom styling
import { User, Wallet, DollarSign, Trash2, Download, Info, Moon, Sun, LogOut, FileDown, Edit3, Save, CheckCircle2, Key, Mail, ShieldCheck } from 'lucide-react';
import { auth } from '../services/supabase';
import { format } from 'date-fns';

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  expenses,
  email
}) => {
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isChangingPassword, setIsChangingPassword] = useState(false);

  const [localSettings, setLocalSettings] = useState(settings);
  const [localEmail, setLocalEmail] = useState(email || '');
  const [newPassword, setNewPassword] = useState('');

  const [feedback, setFeedback] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [loading, setLoading] = useState(false);

  const showFeedback = (msg: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ msg, type });
    setTimeout(() => setFeedback(null), 3500);
  };

  const handleProfileUpdate = async () => {
    setLoading(true);
    try {
      // 1. Update Name
      if (localSettings.name !== settings.name) {
        await auth.updateProfile(localSettings.name);
      }
      // 2. Update Email
      if (localEmail !== email) {
        await auth.updateEmail(localEmail);
        showFeedback("Email inviata per confermare il nuovo indirizzo.");
      }
      onUpdate(localSettings);
      setIsEditingProfile(false);
      showFeedback("Profilo aggiornato!");
    } catch (err: any) {
      showFeedback(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  const handlePasswordUpdate = async () => {
    if (newPassword.length < 6) {
      showFeedback("Password troppo corta (min 6 car.)", "error");
      return;
    }
    setLoading(true);
    try {
      await auth.updatePassword(newPassword);
      setNewPassword('');
      setIsChangingPassword(false);
      showFeedback("Password modificata correttamente.");
    } catch (err: any) {
      showFeedback(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteAccount = async () => {
    if (confirm("ATTENZIONE: Questa azione eliminerà definitivamente tutte le tue spese e chiuderà la sessione. Sei sicuro?")) {
      try {
        setLoading(true);
        await auth.deleteAccount();
        window.location.reload();
