import React, { useMemo } from 'react';
import { Expense, Category, PaymentMethod } from '../types';
import { 
  PieChart, Pie, Cell, ResponsiveContainer, Tooltip 
} from 'recharts';
import { Wallet, Calendar, Target, Zap, Fuel, CreditCard, Building } from 'lucide-react';
import { format, startOfMonth, endOfMonth, isWithinInterval, subMonths } from 'date-fns';
import { it } from 'date-fns/locale';

interface DashboardProps {
  expenses: Expense[];
  budget: number;
  userName?: string;
  currency?: string;
  rechargeLabels: {
    flash: string;
    revolut: string;
    q8: string;
  };
}

export const Dashboard: React.FC<DashboardProps> = ({ expenses, budget, userName = 'Utente', currency = '€', rechargeLabels }) => {
  const currentMonth = new Date();
  const currentMonthStart = startOfMonth(currentMonth);
  const currentMonthEnd = endOfMonth(currentMonth);

  const currentMonthExpenses = useMemo(() => {
    return expenses.filter(e => 
      isWithinInterval(new Date(e.date), { start: currentMonthStart, end: currentMonthEnd })
    );
  }, [expenses]);

  const totalCurrentMonth = currentMonthExpenses.reduce((sum, e) => sum + e.amount, 0);

  const lastMonthStart = startOfMonth(subMonths(currentMonth, 1));
  const lastMonthEnd = endOfMonth(subMonths(currentMonth, 1));
  const totalLastMonth = expenses
    .filter(e => isWithinInterval(new Date(e.date), { start: lastMonthStart, end: lastMonthEnd }))
    .reduce((sum, e) => sum + e.amount, 0);

  const diff = totalLastMonth > 0 ? ((totalCurrentMonth - totalLastMonth) / totalLastMonth) * 100 : 0;
  const budgetProgress = Math.min((totalCurrentMonth / budget) * 100, 100);

  const balances = useMemo(() => {
    const calculateBalance = (rechargeDesc: string, method: PaymentMethod) => {
      const totalRecharged = expenses
        .filter(e => e.description.toLowerCase().includes(rechargeDesc.toLowerCase()))
        .reduce((sum, e) => sum + e.amount, 0);

      const totalSpent = expenses
        .filter(e => e.paymentMethod === method && !e.description.toLowerCase().includes('ricarica'))
        .reduce((sum, e) => sum + e.amount, 0);

      return Math.max(0, totalRecharged - totalSpent);
    };

    // Saldo Bancomat: Trattato come deposito bancario (ricariche aggiungono, spese tolgono)
    const bancomatBalance = calculateBalance('Deposito Bancomat', PaymentMethod.Bancomat);

    return [
      { 
        name: rechargeLabels.flash, 
        value: calculateBalance(`Ricarica ${rechargeLabels.flash}`, PaymentMethod.Flash),
        icon: <Zap size={14} />,
        color: 'text-emerald-500'
      },
      { 
        name: rechargeLabels.revolut, 
        value: calculateBalance(`Ricarica ${rechargeLabels.revolut}`, PaymentMethod.Revolut),
        icon: <Wallet size={14} />,
        color: 'text-blue-500'
      },
      { 
        name: 'Bancomat', 
        value: bancomatBalance,
        icon: <Building size={14} />,
        color: 'text-purple-500'
      },
      { 
        name: rechargeLabels.q8, 
        value: calculateBalance(`Ricarica ${rechargeLabels.q8}`, PaymentMethod.AppQ8),
        icon: <Fuel size={14} />,
        color: 'text-orange-500'
      }
    ];
  }, [expenses, rechargeLabels]);

  const categoryData = useMemo(() => {
    const data: Record<string, number> = {};
    currentMonthExpenses.forEach(e => {
      data[e.category] = (data[e.category] || 0) + e.amount;
    });
    return Object.entries(data).map(([name, value]) => ({ name, value }));
  }, [currentMonthExpenses]);

  const COLORS = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#047857', '#065f46', '#064e3b'];
  const formatValue = (val: number) => `${currency}${val.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`;
  const isDark = document.documentElement.classList.contains('dark');

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="mb-2">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Ciao, {userName}! 👋</h2>
        <p className="text-gray-500 dark:text-gray-400">Riepilogo delle tue finanze.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="md:col-span-2 bg-emerald-500 dark:bg-emerald-600 p-8 rounded-[2rem] text-white shadow-xl shadow-emerald-200/50 dark:shadow-none relative overflow-hidden">
          <div className="absolute -right-8 -top-8 w-32 h-32 bg-white/10 rounded-full blur-3xl"></div>

          <div className="flex justify-between items-start mb-6">
            <div>
              <p className="text-emerald-50 text-sm font-medium uppercase tracking-wider">Uscite Mese</p>
              <h2 className="text-4xl font-bold mt-1">{formatValue(totalCurrentMonth)}</h2>
            </div>
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm">
              <CreditCard size={24} />
            </div>
          </div>

          <div className="space-y-2">
            <div className="flex justify-between text-xs font-medium text-emerald-50">
              <span>Budget: {currency}{budget.toLocaleString('it-IT')}</span>
              <span>{Math.round(budgetProgress)}% utilizzato</span>
            </div>
            <div className="h-2 w-full bg-white/20 rounded-full overflow-hidden">
              <div 
                className={`h-full transition-all duration-1000 ${totalCurrentMonth > budget ? 'bg-red-300' : 'bg-white'}`}
                style={{ width: `${budgetProgress}%` }}
              ></div>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm transition-colors">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl">
              <Target size={20} />
            </div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-xs">Rispetto a Ieri</p>
              <p className={`font-bold ${diff <= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-500'}`}>
                {diff <= 0 ? '-' : '+'}{Math.abs(diff).toFixed(1)}%
              </p>
            </div>
          </div>
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm transition-colors">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl">
              <Calendar size={20} />
            </div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-xs">Periodo</p>
              <p className="font-bold text-gray-800 dark:text-white capitalize">{format(currentMonth, "MMMM yyyy", { locale: it })}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors overflow-x-auto">
        <h3 className="text-sm font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest mb-6 px-2 flex items-center gap-2">
          <Wallet size={16} className="text-emerald-500" />
          I tuoi Saldi
        </h3>
        <div className="flex flex-nowrap md:grid md:grid-cols-4 gap-4 pb-2">
          {balances.map((wallet) => (
            <div key={wallet.name} className="flex-shrink-0 w-48 md:w-auto flex flex-col gap-1 p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/40 border border-transparent hover:border-emerald-100 dark:hover:border-emerald-900/30 transition-all">
              <div className="flex items-center justify-between mb-2">
                <div className={`p-2 rounded-lg bg-white dark:bg-gray-800 shadow-sm ${wallet.color}`}>
                  {wallet.icon}
                </div>
                <span className="text-[9px] font-bold text-gray-400 uppercase tracking-tighter truncate max-w-[60px]">{wallet.name}</span>
              </div>
              <p className={`text-lg font-black ${wallet.value > 0 ? 'text-gray-800 dark:text-white' : 'text-gray-300 dark:text-gray-600'}`}>
                {currency}{wallet.value.toLocaleString('it-IT', { minimumFractionDigits: 2 })}
              </p>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 px-2">Categorie Mese</h3>
          <div className="h-64">
            {categoryData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={categoryData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                    {categoryData.map((_, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                  </Pie>
                  <Tooltip 
                    contentStyle={{ 
                      borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                      backgroundColor: isDark ? '#1f2937' : '#ffffff', color: isDark ? '#ffffff' : '#000000'
                    }} 
                  />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex items-center justify-center text-gray-400">Nessuna spesa</div>
            )}
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
           <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 px-2">Top Categorie</h3>
           <div className="space-y-3">
             {categoryData.sort((a,b) => b.value - a.value).slice(0, 5).map((entry, index) => (
               <div key={entry.name} className="flex items-center justify-between p-3 rounded-xl hover:bg-emerald-50 dark:hover:bg-gray-700 transition-colors">
                 <div className="flex items-center gap-3">
                   <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                   <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{entry.name}</span>
                 </div>
                 <span className="text-sm font-bold text-gray-900 dark:text-white">{formatValue(entry.value)}</span>
               </div>
             ))}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { ReceiptScanner } from './components/ReceiptScanner';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
import { Auth } from './components/Auth';
import { Expense, Category, UserSettings, PaymentMethod } from './types';
import { Plus, ScanLine, Cloud, Loader2, CreditCard, PartyPopper, History, Wand2 } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { startOfMonth, format, subMonths } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [showNewMonthToast, setShowNewMonthToast] = useState(false);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€',
      isDarkMode: false,
      rechargeLabels: {
        flash: 'Prepagata Flash',
        revolut: 'Prepagata Revolut',
        q8: 'App Q8'
      }
    };
    if (!saved) return defaultSettings;
    const parsed = JSON.parse(saved);
    return { ...defaultSettings, ...parsed };
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  useEffect(() => {
    const initSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session?.user) {
        const metadata = session.user.user_metadata;
        const displayName = metadata.full_name || metadata.display_name || metadata.name || session.user.email?.split('@')[0] || 'Utente';
        setUserSettings(prev => ({ ...prev, name: displayName }));
      }
      setIsInitialLoading(false);
    };
    initSession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session?.user?.id) {
      const loadData = async () => {
        try {
          setIsLoading(true);
          const data = await db.getExpenses(session.user.id);
          setExpenses(data);
          const today = new Date();
          const currentMonthKey = format(startOfMonth(today), 'yyyy-MM');
          const lastArchivedMonth = localStorage.getItem('mintflow_last_archived');
          if (today.getDate() === 1 && lastArchivedMonth !== currentMonthKey) {
            setShowNewMonthToast(true);
            localStorage.setItem('mintflow_last_archived', currentMonthKey);
            setTimeout(() => setShowNewMonthToast(false), 8000);
          }
        } catch (err) {
          console.error("Errore caricamento:", err);
        } finally {
          setIsLoading(false);
        }
      };
      loadData();
    }
  }, [session]);

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
    if (userSettings.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [userSettings]);

  if (isInitialLoading) {
    return (
      <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex flex-col items-center justify-center gap-4">
        <div className="bg-emerald-500 p-5 rounded-3xl text-white shadow-2xl animate-pulse">
          <CreditCard size={48} />
        </div>
        <div className="flex flex-col items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold">
          <Loader2 size={20} className="animate-spin" />
          <span>MintFlow Sync...</span>
        </div>
      </div>
    );
  }

  if (!session) return <Auth onSuccess={() => {}} />;

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      if (prefill?.id) {
        const updated = await db.updateExpense(prefill.id, expenseData);
        if (updated) setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
      } else {
        const newExpense = await db.addExpense(expenseData, session.user.id);
        if (newExpense) setExpenses(prev => [newExpense, ...prev]);
      }
      setShowForm(false);
      setPrefill(null);
    } catch (err: any) {
      alert(`Errore Cloud: ${err.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const deleteExpense = async (id: string) => {
    if (!confirm("Eliminare questa spesa?")) return;
    try {
      setIsSyncing(true);
      await db.deleteExpense(id);
      setExpenses(prev => prev.filter(e => e.id !== id));
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleClearData = async () => {
    if (confirm('Resettare tutte le spese dal cloud?')) {
      try {
        setIsSyncing(true);
        await db.clearAll(session.user.id);
        setExpenses([]);
      } catch (err: any) {
        alert("Errore: " + err.message);
      } finally {
        setIsSyncing(false);
      }
    }
  };

  const injectTestData = async () => {
    try {
      setIsSyncing(true);
      const pastDate = format(subMonths(new Date(), 1), 'yyyy-MM-dd');
      const testExpense = await db.addExpense({
        description: "Spesa Test Storico",
        amount: 50.00,
        category: Category.Altro,
        paymentMethod: PaymentMethod.Contanti,
        date: pastDate
      }, session.user.id);
      if (testExpense) setExpenses(prev => [testExpense, ...prev]);
      alert("Spesa storica aggiunta per test!");
    } catch (err) {
      alert("Errore nel test data.");
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {showNewMonthToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm bg-emerald-500 text-white p-6 rounded-[2rem] shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-4 duration-500">
            <div className="bg-white/20 p-3 rounded-2xl shrink-0"><PartyPopper size={24} /></div>
            <div>
              <p className="font-bold text-sm">Nuovo mese iniziato! 🚀</p>
              <p className="text-[10px] opacity-90 uppercase font-bold tracking-widest mt-1 flex items-center gap-1"><History size={10} /> Dati archiviati</p>
            </div>
            <button onClick={() => setShowNewMonthToast(false)} className="ml-auto opacity-50">✕</button>
          </div>
        )}

        <div className="flex justify-between items-center mb-4 px-2">
          <button 
            onClick={injectTestData}
            className="flex items-center gap-1.5 text-[9px] font-bold uppercase tracking-widest text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20 px-3 py-1.5 rounded-full hover:bg-emerald-100 transition-all border border-emerald-100 dark:border-emerald-800"
          >
            <Wand2 size={12} /> Test Storico
          </button>
          <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-gray-400">
            {isSyncing ? <><Loader2 size={12} className="animate-spin text-emerald-500" /> <span className="text-emerald-500">Cloud Sync...</span></> : <><Cloud size={12} className="text-emerald-400" /> <span>Sincronizzato</span></>}
          </div>
        </div>

        {activeTab !== 'dashboard' && (
          <div className="mb-6">
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white capitalize">
               {activeTab === 'list' ? 'Le tue Spese' : 
                activeTab === 'ai' ? 'AI Insights' : 
                activeTab === 'ricariche' ? 'Portafogli' : 
                activeTab === 'subscriptions' ? 'Abbonamenti' : 'Impostazioni'}
            </h1>
          </div>
        )}

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
             <Loader2 size={48} className="text-emerald-500 animate-spin" />
             <p className="text-gray-400 font-medium">Caricamento...</p>
          </div>
        ) : (
          <>
            {activeTab === 'dashboard' && (
              <Dashboard 
                expenses={expenses} budget={userSettings.monthlyBudget} userName={userSettings.name} currency={userSettings.currency} rechargeLabels={userSettings.rechargeLabels}
              />
            )}

            {activeTab === 'list' && (
              <div className="space-y-6">
                <div className="flex gap-3">
                  <button onClick={() => { setPrefill(null); setShowForm(true); }} className="flex-1 bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-lg"><Plus size={20} /> <span className="font-bold">Aggiungi</span></button>
                  <button onClick={() => setShowScanner(true)} className="flex-1 bg-white dark:bg-gray-800 border-2 border-emerald-100 dark:border-gray-700 text-emerald-600 dark:text-emerald-400 px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-sm"><ScanLine size={20} /> <span className="font-bold">Scan</span></button>
                </div>
                <ExpenseList expenses={expenses} onDelete={deleteExpense} onEdit={(ex) => {setPrefill(ex); setShowForm(true);}} currency={userSettings.currency} />
              </div>
            )}

            {activeTab === 'subscriptions' && (
              <SubscriptionsView expenses={expenses} onAddSub={() => { setPrefill({ isSubscription: true, category: Category.Abbonamenti }); setShowForm(true); }} onDelete={deleteExpense} currency={userSettings.currency} />
            )}

            {activeTab === 'ricariche' && (
              <RicaricheView onRefill={(type) => {
                const config = {
                  flash: { desc: `Ricarica ${userSettings.rechargeLabels.flash}`, method: PaymentMethod.Flash },
                  revolut: { desc: `Ricarica ${userSettings.rechargeLabels.revolut}`, method: PaymentMethod.Revolut },
                  q8: { desc: `Ricarica ${userSettings.rechargeLabels.q8}`, method: PaymentMethod.AppQ8 },
                  bancomat: { desc: `Deposito Bancomat`, method: PaymentMethod.Bancomat }
                };
                const s = (config as any)[type] || { desc: "Ricarica", method: PaymentMethod.Contanti };
                setPrefill({ description: s.desc, category: Category.Altro, paymentMethod: s.method, date: format(new Date(), 'yyyy-MM-dd') });
                setShowForm(true);
              }} expenses={expenses} currency={userSettings.currency} labels={userSettings.rechargeLabels} />
            )}

            {activeTab === 'ai' && <AiInsights expenses={expenses} />}
            {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={handleClearData} expenses={expenses} email={session.user.email} />}
          </>
        )}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl relative animate-in zoom-in-95 duration-200">
              <button onClick={() => { setShowForm(false); setPrefill(null); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600">✕</button>
              <h2 className="text-2xl font-bold mb-6 text-gray-800 dark:text-white">{prefill?.id ? 'Modifica' : 'Nuova Spesa'}</h2>
              <ExpenseForm onSubmit={handleSaveExpense} onCancel={() => { setShowForm(false); setPrefill(null); }} initialData={prefill || undefined} currency={userSettings.currency} />
            </div>
          </div>
        )}

        {showScanner && <ReceiptScanner onDetected={(res) => { setPrefill({...res, date: format(new Date(), 'yyyy-MM-dd')}); setShowScanner(false); setShowForm(true); }} onClose={() => setShowScanner(false)} />}
      </div>
    </Layout>
  );
};

export default App;

