              <ExpenseForm onSubmit={handleSaveExpense} onCancel={() => { setShowForm(false); setPrefill(null); }} initialData={prefill || undefined} currency={userSettings.currency} />
            </div>
          </div>
        )}

        {showScanner && <ReceiptScanner onDetected={(res) => { setPrefill({...res, date: format(new Date(), 'yyyy-MM-dd')}); setShowScanner(false); setShowForm(true); }} onClose={() => setShowScanner(false)} />}
      </div>
    </Layout>
  );
};

