import React, { useState, useEffect } from 'react';
import { CategoryConfig, Expense, PaymentMethod, WalletConfig } from '../types';
import { SmartCategorizer } from './SmartCategorizer';
import { Wallet, CreditCard, Banknote, Fuel, Loader2, Save, Repeat, Building } from 'lucide-react';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => Promise<void> | void;
  onCancel: () => void;
  initialData?: Partial<Expense>;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ onSubmit, onCancel, initialData, currency = '€', wallets, categories }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<string>('Altro');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.Contanti);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSubscription, setIsSubscription] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (initialData) {
      if (initialData.description !== undefined) setDescription(initialData.description);
      if (initialData.amount !== undefined) setAmount(initialData.amount.toString());
      if (initialData.category !== undefined) setCategory(initialData.category);
      if (initialData.paymentMethod !== undefined) setPaymentMethod(initialData.paymentMethod);
      if (initialData.date !== undefined) setDate(initialData.date);
      if (initialData.isSubscription !== undefined) setIsSubscription(initialData.isSubscription || false);
    } else {
      setCategory(categories[categories.length - 1]?.name || 'Altro');
    }
  }, [initialData, categories]);

  const handleFormSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    const parsedAmount = parseFloat(amount.replace(',', '.'));
    if (isNaN(parsedAmount) || parsedAmount <= 0) return alert("Importo non valido");

    setIsSubmitting(true);
    try {
      await onSubmit({
        description: description.trim() || 'Spesa senza nome',
        amount: parsedAmount,
        category,
        paymentMethod,
        date,
        isSubscription
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const getPaymentIcon = (method: PaymentMethod) => {
    const wallet = wallets.find(w => w.method === method);
    if (wallet) return wallet.icon === 'zap' ? <Zap size={16} /> : wallet.icon === 'fuel' ? <Fuel size={16} /> : <CreditCard size={16} />;
    return method === PaymentMethod.Contanti ? <Banknote size={16} /> : <Building size={16} />;
  };

  const Zap = ({size}: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>;

  return (
    <form onSubmit={handleFormSubmit} className="space-y-5">
      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Descrizione</label>
        <input type="text" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Cosa hai comprato?" className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" />
        <SmartCategorizer description={description} onSuggest={setCategory} categories={categories} />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <input type="text" inputMode="decimal" value={amount} onChange={(e) => setAmount(e.target.value)} placeholder={`0.00 ${currency}`} className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-bold" />
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" />
      </div>

      <button type="button" onClick={() => setIsSubscription(!isSubscription)} className={`w-full flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isSubscription ? 'bg-emerald-50 border-emerald-500 text-emerald-600' : 'bg-gray-50 border-transparent text-gray-400'}`}>
        <div className="flex items-center gap-2 font-bold text-sm"><Repeat size={18} /> Abbonamento Ricorrente</div>
        <div className={`w-10 h-6 rounded-full relative transition-colors ${isSubscription ? 'bg-emerald-500' : 'bg-gray-300'}`}><div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isSubscription ? 'left-5' : 'left-1'}`}></div></div>
      </button>

      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Pagamento</label>
        <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
          {[PaymentMethod.Contanti, PaymentMethod.Bancomat, ...wallets.map(w => w.method)].map((m) => (
            <button key={m} type="button" onClick={() => setPaymentMethod(m)} className={`flex items-center gap-2 px-3 py-3 rounded-xl text-[10px] font-bold border-2 ${paymentMethod === m ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
              {getPaymentIcon(m)} <span className="truncate">{wallets.find(w => w.method === m)?.name || m}</span>
            </button>
          ))}
        </div>
      </div>

      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Categoria</label>
        <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
          {categories.map((cat) => (
            <button key={cat.id} type="button" onClick={() => setCategory(cat.name)} className={`px-4 py-3 rounded-xl text-xs font-bold border-2 ${category === cat.name ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
              {cat.name}
            </button>
          ))}
        </div>
      </div>

      <div className="flex gap-4 pt-2">
        <button type="button" onClick={onCancel} className="flex-1 px-6 py-4 rounded-2xl border-2 border-gray-100 text-gray-400 font-bold">Annulla</button>
        <button type="submit" disabled={isSubmitting} className="flex-1 px-6 py-4 rounded-2xl bg-emerald-500 text-white font-bold shadow-xl shadow-emerald-100 disabled:opacity-70 flex items-center justify-center gap-2">
          {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />} Salva
        </button>
      </div>
    </form>
  );
};

import React, { useEffect, useState } from 'react';
import { CategoryConfig } from '../types';
import { Sparkles } from 'lucide-react';

interface SmartCategorizerProps {
  description: string;
  onSuggest: (category: string) => void;
  categories: CategoryConfig[];
}

export const SmartCategorizer: React.FC<SmartCategorizerProps> = ({ description, onSuggest, categories }) => {
  const [suggestion, setSuggestion] = useState<string | null>(null);

  useEffect(() => {
    if (description.length < 3) {
      setSuggestion(null);
      return;
    }

    const d = description.toLowerCase();
    let suggested: string | null = null;

    // Mapping logico basato su parole chiave e nomi delle categorie dell'utente
    const findCat = (keywords: string[]) => categories.find(c => keywords.some(k => c.name.toLowerCase().includes(k) || d.includes(k)));

    if (d.includes('sigarette') || d.includes('heets') || d.includes('tabacco')) suggested = findCat(['sigarette'])?.name || null;
    else if (d.includes('benzina') || d.includes('eni') || d.includes('q8')) suggested = findCat(['benzina'])?.name || null;
    else if (d.includes('autostrada') || d.includes('casello')) suggested = findCat(['autostrada'])?.name || null;
    else if (d.includes('netflix') || d.includes('spotify') || d.includes('prime')) suggested = categories.find(c => c.isSubscriptionDefault || c.name.toLowerCase().includes('abbon'))?.name || null;
    else if (d.includes('pizza') || d.includes('bar') || d.includes('ristorante')) suggested = findCat(['svago', 'divertimento'])?.name || null;

    setSuggestion(suggested);
  }, [description, categories]);

  if (!suggestion) return null;

  return (
    <div 
      onClick={() => onSuggest(suggestion)}
      className="mt-2 flex items-center gap-2 text-xs text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-lg cursor-pointer hover:bg-emerald-100 border border-emerald-100 animate-in slide-in-from-top-1"
    >
      <Sparkles size={12} />
      <span>Suggerimento AI: <strong>{suggestion}</strong>. Clicca per impostare.</span>
    </div>
  );
};

