export const db = {
  async getExpenses(userId: string): Promise<Expense[]> {
    const { data, error } = await supabase
      .from('expenses')
      .select('*')
      .eq('user_id', userId)
      .order('date', { ascending: false });

    if (error) throw error;

    // Decodifica il tag dalla descrizione per ripristinare lo stato UI
    return (data || []).map((e: any) => {
      const isSub = e.description?.includes(SUB_TAG);
      return {
        ...e,
        description: isSub ? e.description.replace(SUB_TAG, '') : e.description,
        isSubscription: isSub
      };
    });
  },

  async addExpense(expense: Omit<Expense, 'id'>, userId: string): Promise<Expense> {
    // Codifica lo stato isSubscription nella descrizione per evitare errori di colonna inesistente
    const finalDescription = expense.isSubscription 
      ? `${expense.description}${SUB_TAG}` 
      : expense.description;

    const insertData: any = {
      description: finalDescription,
      amount: expense.amount,
      category: expense.category,
      paymentMethod: expense.paymentMethod,
      date: expense.date,
      user_id: userId
      // NOTA: is_subscription viene omesso per risolvere il crash del database
    };

    const { data, error } = await supabase.from('expenses').insert([insertData]).select().single();
    if (error) throw error;

    // Restituiamo l'oggetto pulito per la UI
    return {
      ...data,
      description: expense.description,
      isSubscription: expense.isSubscription
    };
  },

  async updateExpense(id: string, expense: Partial<Omit<Expense, 'id'>>): Promise<Expense> {
    const updateData: any = {};

    // Se stiamo aggiornando la descrizione o lo stato subscription, dobbiamo ricalcolare il tag
    if (expense.description !== undefined || expense.isSubscription !== undefined) {
      const currentDesc = expense.description || '';
      const currentIsSub = expense.isSubscription !== undefined ? expense.isSubscription : false;
      updateData.description = currentIsSub ? `${currentDesc}${SUB_TAG}` : currentDesc;
    }

    if (expense.amount !== undefined) updateData.amount = expense.amount;
    if (expense.category !== undefined) updateData.category = expense.category;
    if (expense.paymentMethod !== undefined) updateData.paymentMethod = expense.paymentMethod;
    if (expense.date !== undefined) updateData.date = expense.date;

    const { data, error } = await supabase.from('expenses').update(updateData).eq('id', id).select().single();
    if (error) throw error;

    return {
      ...data,
      description: expense.description || data.description.replace(SUB_TAG, ''),
      isSubscription: expense.isSubscription !== undefined ? expense.isSubscription : data.description.includes(SUB_TAG)
