// Tag speciale per salvare i metadati nella descrizione senza rompere lo schema del DB
const SUB_TAG = ' %%SUB%%';

export const auth = {
  async signUp(email: string, password: string, username: string) {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: { data: { display_name: username }, emailRedirectTo: getRedirectUrl() }
    });
    if (error) throw error;
    return data;
  },
  async resendConfirmation(email: string) {
    const { error } = await supabase.auth.resend({ type: 'signup', email, options: { emailRedirectTo: getRedirectUrl() } });
    if (error) throw error;
  },
  async signIn(email: string, password: string) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
    return data;
  },
  async signOut() {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  },
  async updateProfile(name: string) {
    const { data, error } = await supabase.auth.updateUser({ data: { display_name: name } });
    if (error) throw error;
    return data;
  },
  async updateEmail(newEmail: string) {
    const { data, error } = await supabase.auth.updateUser({ email: newEmail }, { emailRedirectTo: getRedirectUrl() });
    if (error) throw error;
    return data;
  },
  async updatePassword(password: string) {
    const { data, error } = await supabase.auth.updateUser({ password });
    if (error) throw error;
    return data;
  },
  async deleteAccount() {
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await db.clearAll(user.id);
      await this.signOut();
    }
  }
};

export const db = {
  async getExpenses(userId: string): Promise<Expense[]> {
    const { data, error } = await supabase
      .from('expenses')
      .select('*')
      .eq('user_id', userId)
      .order('date', { ascending: false });

    if (error) throw error;

    return (data || []).map((e: any) => {
      // Gestiamo il mapping bidirezionale per sicurezza (sia camelCase che snake_case dal DB)
      const isSub = e.description?.includes(SUB_TAG);
      return {
        id: e.id,
        amount: e.amount,
        category: e.category,
        date: e.date,
        description: isSub ? e.description.replace(SUB_TAG, '') : e.description,
        paymentMethod: e.payment_method || e.paymentMethod, // Mappatura flessibile
        isSubscription: isSub
      };
    });
  },

  async addExpense(expense: Omit<Expense, 'id'>, userId: string): Promise<Expense> {
    const finalDescription = expense.isSubscription 
      ? `${expense.description}${SUB_TAG}` 
      : expense.description;

    // Usiamo ESPLICITAMENTE i nomi delle colonne in snake_case per Supabase
    const insertData: any = {
      description: finalDescription,
      amount: expense.amount,
      category: expense.category,
      payment_method: expense.paymentMethod, 
      date: expense.date,
      user_id: userId
    };

    const { data, error } = await supabase.from('expenses').insert([insertData]).select().single();
    if (error) throw error;

    return {
      id: data.id,
      description: expense.description,
      amount: data.amount,
      category: data.category,
      paymentMethod: data.payment_method || data.paymentMethod,
      date: data.date,
      isSubscription: expense.isSubscription
    };
  },

  async updateExpense(id: string, expense: Partial<Omit<Expense, 'id'>>): Promise<Expense> {
    const updateData: any = {};

    if (expense.description !== undefined || expense.isSubscription !== undefined) {
      const currentDesc = expense.description || '';
      const currentIsSub = expense.isSubscription !== undefined ? expense.isSubscription : false;
      updateData.description = currentIsSub ? `${currentDesc}${SUB_TAG}` : currentDesc;
    }

    if (expense.amount !== undefined) updateData.amount = expense.amount;
    if (expense.category !== undefined) updateData.category = expense.category;
    if (expense.paymentMethod !== undefined) updateData.payment_method = expense.paymentMethod;
    if (expense.date !== undefined) updateData.date = expense.date;

    const { data, error } = await supabase.from('expenses').update(updateData).eq('id', id).select().single();
    if (error) throw error;

    return {
      id: data.id,
      amount: data.amount,
      category: data.category,
      date: data.date,
      description: expense.description || data.description.replace(SUB_TAG, ''),
      paymentMethod: data.payment_method || data.paymentMethod,
      isSubscription: expense.isSubscription !== undefined ? expense.isSubscription : data.description.includes(SUB_TAG)
    };
  },

  async deleteExpense(id: string): Promise<void> {
    const { error } = await supabase.from('expenses').delete().eq('id', id);
    if (error) throw error;
  },

  async clearAll(userId: string): Promise<void> {
    const { error } = await supabase.from('expenses').delete().eq('user_id', userId);
    if (error) throw error;
  }
};

