              <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.isDarkMode ? 'left-7' : 'left-1'}`}></div>
            </div>
          </button>
        </div>
      </div>

      {/* Sezione Gestione Dati */}
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
