import React, { useState } from 'react';
import { UserSettings, Expense, WalletConfig, CategoryConfig, PaymentMethod } from '../types';
import { User, DollarSign, Trash2, Download, Moon, Sun, LogOut, FileDown, History, CheckCircle2, ShieldCheck, Edit3, X, Mail, Globe, Lock, Wallet, Tag, ChevronRight, Plus } from 'lucide-react';
import { auth } from '../services/supabase';
import { format } from 'date-fns';
import { HistoryView } from './HistoryView';

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  expenses,
  email
}) => {
  const [showHistory, setShowHistory] = React.useState(false);
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [showWalletsModal, setShowWalletsModal] = useState(false);
  const [showCategoriesModal, setShowCategoriesModal] = useState(false);
  const [feedback, setFeedback] = React.useState<string | null>(null);

  // State per la modale profilo
  const [tempName, setTempName] = useState(settings.name);
  const [tempEmail, setTempEmail] = useState(email || '');
  const [isUpdating, setIsUpdating] = useState(false);

  // State per password
  const [newPassword, setNewPassword] = useState('');

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 3000);
  };

  const handleUpdateProfile = async () => {
    setIsUpdating(true);
    try {
      if (tempName !== settings.name) {
        await auth.updateProfile(tempName);
        onUpdate({ ...settings, name: tempName });
      }
      if (tempEmail !== email) {
        await auth.updateEmail(tempEmail);
        showFeedback("Email di conferma inviata!");
      } else {
        showFeedback("Profilo aggiornato!");
      }
      setShowProfileModal(false);
    } catch (err: any) {
      alert("Errore aggiornamento: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdatePassword = async () => {
    if (newPassword.length < 6) return alert("La password deve essere di almeno 6 caratteri");
    setIsUpdating(true);
    try {
      await auth.updatePassword(newPassword);
      showFeedback("Password aggiornata!");
      setShowPasswordModal(false);
      setNewPassword('');
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDeleteAccount = async () => {
    if (confirm("ATTENZIONE: Questa azione eliminerà definitivamente il tuo account e tutti i dati cloud. Sei sicuro?")) {
      try {
        await auth.deleteAccount();
      } catch (err: any) {
        alert("Errore: " + err.message);
      }
    }
  };

  const handleExportCSV = () => {
    if (expenses.length === 0) return;
    const headers = ["Data", "Descrizione", "Categoria", "Metodo", "Importo"];
    const rows = expenses.map(e => [e.date, e.description, e.category, e.paymentMethod, e.amount.toString()]);
    const csvContent = [headers.join(";"), ...rows.map(r => r.join(";"))].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `mintflow_export_${format(new Date(), 'yyyyMMdd')}.csv`);
    link.click();
    showFeedback("CSV Esportato!");
  };

  if (showHistory) {
    return <HistoryView expenses={expenses} onClose={() => setShowHistory(false)} currency={settings.currency} />;
  }

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {feedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 bg-emerald-500 text-white rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in zoom-in duration-300">
          <CheckCircle2 size={16} />
          <span className="font-bold text-xs uppercase tracking-wider">{feedback}</span>
        </div>
      )}

      {/* Card Profilo */}
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm relative overflow-hidden">
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-4 rounded-3xl text-white">
              <User size={32} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-gray-800 dark:text-white">Il tuo Profilo</h3>
              <p className="text-gray-400 text-sm">{email}</p>
            </div>
          </div>
          <button 
            onClick={() => setShowProfileModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-xl font-bold text-xs hover:bg-emerald-100 transition-all"
          >
            <Edit3 size={14} /> Modifica Profilo
          </button>
        </div>

        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-3 ml-1">Nome Visualizzato</label>
          <div className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 dark:text-white font-bold text-lg">
            {settings.name}
          </div>
        </div>
      </div>

      {/* NUOVA SEZIONE: Voci richieste (Password, Ricariche, Categorie) */}
      <div className="bg-white dark:bg-gray-800 p-2 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-hidden">
        <SettingsRow 
          icon={<Lock className="text-emerald-500" size={20} />} 
          label="Cambia Password" 
          onClick={() => setShowPasswordModal(true)} 
        />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow 
          icon={<Wallet className="text-emerald-500" size={20} />} 
          label="Cambia Ricariche" 
          onClick={() => setShowWalletsModal(true)} 
        />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow 
          icon={<Tag className="text-emerald-500" size={20} />} 
          label="Cambia Categorie" 
          onClick={() => setShowCategoriesModal(true)} 
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Card Budget e Valuta */}
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
            <DollarSign className="text-emerald-500" size={20} /> Budget Mensile
          </h3>
          <div className="space-y-4">
            <input 
              type="number" 
              value={settings.monthlyBudget} 
              onChange={(e) => onUpdate({ ...settings, monthlyBudget: Number(e.target.value) })} 
              className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-black text-2xl"
            />
            <div className="flex items-center gap-3">
              <Globe size={16} className="text-gray-400" />
              <select 
                value={settings.currency}
                onChange={(e) => onUpdate({ ...settings, currency: e.target.value })}
                className="flex-1 bg-gray-50 dark:bg-gray-700 dark:text-white px-4 py-2 rounded-xl text-sm font-bold border-none outline-none"
              >
                <option value="€">Euro (€)</option>
                <option value="$">Dollaro ($)</option>
                <option value="£">Sterlina (£)</option>
                <option value="CHF">Franco (CHF)</option>
              </select>
            </div>
          </div>
        </div>

        {/* Card Aspetto */}
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
            {settings.isDarkMode ? <Moon className="text-emerald-500" size={20} /> : <Sun className="text-emerald-500" size={20} />} 
            Aspetto
          </h3>
          <div className="flex items-center justify-between p-6 rounded-2xl bg-gray-50 dark:bg-gray-700">
            <span className="font-bold text-gray-600 dark:text-gray-300">Tema {settings.isDarkMode ? 'Scuro' : 'Chiaro'}</span>
            <button 
              onClick={() => onUpdate({ ...settings, isDarkMode: !settings.isDarkMode })}
              className={`w-14 h-8 rounded-full relative transition-colors p-1 ${settings.isDarkMode ? 'bg-emerald-500' : 'bg-gray-300'}`}
            >
              <div className={`w-6 h-6 bg-white rounded-full shadow-sm transition-all ${settings.isDarkMode ? 'translate-x-6' : 'translate-x-0'}`}></div>
            </button>
          </div>
        </div>
      </div>

      {/* Card Dati e Archivio */}
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
          <FileDown className="text-emerald-500" size={20} /> Dati e Archivio
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button 
            onClick={() => setShowHistory(true)}
            className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"
          >
            <History size={20} /> Storico Mesi
          </button>
          <button 
            onClick={handleExportCSV}
            className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"
          >
            <Download size={20} /> Esporta CSV
          </button>
        </div>
      </div>

      {/* Card Sicurezza */}
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-red-50 dark:border-red-900/10 shadow-sm">
        <h3 className="text-lg font-bold text-red-500 mb-6 flex items-center gap-2">
          <ShieldCheck size={20} /> Sicurezza
        </h3>
        <div className="space-y-4">
          <button 
            onClick={() => auth.signOut()}
            className="w-full flex items-center justify-center gap-3 p-5 bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-2xl font-bold hover:bg-emerald-50 dark:hover:bg-emerald-900/20 transition-all"
          >
            <LogOut size={20} /> Disconnetti
          </button>

          <div className="flex flex-col gap-2 pt-4 border-t border-gray-100 dark:border-gray-700">
            <button 
              onClick={handleDeleteAccount}
              className="w-full py-3 text-red-400 text-xs font-bold hover:text-red-600 transition-all flex items-center justify-center gap-2"
            >
              <Trash2 size={14} /> Cancella Account
            </button>
            <button 
              onClick={onClearData}
              className="w-full text-gray-400 text-[10px] font-bold uppercase tracking-wider hover:text-red-500 transition-all"
            >
              Elimina tutti i dati dal Cloud
            </button>
          </div>
        </div>
      </div>

      <div className="text-center pt-4">
        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-[0.3em]">MintFlow v2.5 • AI Powered</p>
      </div>

      {/* Modal Modifica Profilo */}
      <Modal 
        isOpen={showProfileModal} 
        onClose={() => setShowProfileModal(false)} 
        title="Modifica Profilo"
      >
        <div className="space-y-4">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nome Utente</label>
            <div className="relative">
              <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text" 
                value={tempName} 
                onChange={(e) => setTempName(e.target.value)} 
                className="w-full pl-12 pr-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-medium"
              />
            </div>
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Email</label>
            <div className="relative">
              <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="email" 
                value={tempEmail} 
                onChange={(e) => setTempEmail(e.target.value)} 
                className="w-full pl-12 pr-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-medium"
              />
            </div>
          </div>
          <button 
            onClick={handleUpdateProfile} 
            disabled={isUpdating}
            className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2"
          >
            {isUpdating ? <CheckCircle2 className="animate-spin" /> : "Salva Modifiche"}
          </button>
        </div>
      </Modal>

