          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nuova Password</label>
            <div className="relative">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="password" 
                value={newPassword} 
                onChange={(e) => setNewPassword(e.target.value)} 
                className="w-full pl-12 pr-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-medium"
                placeholder="Almeno 6 caratteri"
              />
            </div>
          </div>
          <button 
            onClick={handleUpdatePassword} 
            disabled={isUpdating}
            className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2"
          >
            {isUpdating ? <CheckCircle2 className="animate-spin" /> : "Aggiorna Password"}
          </button>
        </div>
