          <div className="max-h-60 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
            {settings.wallets.map(w => (
              <div key={w.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-500 rounded-lg">
                    <Wallet size={16} />
                  </div>
                  <span className="font-bold dark:text-white text-sm">{w.name}</span>
                </div>
                <button 
                  onClick={() => onUpdate({ ...settings, wallets: settings.wallets.filter(x => x.id !== w.id) })}
                  className="text-gray-400 hover:text-red-500 transition-colors"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
          </div>
          <button 
            onClick={() => {
