            <div key={w.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-2xl">
              <div className="flex items-center gap-3 font-bold dark:text-white"><Wallet className="text-emerald-500" /> {w.name}</div>
              <button onClick={() => onUpdate({ ...settings, wallets: settings.wallets.filter(x => x.id !== w.id) })} className="text-red-400 hover:text-red-600"><Trash2 size={18} /></button>
            </div>
          ))}
          <button onClick={() => { const n = prompt("Nome nuovo portafoglio:"); if(n) onUpdate({...settings, wallets: [...settings.wallets, {id: 'w'+Date.now(), name: n, method: n as any, icon: 'credit-card'}]}) }} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 mt-4"><Plus size={20} /> Aggiungi Portafoglio</button>
        </div>
      </div>
    </div>
  );

  if (view === 'categories') return (
    <div className="animate-in slide-in-from-right duration-300 min-h-screen bg-white dark:bg-gray-900 -mt-8 -mx-4 px-4 pt-8">
