      {/* Modale Password */}
      <Modal isOpen={showPasswordModal} onClose={() => setShowPasswordModal(false)} title="Cambia Password">
        <div className="space-y-4">
          <input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white" placeholder="Nuova Password" />
          <button onClick={handleUpdatePassword} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold">{isUpdating ? "Caricamento..." : "Aggiorna"}</button>
        </div>
      </Modal>
    </div>
  );
};

