              <div className="flex items-center gap-3 font-bold dark:text-white"><Tag className="text-emerald-500" /> {c.name}</div>
              {!c.isSubscriptionDefault && (
                <button onClick={() => onUpdate({ ...settings, categories: settings.categories.filter(x => x.id !== c.id) })} className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all"><Trash2 size={18} /></button>
              )}
            </div>
          ))}

          {isAdding ? (
            <div className="space-y-3 p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <input 
                autoFocus
                type="text" 
                value={newItemName} 
                onChange={(e) => setNewItemName(e.target.value)}
                placeholder="Nome categoria..."
                className="w-full px-4 py-3 rounded-xl bg-white dark:bg-gray-700 border-none outline-none dark:text-white font-bold"
              />
              <div className="flex gap-2">
                <button onClick={() => handleAddItem('category')} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold text-sm">Salva</button>
                <button onClick={() => setIsAdding(false)} className="px-4 py-3 bg-white dark:bg-gray-600 text-gray-400 rounded-xl font-bold text-sm">Annulla</button>
              </div>
