interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  expenses,
  email
}) => {
  const [view, setView] = useState<'main' | 'history' | 'wallets' | 'categories'>('main');
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  const [isAdding, setIsAdding] = useState(false);
  const [newItemName, setNewItemName] = useState('');

  const [tempName, setTempName] = useState(settings.name);
  const [tempEmail, setTempEmail] = useState(email || '');
  const [isUpdating, setIsUpdating] = useState(false);
  const [newPassword, setNewPassword] = useState('');

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 3000);
  };

  const handleUpdateProfile = async () => {
    setIsUpdating(true);
    try {
      if (tempName !== settings.name) {
        await auth.updateProfile(tempName);
        onUpdate({ ...settings, name: tempName });
      }
      if (tempEmail !== email) {
        await auth.updateEmail(tempEmail);
        showFeedback("Email inviata!");
      } else {
        showFeedback("Profilo aggiornato!");
      }
      setShowProfileModal(false);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdatePassword = async () => {
    if (newPassword.length < 6) return alert("Minimo 6 caratteri");
    setIsUpdating(true);
    try {
      await auth.updatePassword(newPassword);
      showFeedback("Password aggiornata!");
      setShowPasswordModal(false);
      setNewPassword('');
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDeleteAccount = async () => {
    if (window.confirm("Vuoi eliminare DEFINITIVAMENTE l'account?")) {
      try {
        setIsUpdating(true);
        await auth.deleteAccount();
      } catch (err: any) {
        await auth.signOut();
      } finally {
        setIsUpdating(false);
      }
    }
  };

  const handleAddItem = (type: 'wallet' | 'category') => {
    if (!newItemName.trim()) return;

    if (type === 'wallet') {
      const newWallet: WalletConfig = {
        id: 'w' + Date.now(),
        name: newItemName.trim(),
        method: newItemName.trim() as PaymentMethod,
        icon: 'credit-card'
      };
      onUpdate({ ...settings, wallets: [...settings.wallets, newWallet] });
    } else {
      const newCat: CategoryConfig = {
        id: 'c' + Date.now(),
        name: newItemName.trim()
      };
      onUpdate({ ...settings, categories: [...settings.categories, newCat] });
    }

    setNewItemName('');
    setIsAdding(false);
    showFeedback("Aggiunto con successo!");
  };

  if (view === 'history') return <HistoryView expenses={expenses} onClose={() => setView('main')} currency={settings.currency} />;

  if (view === 'wallets') return (
    <div className="animate-in slide-in-from-right duration-300 min-h-screen bg-white dark:bg-gray-900 -mt-8 -mx-4 px-4 pt-8">
      <div className="max-w-4xl mx-auto space-y-6 pb-20">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6"><ChevronLeft /> Impostazioni</button>
        <h2 className="text-3xl font-bold dark:text-white">Gestione Ricariche</h2>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm space-y-4">
          {settings.wallets.map(w => (
            <div key={w.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-2xl relative">
              <div className="flex items-center gap-3 font-bold dark:text-white"><Wallet className="text-emerald-500" /> {w.name}</div>
              <button 
                type="button"
                onClick={() => {
                  console.log("Elimina wallet:", w.name);
                  onUpdate({ ...settings, wallets: settings.wallets.filter(x => x.id !== w.id) });
                }} 
                className="p-2.5 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-all flex items-center justify-center relative z-30"
              >
                <Trash2 size={18} className="pointer-events-none" />
              </button>
            </div>
          ))}

          {isAdding ? (
            <div className="space-y-3 p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <input 
                autoFocus
                type="text" 
                value={newItemName} 
                onChange={(e) => setNewItemName(e.target.value)}
                placeholder="Nome portafoglio..."
                className="w-full px-4 py-3 rounded-xl bg-white dark:bg-gray-700 border-none outline-none dark:text-white font-bold"
              />
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('wallet')} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold text-sm">Salva</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-3 bg-white dark:bg-gray-600 text-gray-400 rounded-xl font-bold text-sm">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 mt-4 transition-transform active:scale-95"><Plus size={20} /> Aggiungi Portafoglio</button>
          )}
        </div>
      </div>
    </div>
  );

  if (view === 'categories') return (
    <div className="animate-in slide-in-from-right duration-300 min-h-screen bg-white dark:bg-gray-900 -mt-8 -mx-4 px-4 pt-8">
      <div className="max-w-4xl mx-auto space-y-6 pb-20">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6"><ChevronLeft /> Impostazioni</button>
        <h2 className="text-3xl font-bold dark:text-white">Gestione Categorie</h2>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm space-y-4">
          {settings.categories.map(c => (
            <div key={c.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-2xl relative">
              <div className="flex items-center gap-3 font-bold dark:text-white"><Tag className="text-emerald-500" /> {c.name}</div>
              {!c.isSubscriptionDefault && (
                <button 
                  type="button"
                  onClick={() => {
                    console.log("Elimina categoria:", c.name);
                    onUpdate({ ...settings, categories: settings.categories.filter(x => x.id !== c.id) });
                  }} 
                  className="p-2.5 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-all flex items-center justify-center relative z-30"
                >
                  <Trash2 size={18} className="pointer-events-none" />
                </button>
              )}
            </div>
          ))}

          {isAdding ? (
            <div className="space-y-3 p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <input 
                autoFocus
                type="text" 
                value={newItemName} 
                onChange={(e) => setNewItemName(e.target.value)}
                placeholder="Nome categoria..."
                className="w-full px-4 py-3 rounded-xl bg-white dark:bg-gray-700 border-none outline-none dark:text-white font-bold"
              />
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('category')} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold text-sm">Salva</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-3 bg-white dark:bg-gray-600 text-gray-400 rounded-xl font-bold text-sm">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 mt-4 transition-transform active:scale-95"><Plus size={20} /> Aggiungi Categoria</button>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {feedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 bg-emerald-500 text-white rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in zoom-in duration-300">
          <CheckCircle2 size={16} />
          <span className="font-bold text-xs uppercase tracking-wider">{feedback}</span>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm relative overflow-hidden">
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-4 rounded-3xl text-white">
              <User size={32} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-gray-800 dark:text-white">Il tuo Profilo</h3>
              <p className="text-gray-400 text-sm">{email}</p>
            </div>
          </div>
          <button type="button" onClick={() => setShowProfileModal(true)} className="flex items-center gap-2 px-4 py-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-xl font-bold text-xs hover:bg-emerald-100 transition-all">
            <Edit3 size={14} /> Modifica
          </button>
        </div>
        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3 ml-1">Nome Visualizzato</label>
          <div className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 dark:text-white font-bold text-lg">{settings.name}</div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-hidden">
        <SettingsRow icon={<Lock className="text-emerald-500" size={20} />} label="Cambia Password" onClick={() => setShowPasswordModal(true)} />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow icon={<Wallet className="text-emerald-500" size={20} />} label="Cambia Ricariche" onClick={() => setView('wallets')} />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow icon={<Tag className="text-emerald-500" size={20} />} label="Cambia Categorie" onClick={() => setView('categories')} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2"><DollarSign className="text-emerald-500" size={20} /> Budget Mensile</h3>
          <div className="space-y-4">
            <input type="number" value={settings.monthlyBudget} onChange={(e) => onUpdate({ ...settings, monthlyBudget: Number(e.target.value) })} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-black text-2xl" />
            <select value={settings.currency} onChange={(e) => onUpdate({ ...settings, currency: e.target.value })} className="w-full bg-gray-50 dark:bg-gray-700 dark:text-white px-4 py-3 rounded-2xl font-bold text-sm outline-none border-none">
              <option value="€">Euro (€)</option>
              <option value="$">Dollaro ($)</option>
              <option value="£">Sterlina (£)</option>
            </select>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">{settings.isDarkMode ? <Moon className="text-emerald-500" size={20} /> : <Sun className="text-emerald-500" size={20} />} Aspetto</h3>
          <div className="flex items-center justify-between p-6 rounded-2xl bg-gray-50 dark:bg-gray-700">
            <span className="font-bold text-gray-600 dark:text-gray-300">Tema {settings.isDarkMode ? 'Scuro' : 'Chiaro'}</span>
            <button type="button" onClick={() => onUpdate({ ...settings, isDarkMode: !settings.isDarkMode })} className={`w-14 h-8 rounded-full relative transition-colors p-1 ${settings.isDarkMode ? 'bg-emerald-500' : 'bg-gray-300'}`}>
              <div className={`w-6 h-6 bg-white rounded-full shadow-sm transition-all ${settings.isDarkMode ? 'translate-x-6' : 'translate-x-0'}`}></div>
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2"><FileDown className="text-emerald-500" size={20} /> Dati e Archivio</h3>
        <div className="grid grid-cols-2 gap-4">
          <button type="button" onClick={() => setView('history')} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><History size={20} /> Storico Mesi</button>
          <button type="button" onClick={() => alert("Funzione esportazione CSV pronta")} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><Download size={20} /> Esporta CSV</button>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-red-50 dark:border-red-900/10 shadow-sm">
        <h3 className="text-lg font-bold text-red-500 mb-6 flex items-center gap-2"><ShieldCheck size={20} /> Sicurezza</h3>
        <div className="space-y-4">
          <button type="button" onClick={() => auth.signOut()} className="w-full flex items-center justify-center gap-3 p-5 bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-2xl font-bold hover:bg-gray-100 dark:hover:bg-gray-600 transition-all"><LogOut size={20} /> Disconnetti</button>
          <div className="flex flex-col gap-2 pt-4 border-t border-gray-100 dark:border-gray-700">
            <button type="button" onClick={handleDeleteAccount} className="w-full py-3 text-red-400 text-xs font-bold hover:text-red-600 transition-all flex items-center justify-center gap-2"><Trash2 size={14} /> Cancella Account</button>
            <button type="button" onClick={onClearData} className="w-full flex items-center justify-center gap-2 text-gray-400 text-[10px] font-bold uppercase tracking-wider hover:text-red-500 transition-all"><Trash2 size={10} /> Elimina dati Cloud</button>
          </div>
        </div>
      </div>

      <div className="text-center pt-4"><p className="text-[10px] text-gray-400 font-bold uppercase tracking-[0.3em]">MintFlow v2.5 • AI Powered</p></div>

      <Modal isOpen={showProfileModal} onClose={() => setShowProfileModal(false)} title="Modifica Profilo">
        <div className="space-y-4">
          <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white" placeholder="Nome" />
          <input type="email" value={tempEmail} onChange={(e) => setTempEmail(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white" placeholder="Email" />
          <button type="button" onClick={handleUpdateProfile} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg mt-2">{isUpdating ? "..." : "Salva"}</button>
        </div>
      </Modal>

      <Modal isOpen={showPasswordModal} onClose={() => setShowPasswordModal(false)} title="Cambia Password">
        <div className="space-y-4">
          <input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white" placeholder="Minimo 6 caratteri" />
          <button type="button" onClick={handleUpdatePassword} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg mt-2">{isUpdating ? "..." : "Aggiorna"}</button>
        </div>
      </Modal>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { ReceiptScanner } from './components/ReceiptScanner';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
// Fix: Added missing import for Auth component
import { Auth } from './components/Auth';
import { Expense, UserSettings, PaymentMethod, WalletConfig, CategoryConfig } from './types';
import { Plus, ScanLine, Cloud, Loader2, CreditCard, PartyPopper, History } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { startOfMonth, format } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [showNewMonthToast, setShowNewMonthToast] = useState(false);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultWallets: WalletConfig[] = [
      { id: 'w1', name: 'Prepagata Flash', method: PaymentMethod.Flash, icon: 'zap' },
      { id: 'w2', name: 'Prepagata Revolut', method: PaymentMethod.Revolut, icon: 'wallet' },
      { id: 'w3', name: 'App Q8', method: PaymentMethod.AppQ8, icon: 'fuel' }
    ];

    const defaultCategories: CategoryConfig[] = [
      { id: 'c1', name: 'Sigarette' },
      { id: 'c2', name: 'Benzina' },
      { id: 'c3', name: 'Autostrada' },
      { id: 'c4', name: 'Ricarica Chiavetta' },
      { id: 'c5', name: 'Svago' },
      { id: 'c6', name: 'Salute' },
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true },
      { id: 'c8', name: 'Altro' }
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories
    };

    if (!saved) return defaultSettings;

    try {
      const parsed = JSON.parse(saved);
      if (!parsed.categories) {
        parsed.categories = defaultCategories;
      }
      return { ...defaultSettings, ...parsed };
    } catch {
      return defaultSettings;
    }
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  useEffect(() => {
    const initSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session?.user) {
        const metadata = session.user.user_metadata;
        const displayName = metadata.full_name || metadata.display_name || metadata.name || session.user.email?.split('@')[0] || 'Utente';
        setUserSettings(prev => ({ ...prev, name: displayName }));
      }
      setIsInitialLoading(false);
    };
    initSession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session?.user?.id) {
      const loadData = async () => {
        try {
          setIsLoading(true);
          const data = await db.getExpenses(session.user.id);
          setExpenses(data);
          const today = new Date();
          const currentMonthKey = format(startOfMonth(today), 'yyyy-MM');
          const lastArchivedMonth = localStorage.getItem('mintflow_last_archived');
          if (today.getDate() === 1 && lastArchivedMonth !== currentMonthKey) {
            setShowNewMonthToast(true);
            localStorage.setItem('mintflow_last_archived', currentMonthKey);
            setTimeout(() => setShowNewMonthToast(false), 8000);
          }
        } catch (err) {
          console.error("Errore caricamento:", err);
        } finally {
          setIsLoading(false);
        }
      };
      loadData();
    }
  }, [session]);

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
    if (userSettings.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [userSettings]);

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      if (prefill?.id) {
        const updated = await db.updateExpense(prefill.id, expenseData);
        if (updated) setExpenses(prev => prev.map(e => e.id === updated.id ? updated : e));
      } else {
        const newExpense = await db.addExpense(expenseData, session.user.id);
        if (newExpense) setExpenses(prev => [newExpense, ...prev]);
      }
      setShowForm(false);
      setPrefill(null);
    } catch (err: any) {
      alert(`Errore Cloud: ${err.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const deleteExpense = useCallback(async (id: string) => {
    console.log("Tentativo cancellazione ID:", id);
    if (!window.confirm("Eliminare questa spesa?")) return;
    try {
      setIsSyncing(true);
      await db.deleteExpense(id);
      setExpenses(prev => prev.filter(e => e.id !== id));
      console.log("Cancellazione completata ID:", id);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  }, []);

  const handleClearData = async () => {
    if (window.confirm('Resettare tutte le spese dal cloud?')) {
      try {
        setIsSyncing(true);
        await db.clearAll(session.user.id);
        setExpenses([]);
      } catch (err: any) {
        alert("Errore: " + err.message);
      } finally {
        setIsSyncing(false);
      }
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex flex-col items-center justify-center gap-4">
        <div className="bg-emerald-500 p-5 rounded-3xl text-white shadow-2xl animate-pulse">
          <CreditCard size={48} />
        </div>
        <div className="flex flex-col items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold">
          <Loader2 size={20} className="animate-spin" />
          <span>MintFlow Sync...</span>
        </div>
      </div>
    );
  }

  // Fix: Auth is now properly imported
  if (!session) return <Auth onSuccess={() => {}} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {showNewMonthToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm bg-emerald-500 text-white p-6 rounded-[2rem] shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-4 duration-500">
            <div className="bg-white/20 p-3 rounded-2xl shrink-0"><PartyPopper size={24} /></div>
            <div>
              <p className="font-bold text-sm">Nuovo mese iniziato! 🚀</p>
              <p className="text-[10px] opacity-90 uppercase font-bold tracking-widest mt-1 flex items-center gap-1"><History size={10} /> Dati archiviati</p>
            </div>
            <button onClick={() => setShowNewMonthToast(false)} className="ml-auto opacity-50">✕</button>
          </div>
        )}

        <div className="flex justify-end items-center mb-4 px-2">
          <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-gray-400">
            {isSyncing ? <><Loader2 size={12} className="animate-spin text-emerald-500" /> <span className="text-emerald-500">Cloud Sync...</span></> : <><Cloud size={12} className="text-emerald-400" /> <span>Sincronizzato</span></>}
          </div>
        </div>

        {activeTab !== 'dashboard' && (
          <div className="mb-6">
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white capitalize">
               {activeTab === 'list' ? 'Le tue Spese' : 
                activeTab === 'ai' ? 'AI Insights' : 
                activeTab === 'ricariche' ? 'Portafogli' : 
                activeTab === 'subscriptions' ? 'Abbonamenti' : 'Impostazioni'}
            </h1>
          </div>
        )}

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
             <Loader2 size={48} className="text-emerald-500 animate-spin" />
             <p className="text-gray-400 font-medium">Caricamento...</p>
          </div>
        ) : (
          <>
            {activeTab === 'dashboard' && (
              <Dashboard 
                expenses={expenses} budget={userSettings.monthlyBudget} userName={userSettings.name} currency={userSettings.currency} wallets={userSettings.wallets}
              />
            )}

            {activeTab === 'list' && (
              <div className="space-y-6">
                <div className="flex gap-3">
                  <button onClick={() => { setPrefill(null); setShowForm(true); }} className="flex-1 bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-lg"><Plus size={20} /> <span className="font-bold">Aggiungi</span></button>
                  <button onClick={() => setShowScanner(true)} className="flex-1 bg-white dark:bg-gray-800 border-2 border-emerald-100 dark:border-gray-700 text-emerald-600 dark:text-emerald-400 px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-sm"><ScanLine size={20} /> <span className="font-bold">Scan</span></button>
                </div>
                <ExpenseList expenses={expenses} onDelete={deleteExpense} onEdit={(ex) => {setPrefill(ex); setShowForm(true);}} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
              </div>
            )}

            {activeTab === 'subscriptions' && (
              <SubscriptionsView expenses={expenses} onAddSub={() => { 
                const subCat = userSettings.categories.find(c => c.isSubscriptionDefault)?.name || 'Abbonamenti';
                setPrefill({ isSubscription: true, category: subCat }); 
                setShowForm(true); 
              }} onDelete={deleteExpense} currency={userSettings.currency} />
            )}

            {activeTab === 'ricariche' && (
              <RicaricheView onRefill={(wallet) => {
                setPrefill({ 
                  description: `Ricarica ${wallet.name}`, 
                  category: 'Altro', 
                  paymentMethod: PaymentMethod.Bancomat, 
                  date: format(new Date(), 'yyyy-MM-dd') 
                });
                setShowForm(true);
              }} expenses={expenses} currency={userSettings.currency} wallets={userSettings.wallets} />
            )}

            {activeTab === 'ai' && <AiInsights expenses={expenses} />}
            {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={handleClearData} expenses={expenses} email={session.user.email} />}
          </>
        )}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl relative animate-in zoom-in-95 duration-200">
              <button onClick={() => { setShowForm(false); setPrefill(null); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600">✕</button>
              <h2 className="text-2xl font-bold mb-6 text-gray-800 dark:text-white">{prefill?.id ? 'Modifica' : 'Nuova Spesa'}</h2>
              <ExpenseForm onSubmit={handleSaveExpense} onCancel={() => { setShowForm(false); setPrefill(null); }} initialData={prefill || undefined} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
            </div>
          </div>
        )}

        {showScanner && <ReceiptScanner onDetected={(res) => { setPrefill({...res, date: format(new Date(), 'yyyy-MM-dd')}); setShowScanner(false); setShowForm(true); }} onClose={() => setShowScanner(false)} />}
      </div>
    </Layout>
  );
};

