};

import React, { useState, useEffect } from 'react';
import { CategoryConfig, Expense, PaymentMethod, WalletConfig } from '../types';
import { SmartCategorizer } from './SmartCategorizer';
import { Loader2, Save, Repeat, Building, CreditCard, Banknote, Fuel } from 'lucide-react';
import { isSameMonth, isAfter, startOfMonth, endOfMonth, parseISO, startOfToday } from 'date-fns';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => Promise<void> | void;
  onCancel: () => void;
  initialData?: Partial<Expense>;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ 
  onSubmit, 
  onCancel, 
  initialData, 
  currency = '€', 
  wallets, 
  categories 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<string>('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.Contanti);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSubscription, setIsSubscription] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (initialData) {
      if (initialData.description !== undefined) setDescription(initialData.description);
      if (initialData.amount !== undefined) setAmount(initialData.amount.toString());
      if (initialData.category !== undefined) setCategory(initialData.category);
      if (initialData.paymentMethod !== undefined) setPaymentMethod(initialData.paymentMethod);
      if (initialData.date !== undefined) setDate(initialData.date);
      if (initialData.isSubscription !== undefined) setIsSubscription(initialData.isSubscription || false);
    } else {
      setCategory(categories[categories.length - 1]?.name || 'Altro');
    }
  }, [initialData, categories]);

  const handleFormSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    const parsedAmount = parseFloat(amount.replace(',', '.'));
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      alert("Inserisci un importo valido");
      return;
    }

    // --- LOGICA VALIDAZIONE DATA ---
    const selectedDate = parseISO(date);
    const today = startOfToday();
    const startOfThisMonth = startOfMonth(today);
    const endOfThisMonth = endOfMonth(today);

    // 1. CONFERMA PER DATE FUTURE
    if (isAfter(selectedDate, endOfThisMonth)) {
      const confirmFuture = window.confirm("📅 Questa è una data futura, sei sicuro di voler aggiungere?");
      if (!confirmFuture) return; // Annulla l'azione se l'utente preme No
    }

    // 2. CONFERMA MESI PASSATI
    const isPastMonth = !isSameMonth(selectedDate, today) && selectedDate < startOfThisMonth;
    if (isPastMonth) {
      const confirmHistory = window.confirm("📅 Nota: La data inserita appartiene a un mese passato.\n\nVuoi confermare l'inserimento di questa spesa nel tuo archivio storico?");
      if (!confirmHistory) return;
    }

    setIsSubmitting(true);
    try {
      await onSubmit({
        description: description.trim() || 'Spesa senza nome',
        amount: parsedAmount,
        category: category || 'Altro',
        paymentMethod,
        date,
        isSubscription
      });
    } catch (err: any) {
      console.error("Errore salvataggio form:", err);
      alert("Errore durante il salvataggio: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const getPaymentIcon = (method: PaymentMethod) => {
    const wallet = wallets.find(w => w.method === method);
    if (wallet) return wallet.icon === 'zap' ? <Zap size={16} /> : wallet.icon === 'fuel' ? <Fuel size={16} /> : <CreditCard size={16} />;
    return method === PaymentMethod.Contanti ? <Banknote size={16} /> : <Building size={16} />;
  };

  const Zap = ({size}: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>;

  return (
    <form onSubmit={handleFormSubmit} className="space-y-5">
      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Descrizione</label>
        <input 
          type="text" 
          value={description} 
          onChange={(e) => setDescription(e.target.value)} 
          placeholder="Cosa hai acquistato?" 
          className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" 
          required 
        />
        <SmartCategorizer description={description} onSuggest={setCategory} categories={categories} />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Importo</label>
          <input 
            type="text" 
            inputMode="decimal" 
            value={amount} 
            onChange={(e) => setAmount(e.target.value)} 
            placeholder={`0.00 ${currency}`} 
            className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-bold text-xl" 
            required 
          />
        </div>
        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Data</label>
          <input 
            type="date" 
            value={date} 
            onChange={(e) => setDate(e.target.value)} 
            className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" 
            required 
          />
        </div>
      </div>

      <button type="button" onClick={() => setIsSubscription(!isSubscription)} className={`w-full flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isSubscription ? 'bg-emerald-50 border-emerald-500 text-emerald-600' : 'bg-gray-50 border-transparent text-gray-400'}`}>
        <div className="flex items-center gap-2 font-bold text-sm"><Repeat size={18} /> Abbonamento Ricorrente</div>
        <div className={`w-10 h-6 rounded-full relative transition-colors ${isSubscription ? 'bg-emerald-500' : 'bg-gray-300'}`}><div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isSubscription ? 'left-5' : 'left-1'}`}></div></div>
      </button>

      <div>
        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Metodo di Pagamento</label>
        <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
          {[PaymentMethod.Contanti, PaymentMethod.Bancomat, ...wallets.map(w => w.method)].map((m) => (
            <button key={m} type="button" onClick={() => setPaymentMethod(m)} className={`flex items-center gap-2 px-3 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${paymentMethod === m ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
              {getPaymentIcon(m)} <span className="truncate">{wallets.find(w => w.method === m)?.name || m}</span>
            </button>
          ))}
        </div>
      </div>

      <div>
        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Categoria</label>
        <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
          {categories.map((cat) => (
            <button key={cat.id} type="button" onClick={() => setCategory(cat.name)} className={`px-4 py-3 rounded-xl text-xs font-bold border-2 transition-all ${category === cat.name ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
              {cat.name}
            </button>
          ))}
        </div>
      </div>

      <div className="flex gap-4 pt-4">
        <button type="button" onClick={onCancel} className="flex-1 px-6 py-4 rounded-2xl border-2 border-gray-100 dark:border-gray-700 text-gray-400 font-bold hover:bg-gray-50 transition-colors">Annulla</button>
        <button type="submit" disabled={isSubmitting} className="flex-1 px-6 py-4 rounded-2xl bg-emerald-500 text-white font-bold shadow-xl shadow-emerald-100 dark:shadow-none disabled:opacity-70 flex items-center justify-center gap-2 active:scale-95 transition-transform">
          {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />} Salva
        </button>
      </div>
    </form>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { ReceiptScanner } from './components/ReceiptScanner';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
import { Auth } from './components/Auth';
import { Expense, UserSettings, PaymentMethod, WalletConfig, CategoryConfig } from './types';
import { Plus, ScanLine, Cloud, Loader2, CreditCard, PartyPopper, History, CheckCircle2 } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { startOfMonth, format, isSameMonth, parseISO, isAfter, endOfMonth } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [showNewMonthToast, setShowNewMonthToast] = useState(false);
  const [successToast, setSuccessToast] = useState<string | null>(null);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultWallets: WalletConfig[] = [
      { id: 'w1', name: 'Prepagata Flash', method: PaymentMethod.Flash, icon: 'zap' },
      { id: 'w2', name: 'Prepagata Revolut', method: PaymentMethod.Revolut, icon: 'wallet' },
      { id: 'w3', name: 'App Q8', method: PaymentMethod.AppQ8, icon: 'fuel' }
    ];

    const defaultCategories: CategoryConfig[] = [
      { id: 'c1', name: 'Sigarette' },
      { id: 'c2', name: 'Benzina' },
      { id: 'c3', name: 'Autostrada' },
      { id: 'c4', name: 'Ricarica Chiavetta' },
      { id: 'c5', name: 'Svago' },
      { id: 'c6', name: 'Salute' },
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true },
      { id: 'c8', name: 'Altro' }
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories
    };

    if (!saved) return defaultSettings;

    try {
      const parsed = JSON.parse(saved);
      if (!parsed.categories) {
        parsed.categories = defaultCategories;
      }
      return { ...defaultSettings, ...parsed };
    } catch {
      return defaultSettings;
    }
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  useEffect(() => {
    const initSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session?.user) {
        const metadata = session.user.user_metadata;
        const displayName = metadata.full_name || metadata.display_name || metadata.name || session.user.email?.split('@')[0] || 'Utente';
        setUserSettings(prev => ({ ...prev, name: displayName }));
      }
      setIsInitialLoading(false);
    };
    initSession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session?.user?.id) {
      const loadData = async () => {
        try {
          setIsLoading(true);
          const data = await db.getExpenses(session.user.id);
          setExpenses(data);
          const today = new Date();
          const currentMonthKey = format(startOfMonth(today), 'yyyy-MM');
          const lastArchivedMonth = localStorage.getItem('mintflow_last_archived');
          if (today.getDate() === 1 && lastArchivedMonth !== currentMonthKey) {
            setShowNewMonthToast(true);
            localStorage.setItem('mintflow_last_archived', currentMonthKey);
            setTimeout(() => setShowNewMonthToast(false), 8000);
          }
        } catch (err) {
          console.error("Errore caricamento:", err);
        } finally {
          setIsLoading(false);
        }
      };
      loadData();
    }
  }, [session]);

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
    if (userSettings.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [userSettings]);

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      const expenseDate = parseISO(expenseData.date);
      const today = new Date();
      const isPast = !isSameMonth(expenseDate, today) && expenseDate < startOfMonth(today);
      const isFutureDate = isAfter(expenseDate, endOfMonth(today));

      let savedExpense: Expense | null = null;
      if (prefill?.id) {
        savedExpense = await db.updateExpense(prefill.id, expenseData);
        if (savedExpense) setExpenses(prev => prev.map(e => e.id === savedExpense!.id ? savedExpense! : e));
        setSuccessToast("Modifica salvata!");
      } else {
        savedExpense = await db.addExpense(expenseData, session.user.id);
        if (savedExpense) setExpenses(prev => [savedExpense!, ...prev]);
        setSuccessToast(isPast ? "Spesa salvata nello storico!" : isFutureDate ? "Spesa futura programmata!" : "Spesa aggiunta!");
      }

      setShowForm(false);
      setPrefill(null);

      // Se la spesa non è del mese corrente, portiamo l'utente sulla lista per fargliela vedere
      if (isPast || isFutureDate) {
        setActiveTab('list');
      }

      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      alert(`Errore Cloud: ${err.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const deleteExpense = useCallback(async (id: string) => {
    if (!window.confirm("Sei sicuro di voler eliminare questa spesa?")) return;
    try {
      setIsSyncing(true);
      await db.deleteExpense(id);
      setExpenses(prev => prev.filter(e => e.id !== id));
      setSuccessToast("Spesa eliminata.");
      setTimeout(() => setSuccessToast(null), 2000);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  }, []);

  const handleClearData = async () => {
    if (window.confirm('Resettare tutte le spese dal cloud?')) {
      try {
        setIsSyncing(true);
        await db.clearAll(session.user.id);
        setExpenses([]);
      } catch (err: any) {
        alert("Errore: " + err.message);
      } finally {
        setIsSyncing(false);
      }
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex flex-col items-center justify-center gap-4">
        <div className="bg-emerald-500 p-5 rounded-3xl text-white shadow-2xl animate-pulse">
          <CreditCard size={48} />
        </div>
        <div className="flex flex-col items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold">
          <Loader2 size={20} className="animate-spin" />
          <span>MintFlow Sync...</span>
        </div>
      </div>
    );
  }

  if (!session) return <Auth onSuccess={() => {}} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {/* Success Toast */}
        {successToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in slide-in-from-top-4 duration-300">
            <CheckCircle2 size={18} />
            <span className="font-bold text-sm">{successToast}</span>
          </div>
        )}

        {showNewMonthToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm bg-emerald-500 text-white p-6 rounded-[2rem] shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-4 duration-500">
            <div className="bg-white/20 p-3 rounded-2xl shrink-0"><PartyPopper size={24} /></div>
            <div>
              <p className="font-bold text-sm">Nuovo mese iniziato! 🚀</p>
              <p className="text-[10px] opacity-90 uppercase font-bold tracking-widest mt-1 flex items-center gap-1"><History size={10} /> Dati archiviati</p>
            </div>
            <button onClick={() => setShowNewMonthToast(false)} className="ml-auto opacity-50">✕</button>
          </div>
        )}

        <div className="flex justify-end items-center mb-4 px-2">
          <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-gray-400">
            {isSyncing ? <><Loader2 size={12} className="animate-spin text-emerald-500" /> <span className="text-emerald-500">Cloud Sync...</span></> : <><Cloud size={12} className="text-emerald-400" /> <span>Sincronizzato</span></>}
          </div>
        </div>

        {activeTab !== 'dashboard' && (
          <div className="mb-6">
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white capitalize">
               {activeTab === 'list' ? 'Le tue Spese' : 
                activeTab === 'ai' ? 'AI Insights' : 
                activeTab === 'ricariche' ? 'Portafogli' : 
                activeTab === 'subscriptions' ? 'Abbonamenti' : 'Impostazioni'}
            </h1>
          </div>
        )}

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
             <Loader2 size={48} className="text-emerald-500 animate-spin" />
             <p className="text-gray-400 font-medium">Caricamento...</p>
          </div>
        ) : (
          <>
            {activeTab === 'dashboard' && (
              <Dashboard 
                expenses={expenses} budget={userSettings.monthlyBudget} userName={userSettings.name} currency={userSettings.currency} wallets={userSettings.wallets}
              />
            )}

            {activeTab === 'list' && (
              <div className="space-y-6">
                <div className="flex gap-3">
                  <button type="button" onClick={() => { setPrefill(null); setShowForm(true); }} className="flex-1 bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-lg active:scale-95"><Plus size={20} /> <span className="font-bold">Aggiungi</span></button>
                  <button type="button" onClick={() => setShowScanner(true)} className="flex-1 bg-white dark:bg-gray-800 border-2 border-emerald-100 dark:border-gray-700 text-emerald-600 dark:text-emerald-400 px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-sm active:scale-95"><ScanLine size={20} /> <span className="font-bold">Scan</span></button>
                </div>
                <ExpenseList expenses={expenses} onDelete={deleteExpense} onEdit={(ex) => {setPrefill(ex); setShowForm(true);}} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
              </div>
            )}

            {activeTab === 'subscriptions' && (
              <SubscriptionsView expenses={expenses} onAddSub={() => { 
                const subCat = userSettings.categories.find(c => c.isSubscriptionDefault)?.name || 'Abbonamenti';
                setPrefill({ isSubscription: true, category: subCat }); 
                setShowForm(true); 
              }} onDelete={deleteExpense} currency={userSettings.currency} />
            )}

            {activeTab === 'ricariche' && (
              <RicaricheView onRefill={(wallet) => {
                setPrefill({ 
                  description: `Ricarica ${wallet.name}`, 
                  category: 'Altro', 
                  paymentMethod: PaymentMethod.Bancomat, 
                  date: format(new Date(), 'yyyy-MM-dd') 
                });
                setShowForm(true);
              }} expenses={expenses} currency={userSettings.currency} wallets={userSettings.wallets} />
            )}

            {activeTab === 'ai' && <AiInsights expenses={expenses} />}
            {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={handleClearData} expenses={expenses} email={session.user.email} />}
          </>
        )}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl relative animate-in zoom-in-95 duration-200">
              <button type="button" onClick={() => { setShowForm(false); setPrefill(null); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 p-2">✕</button>
              <h2 className="text-2xl font-bold mb-6 text-gray-800 dark:text-white">{prefill?.id ? 'Modifica' : 'Nuova Spesa'}</h2>
              <ExpenseForm onSubmit={handleSaveExpense} onCancel={() => { setShowForm(false); setPrefill(null); }} initialData={prefill || undefined} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
            </div>
          </div>
        )}

        {showScanner && <ReceiptScanner onDetected={(res) => { setPrefill({...res, date: format(new Date(), 'yyyy-MM-dd')}); setShowScanner(false); setShowForm(true); }} onClose={() => setShowScanner(false)} />}
      </div>
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { CategoryConfig, Expense, PaymentMethod, WalletConfig } from '../types';
import { SmartCategorizer } from './SmartCategorizer';
import { Loader2, Save, Repeat, Building, CreditCard, Banknote, Fuel, AlertTriangle, Check, X } from 'lucide-react';
import { isSameMonth, isAfter, startOfMonth, endOfMonth, parseISO, startOfToday } from 'date-fns';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => Promise<void> | void;
  onCancel: () => void;
  initialData?: Partial<Expense>;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ 
  onSubmit, 
  onCancel, 
  initialData, 
  currency = '€', 
  wallets, 
  categories 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<string>('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.Contanti);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSubscription, setIsSubscription] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Stato per il modale di conferma personalizzato
  const [showConfirmModal, setShowConfirmModal] = useState<{show: boolean, type: 'future' | 'past' | null}>({
    show: false,
    type: null
  });

  useEffect(() => {
    if (initialData) {
      if (initialData.description !== undefined) setDescription(initialData.description);
      if (initialData.amount !== undefined) setAmount(initialData.amount.toString());
      if (initialData.category !== undefined) setCategory(initialData.category);
      if (initialData.paymentMethod !== undefined) setPaymentMethod(initialData.paymentMethod);
      if (initialData.date !== undefined) setDate(initialData.date);
      if (initialData.isSubscription !== undefined) setIsSubscription(initialData.isSubscription || false);
    } else {
      setCategory(categories[categories.length - 1]?.name || 'Altro');
    }
  }, [initialData, categories]);

  const validateAndProcess = () => {
    const parsedAmount = parseFloat(amount.replace(',', '.'));
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      alert("Inserisci un importo valido");
      return;
    }

    const selectedDate = parseISO(date);
    const today = startOfToday();
    const endOfThisMonth = endOfMonth(today);

    // Controllo data futura
    if (isAfter(selectedDate, endOfThisMonth)) {
      setShowConfirmModal({ show: true, type: 'future' });
      return;
    }

    // Controllo data passata
    const startOfThisMonth = startOfMonth(today);
    if (!isSameMonth(selectedDate, today) && selectedDate < startOfThisMonth) {
      setShowConfirmModal({ show: true, type: 'past' });
      return;
    }

    executeSubmit();
  };

  const executeSubmit = async () => {
    setIsSubmitting(true);
    const parsedAmount = parseFloat(amount.replace(',', '.'));
    try {
      await onSubmit({
        description: description.trim() || 'Spesa senza nome',
        amount: parsedAmount,
        category: category || 'Altro',
        paymentMethod,
        date,
        isSubscription
      });
    } catch (err: any) {
      console.error("Errore salvataggio:", err);
      alert("Errore: " + err.message);
    } finally {
      setIsSubmitting(false);
      setShowConfirmModal({ show: false, type: null });
    }
  };

  const getPaymentIcon = (method: PaymentMethod) => {
    const wallet = wallets.find(w => w.method === method);
    if (wallet) return wallet.icon === 'zap' ? <Zap size={16} /> : wallet.icon === 'fuel' ? <Fuel size={16} /> : <CreditCard size={16} />;
    return method === PaymentMethod.Contanti ? <Banknote size={16} /> : <Building size={16} />;
  };

  const Zap = ({size}: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>;

  return (
    <div className="relative">
      <form onSubmit={(e) => { e.preventDefault(); validateAndProcess(); }} className="space-y-5">
        <div>
          <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Descrizione</label>
          <input 
            type="text" 
            value={description} 
            onChange={(e) => setDescription(e.target.value)} 
            placeholder="Cosa hai acquistato?" 
            className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" 
            required 
          />
          <SmartCategorizer description={description} onSuggest={setCategory} categories={categories} />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Importo</label>
            <input 
              type="text" 
              inputMode="decimal" 
              value={amount} 
              onChange={(e) => setAmount(e.target.value)} 
              placeholder={`0.00 ${currency}`} 
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-bold text-xl" 
              required 
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Data</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)} 
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" 
              required 
            />
          </div>
        </div>

        <button type="button" onClick={() => setIsSubscription(!isSubscription)} className={`w-full flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isSubscription ? 'bg-emerald-50 border-emerald-500 text-emerald-600' : 'bg-gray-50 border-transparent text-gray-400'}`}>
          <div className="flex items-center gap-2 font-bold text-sm"><Repeat size={18} /> Abbonamento Ricorrente</div>
          <div className={`w-10 h-6 rounded-full relative transition-colors ${isSubscription ? 'bg-emerald-500' : 'bg-gray-300'}`}><div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isSubscription ? 'left-5' : 'left-1'}`}></div></div>
        </button>

        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Metodo di Pagamento</label>
          <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
            {[PaymentMethod.Contanti, PaymentMethod.Bancomat, ...wallets.map(w => w.method)].map((m) => (
              <button key={m} type="button" onClick={() => setPaymentMethod(m)} className={`flex items-center gap-2 px-3 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${paymentMethod === m ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
                {getPaymentIcon(m)} <span className="truncate">{wallets.find(w => w.method === m)?.name || m}</span>
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Categoria</label>
          <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
            {categories.map((cat) => (
              <button key={cat.id} type="button" onClick={() => setCategory(cat.name)} className={`px-4 py-3 rounded-xl text-xs font-bold border-2 transition-all ${category === cat.name ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div className="flex gap-4 pt-4">
          <button type="button" onClick={onCancel} className="flex-1 px-6 py-4 rounded-2xl border-2 border-gray-100 dark:border-gray-700 text-gray-400 font-bold hover:bg-gray-50 transition-colors">Annulla</button>
          <button type="submit" disabled={isSubmitting} className="flex-1 px-6 py-4 rounded-2xl bg-emerald-500 text-white font-bold shadow-xl shadow-emerald-100 dark:shadow-none disabled:opacity-70 flex items-center justify-center gap-2 active:scale-95 transition-transform">
            {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />} Salva
          </button>
        </div>
      </form>

      {/* MODALE DI CONFERMA PERSONALIZZATO */}
      {showConfirmModal.show && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-emerald-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-xs p-8 shadow-2xl text-center animate-in zoom-in-95 duration-300 border-4 border-emerald-500">
            <div className="bg-emerald-100 dark:bg-emerald-900/30 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-emerald-600">
              <AlertTriangle size={32} />
            </div>
            <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
              {showConfirmModal.type === 'future' ? 'Data Futura' : 'Data Passata'}
            </h3>
            <p className="text-sm text-gray-500 dark:text-gray-400 mb-8 leading-relaxed">
              {showConfirmModal.type === 'future' 
                ? 'Questa è una data futura, sei sicuro di voler aggiungere questa spesa?' 
                : 'Questa data appartiene a un mese passato. Vuoi aggiungerla allo storico?'}
            </p>
            <div className="flex flex-col gap-3">
              <button 
                onClick={executeSubmit}
                disabled={isSubmitting}
                className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95"
              >
                {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />} Sì, aggiungi
              </button>
              <button 
                onClick={() => setShowConfirmModal({ show: false, type: null })}
                className="w-full py-3 text-gray-400 font-bold hover:text-gray-600 transition-colors"
              >
                No, annulla
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useMemo } from 'react';
import { Expense, PaymentMethod, WalletConfig } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip 
} from 'recharts';
import { Wallet, Calendar, Target, Zap, Fuel, CreditCard, Clock, ChevronRight } from 'lucide-react';
import { format, startOfMonth, endOfMonth, isWithinInterval, subMonths, isAfter } from 'date-fns';
import { it } from 'date-fns/locale';

interface DashboardProps {
  expenses: Expense[];
  budget: number;
  userName?: string;
  currency?: string;
  wallets: WalletConfig[];
}

export const Dashboard: React.FC<DashboardProps> = ({ expenses, budget, userName = 'Utente', currency = '€', wallets }) => {
  const currentMonth = new Date();
  const currentMonthStart = startOfMonth(currentMonth);
  const currentMonthEnd = endOfMonth(currentMonth);

  const currentMonthExpenses = useMemo(() => {
    return expenses.filter(e => 
      isWithinInterval(new Date(e.date), { start: currentMonthStart, end: currentMonthEnd })
    );
  }, [expenses]);

  const futureExpenses = useMemo(() => {
    return expenses.filter(e => isAfter(new Date(e.date), currentMonthEnd));
  }, [expenses, currentMonthEnd]);

  const budgetExpenses = useMemo(() => {
    return currentMonthExpenses.filter(e => 
      e.paymentMethod === PaymentMethod.Contanti || e.paymentMethod === PaymentMethod.Bancomat
    );
  }, [currentMonthExpenses]);

  const totalCurrentMonth = budgetExpenses.reduce((sum, e) => sum + e.amount, 0);

  const lastMonthStart = startOfMonth(subMonths(currentMonth, 1));
  const lastMonthEnd = endOfMonth(subMonths(currentMonth, 1));
  const totalLastMonth = expenses
    .filter(e => 
      isWithinInterval(new Date(e.date), { start: lastMonthStart, end: lastMonthEnd }) &&
      (e.paymentMethod === PaymentMethod.Contanti || e.paymentMethod === PaymentMethod.Bancomat)
    )
    .reduce((sum, e) => sum + e.amount, 0);

  const diff = totalLastMonth > 0 ? ((totalCurrentMonth - totalLastMonth) / totalLastMonth) * 100 : 0;
  const budgetProgress = Math.min((totalCurrentMonth / budget) * 100, 100);

  const balances = useMemo(() => {
    return wallets.map(w => {
      const totalRecharged = expenses
        .filter(e => e.description.toLowerCase().includes(`ricarica ${w.name.toLowerCase()}`))
        .reduce((sum, e) => sum + e.amount, 0);

      const totalSpent = expenses
        .filter(e => e.paymentMethod === w.method && !e.description.toLowerCase().includes('ricarica'))
        .reduce((sum, e) => sum + e.amount, 0);

      return {
        ...w,
        value: Math.max(0, totalRecharged - totalSpent),
        icon: w.icon === 'zap' ? <Zap size={14} /> : w.icon === 'fuel' ? <Fuel size={14} /> : <CreditCard size={14} />,
        color: w.icon === 'zap' ? 'text-emerald-500' : 'text-blue-500'
      };
    });
  }, [expenses, wallets]);

  const categoryData = useMemo(() => {
    const data: Record<string, number> = {};
    currentMonthExpenses.forEach(e => {
      data[e.category] = (data[e.category] || 0) + e.amount;
    });
    return Object.entries(data)
      .map(([name, value]) => ({ name, value }))
      .filter(item => item.value > 0);
  }, [currentMonthExpenses]);

  const COLORS = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#047857', '#065f46', '#064e3b'];
  const formatValue = (val: number) => `${currency}${val.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`;
  const isDark = document.documentElement.classList.contains('dark');

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="mb-2">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Ciao, {userName}! 👋</h2>
        <p className="text-gray-500 dark:text-gray-400 text-sm">Ecco lo stato delle finanze di questo mese</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="md:col-span-2 bg-emerald-500 dark:bg-emerald-600 p-8 rounded-[2rem] text-white shadow-xl shadow-emerald-200/50 dark:shadow-none relative overflow-hidden">
          <div className="flex justify-between items-start mb-6">
            <div>
              <p className="text-emerald-50 text-xs font-bold uppercase tracking-wider mb-1">Speso questo mese</p>
              <h2 className="text-4xl font-black">{formatValue(totalCurrentMonth)}</h2>
            </div>
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm">
              <CreditCard size={24} />
            </div>
          </div>
          <div className="space-y-2">
            <div className="flex justify-between text-xs font-medium text-emerald-50">
              <span>Target: {currency}{budget.toLocaleString('it-IT')}</span>
              <span>{Math.round(budgetProgress)}%</span>
            </div>
            <div className="h-2 w-full bg-white/20 rounded-full overflow-hidden">
              <div className="h-full bg-white transition-all duration-1000" style={{ width: `${budgetProgress}%` }}></div>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl"><Target size={20} /></div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold">Rispetto a Mese Scorso</p>
              <p className={`font-bold ${diff <= 0 ? 'text-emerald-600' : 'text-red-500'}`}>{diff <= 0 ? '-' : '+'}{Math.abs(diff).toFixed(1)}%</p>
            </div>
          </div>
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl"><Calendar size={20} /></div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold">Mese</p>
              <p className="font-bold dark:text-white capitalize">{format(currentMonth, "MMMM yyyy", { locale: it })}</p>
            </div>
          </div>
        </div>
      </div>

      {futureExpenses.length > 0 && (
        <div className="bg-emerald-50 dark:bg-emerald-900/10 p-5 rounded-[2rem] border border-emerald-200 dark:border-emerald-800 flex items-center justify-between group cursor-default">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-3 rounded-2xl text-white">
              <Clock size={20} />
            </div>
            <div>
              <p className="text-emerald-600 dark:text-emerald-400 font-bold text-sm">Spese Programmate</p>
              <p className="text-[10px] text-emerald-500/70 dark:text-emerald-500/50 font-bold uppercase tracking-wider">Hai {futureExpenses.length} {futureExpenses.length === 1 ? 'spesa' : 'spese'} nei prossimi mesi</p>
            </div>
          </div>
          <p className="text-xl font-black text-emerald-600 dark:text-emerald-400">
            {currency}{futureExpenses.reduce((s, e) => s + e.amount, 0).toLocaleString('it-IT', { minimumFractionDigits: 2 })}
          </p>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-x-auto">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4 ml-2">Saldi Wallet</h3>
        <div className="flex gap-4 px-2">
          {balances.map((wallet) => (
            <div key={wallet.name} className="flex-shrink-0 w-40 p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50">
              <div className="flex justify-between items-center mb-2">
                <div className={wallet.color}>{wallet.icon}</div>
                <span className="text-[8px] font-bold text-gray-400 uppercase">{wallet.name}</span>
              </div>
              <p className="font-bold dark:text-white">{currency}{wallet.value.toFixed(2)}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm flex flex-col items-center">
          <h3 className="text-lg font-bold dark:text-white mb-6 self-start">Distribuzione Spese</h3>
          <div className="w-full flex justify-center py-4" style={{ height: '300px' }}>
            {categoryData.length > 0 ? (
              <PieChart width={280} height={280}>
                <Pie data={categoryData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                  {categoryData.map((_, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                </Pie>
                <Tooltip 
                  contentStyle={{ 
                    borderRadius: '12px', border: 'none', 
                    backgroundColor: isDark ? '#1f2937' : '#ffffff', color: isDark ? '#ffffff' : '#000000'
                  }} 
                />
              </PieChart>
            ) : <div className="h-full flex items-center text-gray-400">Nessun dato questo mese</div>}
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold dark:text-white mb-6">Top Categorie</h3>
          <div className="space-y-4">
            {categoryData.length > 0 ? (
              categoryData.sort((a,b) => b.value - a.value).slice(0, 5).map((entry, index) => (
                <div key={entry.name} className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                    <span className="text-sm dark:text-gray-300">{entry.name}</span>
                  </div>
                  <span className="text-sm font-bold dark:text-white">{formatValue(entry.value)}</span>
                </div>
              ))
            ) : (
              <div className="text-center py-10 text-gray-400 text-sm">Nessuna spesa registrata a {format(currentMonth, 'MMMM', { locale: it })}</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CategoryConfig, Expense, PaymentMethod, WalletConfig } from '../types';
import { SmartCategorizer } from './SmartCategorizer';
import { Loader2, Save, Repeat, Building, CreditCard, Banknote, Fuel, AlertTriangle, Check } from 'lucide-react';
import { isSameMonth, isAfter, startOfMonth, parseISO, startOfToday } from 'date-fns';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => Promise<void> | void;
  onCancel: () => void;
  initialData?: Partial<Expense>;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ 
  onSubmit, 
  onCancel, 
  initialData, 
  currency = '€', 
  wallets, 
  categories 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<string>('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.Contanti);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSubscription, setIsSubscription] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Stato per il modale di conferma personalizzato
  const [showConfirmModal, setShowConfirmModal] = useState<{show: boolean, type: 'future' | 'past' | null}>({
    show: false,
    type: null
  });

  useEffect(() => {
    if (initialData) {
      if (initialData.description !== undefined) setDescription(initialData.description);
      if (initialData.amount !== undefined) setAmount(initialData.amount.toString());
      if (initialData.category !== undefined) setCategory(initialData.category);
      if (initialData.paymentMethod !== undefined) setPaymentMethod(initialData.paymentMethod);
      if (initialData.date !== undefined) setDate(initialData.date);
      if (initialData.isSubscription !== undefined) setIsSubscription(initialData.isSubscription || false);
    } else {
      setCategory(categories[categories.length - 1]?.name || 'Altro');
    }
  }, [initialData, categories]);

  const validateAndProcess = () => {
    const parsedAmount = parseFloat(amount.replace(',', '.'));
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      alert("Inserisci un importo valido");
      return;
    }

    const selectedDate = parseISO(date);
    const today = startOfToday();

    // Controllo data futura: Qualsiasi data strettamente successiva ad oggi (anche domani stesso mese)
    if (isAfter(selectedDate, today)) {
      setShowConfirmModal({ show: true, type: 'future' });
      return;
    }

    // Controllo data passata (mesi precedenti)
    const startOfThisMonth = startOfMonth(today);
    if (!isSameMonth(selectedDate, today) && selectedDate < startOfThisMonth) {
      setShowConfirmModal({ show: true, type: 'past' });
      return;
    }

    executeSubmit();
  };

  const executeSubmit = async () => {
    setIsSubmitting(true);
    const parsedAmount = parseFloat(amount.replace(',', '.'));
    try {
      await onSubmit({
        description: description.trim() || 'Spesa senza nome',
        amount: parsedAmount,
        category: category || 'Altro',
        paymentMethod,
        date,
        isSubscription
      });
    } catch (err: any) {
      console.error("Errore salvataggio:", err);
      alert("Errore: " + err.message);
    } finally {
      setIsSubmitting(false);
      setShowConfirmModal({ show: false, type: null });
    }
  };

  const getPaymentIcon = (method: PaymentMethod) => {
    const wallet = wallets.find(w => w.method === method);
    if (wallet) return wallet.icon === 'zap' ? <Zap size={16} /> : wallet.icon === 'fuel' ? <Fuel size={16} /> : <CreditCard size={16} />;
    return method === PaymentMethod.Contanti ? <Banknote size={16} /> : <Building size={16} />;
  };

  const Zap = ({size}: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>;

  return (
    <div className="relative">
      <form onSubmit={(e) => { e.preventDefault(); validateAndProcess(); }} className="space-y-5">
        <div>
          <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Descrizione</label>
          <input 
            type="text" 
            value={description} 
            onChange={(e) => setDescription(e.target.value)} 
            placeholder="Cosa hai acquistato?" 
            className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" 
            required 
          />
          <SmartCategorizer description={description} onSuggest={setCategory} categories={categories} />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Importo</label>
            <input 
              type="text" 
              inputMode="decimal" 
              value={amount} 
              onChange={(e) => setAmount(e.target.value)} 
              placeholder={`0.00 ${currency}`} 
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-bold text-xl" 
              required 
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Data</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)} 
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" 
              required 
            />
          </div>
        </div>

        <button type="button" onClick={() => setIsSubscription(!isSubscription)} className={`w-full flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isSubscription ? 'bg-emerald-50 border-emerald-500 text-emerald-600' : 'bg-gray-50 border-transparent text-gray-400'}`}>
          <div className="flex items-center gap-2 font-bold text-sm"><Repeat size={18} /> Abbonamento Ricorrente</div>
          <div className={`w-10 h-6 rounded-full relative transition-colors ${isSubscription ? 'bg-emerald-500' : 'bg-gray-300'}`}><div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isSubscription ? 'left-5' : 'left-1'}`}></div></div>
        </button>

        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Metodo di Pagamento</label>
          <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
            {[PaymentMethod.Contanti, PaymentMethod.Bancomat, ...wallets.map(w => w.method)].map((m) => (
              <button key={m} type="button" onClick={() => setPaymentMethod(m)} className={`flex items-center gap-2 px-3 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${paymentMethod === m ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
                {getPaymentIcon(m)} <span className="truncate">{wallets.find(w => w.method === m)?.name || m}</span>
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Categoria</label>
          <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
            {categories.map((cat) => (
              <button key={cat.id} type="button" onClick={() => setCategory(cat.name)} className={`px-4 py-3 rounded-xl text-xs font-bold border-2 transition-all ${category === cat.name ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div className="flex gap-4 pt-4">
          <button type="button" onClick={onCancel} className="flex-1 px-6 py-4 rounded-2xl border-2 border-gray-100 dark:border-gray-700 text-gray-400 font-bold hover:bg-gray-50 transition-colors">Annulla</button>
          <button type="submit" disabled={isSubmitting} className="flex-1 px-6 py-4 rounded-2xl bg-emerald-500 text-white font-bold shadow-xl shadow-emerald-100 dark:shadow-none disabled:opacity-70 flex items-center justify-center gap-2 active:scale-95 transition-transform">
            {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />} Salva
          </button>
        </div>
      </form>

      {/* MODALE DI CONFERMA PERSONALIZZATO */}
      {showConfirmModal.show && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-emerald-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-xs p-8 shadow-2xl text-center animate-in zoom-in-95 duration-300 border-4 border-emerald-500">
            <div className="bg-emerald-100 dark:bg-emerald-900/30 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-emerald-600">
              <AlertTriangle size={32} />
            </div>
            <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
              {showConfirmModal.type === 'future' ? 'Data Futura' : 'Data Passata'}
            </h3>
            <p className="text-sm text-gray-500 dark:text-gray-400 mb-8 leading-relaxed font-medium">
              {showConfirmModal.type === 'future' 
                ? 'Questa è una data futura, sei sicuro di voler aggiungere' 
                : 'Questa data appartiene a un mese passato. Vuoi aggiungerla allo storico?'}
            </p>
            <div className="flex flex-col gap-3">
              <button 
                onClick={executeSubmit}
                disabled={isSubmitting}
                className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 hover:bg-emerald-600 transition-colors"
              >
                {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />} Si
              </button>
              <button 
                onClick={() => setShowConfirmModal({ show: false, type: null })}
                className="w-full py-3 text-gray-400 font-bold hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
              >
                No
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CategoryConfig, Expense, PaymentMethod, WalletConfig } from '../types';
import { SmartCategorizer } from './SmartCategorizer';
import { Loader2, Save, Repeat, Building, CreditCard, Banknote, Fuel, AlertTriangle, Check } from 'lucide-react';
import { isSameMonth, isAfter, startOfMonth, parseISO, startOfToday } from 'date-fns';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => Promise<void> | void;
  onCancel: () => void;
  initialData?: Partial<Expense>;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ 
  onSubmit, 
  onCancel, 
  initialData, 
  currency = '€', 
  wallets, 
  categories 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<string>('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.Contanti);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSubscription, setIsSubscription] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

