          label={t.expenses}
        />
        <MobileNavButton 
          active={activeTab === 'subscriptions'} 
          onClick={() => setActiveTab('subscriptions')}
          icon={<Repeat />}
          label={t.subscriptions.substring(0, 4)}
        />
        <MobileNavButton 
          active={activeTab === 'ricariche'} 
