const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-md z-[110] flex items-center justify-center p-4">
      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{title}</h2>
          <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>
        </div>
        {children}
      </div>
    </div>
  );
};

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  onImport?: (file: File) => Promise<{ imported: number; skipped: number }>;
  onExport?: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  onImport,
  onExport,
  expenses,
  email
}) => {
  const [view, setView] = useState<'main' | 'history' | 'wallets' | 'categories'>('main');
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  // States for adding new items
  const [isAdding, setIsAdding] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemColor, setNewItemColor] = useState('#10b981');

  // States for editing existing items
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editColor, setEditColor] = useState('');

  const [tempName, setTempName] = useState(settings.name);
  const [tempEmail, setTempEmail] = useState(email || '');
  const [isUpdating, setIsUpdating] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const lang = settings.language || 'it';
  const t = translations[lang].settings;
  const tNav = translations[lang].nav;

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 3000);
  };

  const handleUpdateProfile = async () => {
    setIsUpdating(true);
    try {
      if (tempName !== settings.name) {
        await auth.updateProfile(tempName);
        onUpdate({ ...settings, name: tempName });
      }
      if (tempEmail !== email) {
        await auth.updateEmail(tempEmail);
        showFeedback("Email inviata!");
      } else {
        showFeedback("Profilo aggiornato!");
      }
      setShowProfileModal(false);
    } catch (err: any) {
      alert("Errore aggiornamento: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
      alert("La password deve essere di almeno 6 caratteri");
      return;
    }
    setIsUpdating(true);
    try {
      await auth.updatePassword(newPassword);
      showFeedback("Password aggiornata!");
      setShowPasswordModal(false);
      setNewPassword('');
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !onImport) return;

    setIsImporting(true);
    try {
      const { imported, skipped } = await onImport(file);

      if (imported > 0) {
        showFeedback(`Importazione completata: ${imported} spese aggiunte.`);
      } else if (skipped > 0) {
        alert("Ma hai già importato questo file?");
      } else {
        alert("Nessuna spesa valida trovata nel file.");
      }
    } catch (err: any) {
      alert("Errore importazione: " + err.message);
    } finally {
      setIsImporting(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // Wallets Handlers
  const addWallet = () => {
    if (!newItemName) return;
    const newWallet: WalletConfig = {
      id: `w${Date.now()}`,
      name: newItemName,
      method: PaymentMethod[`Wallet${Math.min(settings.wallets.length + 4, 6)}` as keyof typeof PaymentMethod] || PaymentMethod.Contanti,
      icon: 'wallet'
    };
    onUpdate({ ...settings, wallets: [...settings.wallets, newWallet] });
    setNewItemName('');
    setIsAdding(false);
  };

  const deleteWallet = (id: string) => {
    onUpdate({ ...settings, wallets: settings.wallets.filter(w => w.id !== id) });
  };

  // Categories Handlers
  const addCategory = () => {
    if (!newItemName) return;
    const newCat: CategoryConfig = {
      id: `c${Date.now()}`,
      name: newItemName,
      color: newItemColor
    };
    onUpdate({ ...settings, categories: [...settings.categories, newCat] });
    setNewItemName('');
    setNewItemColor('#10b981');
    setIsAdding(false);
  };

  const deleteCategory = (id: string) => {
    onUpdate({ ...settings, categories: settings.categories.filter(c => c.id !== id) });
  };

  if (view === 'history') {
    return <HistoryView expenses={expenses} onClose={() => setView('main')} currency={settings.currency} />;
  }

  if (view === 'wallets') {
    return (
      <div className="space-y-6">
        <div className="flex items-center gap-4 mb-6">
          <button onClick={() => setView('main')} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><ChevronLeft /></button>
          <h2 className="text-2xl font-bold dark:text-white">{t.manageWallets}</h2>
        </div>

        <div className="space-y-3">
          {settings.wallets.map(w => (
            <div key={w.id} className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700 flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-emerald-50 dark:bg-gray-700 rounded-xl text-emerald-500"><Wallet size={20} /></div>
                <span className="font-bold dark:text-white">{w.name}</span>
              </div>
              <button onClick={() => deleteWallet(w.id)} className="text-red-400 hover:text-red-600 p-2"><Trash2 size={18} /></button>
            </div>
          ))}
        </div>

        {isAdding ? (
          <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-2xl animate-in fade-in">
            <input 
              autoFocus
              placeholder="Nome Wallet (es. Hype)" 
              value={newItemName}
              onChange={e => setNewItemName(e.target.value)}
              className="w-full p-3 rounded-xl border mb-3 dark:bg-gray-700 dark:text-white"
            />
            <div className="flex gap-2">
              <button onClick={addWallet} className="flex-1 bg-emerald-500 text-white py-2 rounded-xl font-bold">Aggiungi</button>
              <button onClick={() => setIsAdding(false)} className="flex-1 bg-gray-200 dark:bg-gray-700 text-gray-500 py-2 rounded-xl font-bold">Annulla</button>
            </div>
          </div>
        ) : (
          <button onClick={() => setIsAdding(true)} className="w-full py-4 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-2xl text-gray-400 font-bold flex items-center justify-center gap-2 hover:border-emerald-500 hover:text-emerald-500 transition-all">
            <Plus size={20} /> Aggiungi Wallet
          </button>
        )}
      </div>
    );
  }

  if (view === 'categories') {
    return (
      <div className="space-y-6">
        <div className="flex items-center gap-4 mb-6">
          <button onClick={() => setView('main')} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"><ChevronLeft /></button>
          <h2 className="text-2xl font-bold dark:text-white">{t.manageCategories}</h2>
        </div>

        <div className="space-y-3">
          {settings.categories.map(c => (
            <div key={c.id} className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700 flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full border-2 border-white shadow-sm" style={{ backgroundColor: c.color || '#10b981' }}></div>
                <span className="font-bold dark:text-white">{c.name}</span>
              </div>
              <button onClick={() => deleteCategory(c.id)} className="text-red-400 hover:text-red-600 p-2"><Trash2 size={18} /></button>
            </div>
          ))}
        </div>

        {isAdding ? (
          <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-2xl animate-in fade-in">
            <input 
              autoFocus
              placeholder="Nome Categoria" 
              value={newItemName}
              onChange={e => setNewItemName(e.target.value)}
              className="w-full p-3 rounded-xl border mb-3 dark:bg-gray-700 dark:text-white"
            />
            <div className="flex items-center gap-2 mb-3 overflow-x-auto p-1">
              {['#ef4444', '#f97316', '#eab308', '#84cc16', '#10b981', '#06b6d4', '#3b82f6', '#8b5cf6', '#ec4899', '#64748b'].map(color => (
                <button 
                  key={color}
                  onClick={() => setNewItemColor(color)}
                  className={`w-8 h-8 rounded-full border-2 shrink-0 ${newItemColor === color ? 'border-gray-900 scale-110' : 'border-transparent'}`}
                  style={{ backgroundColor: color }}
                />
              ))}
            </div>
            <div className="flex gap-2">
              <button onClick={addCategory} className="flex-1 bg-emerald-500 text-white py-2 rounded-xl font-bold">Aggiungi</button>
              <button onClick={() => setIsAdding(false)} className="flex-1 bg-gray-200 dark:bg-gray-700 text-gray-500 py-2 rounded-xl font-bold">Annulla</button>
            </div>
          </div>
        ) : (
          <button onClick={() => setIsAdding(true)} className="w-full py-4 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-2xl text-gray-400 font-bold flex items-center justify-center gap-2 hover:border-emerald-500 hover:text-emerald-500 transition-all">
            <Plus size={20} /> Aggiungi Categoria
          </button>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 relative">
      {/* Feedback Toast */}
      {feedback && (
        <div className="absolute top-0 left-0 right-0 z-50 flex justify-center pointer-events-none">
          <div className="bg-gray-900 text-white px-6 py-3 rounded-full shadow-xl flex items-center gap-2 text-sm font-bold animate-in slide-in-from-top-4 fade-in">
            <CheckCircle2 size={16} className="text-emerald-400" /> {feedback}
          </div>
        </div>
      )}

      {/* Profile Card */}
