      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-hidden divide-y divide-gray-50 dark:divide-gray-700/50">
        <SettingsRow 
          icon={<div className="p-2 bg-teal-50 dark:bg-teal-900/20 text-teal-500 rounded-xl"><History size={20} /></div>}
          label={t.history}
