          <div className="border-t border-gray-100 dark:border-gray-700 my-4 pt-4">
             <button onClick={() => { setShowProfileModal(false); setShowPasswordModal(true); }} className="w-full text-left text-sm text-emerald-600 font-bold flex items-center gap-2">
               <ShieldCheck size={16} /> {t.changePassword}
             </button>
