      { id: 'c5', name: 'Svago', color: '#06b6d4' }, // Ciano
      { id: 'c6', name: 'Salute', color: '#ec4899' }, // Rosa
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true, color: '#8b5cf6' }, // Viola
      { id: 'c8', name: 'Altro', color: '#64748b' } // Grigio
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories,
      language: 'it'
    };

    if (!saved) return defaultSettings;

    try {
      const parsed = JSON.parse(saved);
      if (!parsed.categories) {
        parsed.categories = defaultCategories;
      } else {
        // Migration: assegna colori se mancano
        parsed.categories = parsed.categories.map((c: any, idx: number) => ({
          ...c,
          color: c.color || defaultCategories[idx % defaultCategories.length]?.color || '#10b981'
        }));
      }
      if (!parsed.language) {
        parsed.language = 'it';
      }
      return { ...defaultSettings, ...parsed };
    } catch {
      return defaultSettings;
    }
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  useEffect(() => {
    const initSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session?.user) {
        const metadata = session.user.user_metadata;
        const displayName = metadata.full_name || metadata.display_name || metadata.name || session.user.email?.split('@')[0] || 'Utente';
        setUserSettings(prev => ({ ...prev, name: displayName }));
      }
      setIsInitialLoading(false);
    };
    initSession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchExpenses = useCallback(async () => {
    if (!session?.user?.id) return;
    try {
      setIsLoading(true);
      const data = await db.getExpenses(session.user.id);
      setExpenses(data);

      // Check new month
      const today = new Date();
      const currentMonthKey = format(startOfMonth(today), 'yyyy-MM');
      const lastArchivedMonth = localStorage.getItem('mintflow_last_archived');
      if (today.getDate() === 1 && lastArchivedMonth !== currentMonthKey) {
        setShowNewMonthToast(true);
        localStorage.setItem('mintflow_last_archived', currentMonthKey);
        setTimeout(() => setShowNewMonthToast(false), 8000);
      }
    } catch (err) {
      console.error("Errore caricamento:", err);
    } finally {
      setIsLoading(false);
    }
  }, [session]);

  useEffect(() => {
    if (session?.user?.id) {
      fetchExpenses();
    }
  }, [session, fetchExpenses]);

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
    if (userSettings.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [userSettings]);

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      const expenseDate = parseISO(expenseData.date);
      const today = new Date();
      const isPast = !isSameMonth(expenseDate, today) && expenseDate < startOfMonth(today);
      const isFutureDate = isAfter(expenseDate, endOfMonth(today));

      let savedExpense: Expense | null = null;
      if (prefill?.id) {
        savedExpense = await db.updateExpense(prefill.id, expenseData);
        if (savedExpense) setExpenses(prev => prev.map(e => e.id === savedExpense!.id ? savedExpense! : e));
        setSuccessToast("Modifica salvata!");
      } else {
        savedExpense = await db.addExpense(expenseData, session.user.id);
        if (savedExpense) setExpenses(prev => [savedExpense!, ...prev]);
        setSuccessToast(isPast ? "Spesa salvata nello storico!" : isFutureDate ? "Spesa futura programmata!" : "Spesa aggiunta!");
      }

      setShowForm(false);
      setPrefill(null);

      // Se la spesa non è del mese corrente, portiamo l'utente sulla lista per fargliela vedere
      if (isPast || isFutureDate) {
        setActiveTab('list');
      }

      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      alert(`Errore Cloud: ${err.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = async (file: File): Promise<{ imported: number, skipped: number, errors: string[] }> => {
    setIsSyncing(true);
    let importedCount = 0;
    let skippedCount = 0;
    const errors: string[] = [];

    try {
      const text = await file.text();
      const lines = text.split(/\r?\n/); // Supporto anche Windows CRLF

      if (lines.length === 0) throw new Error("Il file è vuoto");

      // --- 1. Rilevamento Separatore ---
      // Cerca se la prima riga usa ; o ,
      const firstLine = lines[0];
      const separator = firstLine.includes(';') ? ';' : ',';

      // --- 2. Rilevamento Colonne (Header Mapping) ---
      const headers = firstLine.toLowerCase().split(separator).map(h => h.trim().replace(/^"|"$/g, ''));

      // Indici di default (se non troviamo header, assumiamo lo standard MintFlow: Date, Desc, Amount...)
      let dateIdx = -1;
      let descIdx = -1;
      let amountIdx = -1;
      let catIdx = -1;
      let pmIdx = -1;

      headers.forEach((h, i) => {
        if (h.includes('date') || h.includes('data') || h.includes('giorno')) dateIdx = i;
        else if (h.includes('desc') || h.includes('causale') || h.includes('testo') || h.includes('nome')) descIdx = i;
        else if (h.includes('amount') || h.includes('importo') || h.includes('euro') || h.includes('valore') || h.includes('prezzo')) amountIdx = i;
        else if (h.includes('cat')) catIdx = i;
        else if (h.includes('metodo') || h.includes('pagamento') || h.includes('payment')) pmIdx = i;
      });

      // Se non abbiamo trovato header significativi, usiamo fallback posizionale
      if (dateIdx === -1) dateIdx = 0;
      if (descIdx === -1) descIdx = 1;
      if (amountIdx === -1) amountIdx = 2;

      // Helper per pulire valori
      const cleanVal = (val: string) => val ? val.replace(/^"|"$/g, '').replace(/""/g, '"').trim() : '';

      // Skip della prima riga SOLO se sembra un header (contiene testo non numerico dove ci aspettiamo data/importo)
      const hasHeader = (lines[0].toLowerCase().includes('data') || lines[0].toLowerCase().includes('date') || isNaN(parseFloat(lines[0].split(separator)[amountIdx])));
      const startIdx = hasHeader ? 1 : 0;

      for (let i = startIdx; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        // --- 3. Split Intelligente (gestione quote) ---
        // Se usiamo una regex complessa per split, attenzione ai casi limite. 
        // Qui facciamo un parsing manuale semplice per rispettare le virgolette.
        const parts: string[] = [];
        let current = '';
        let inQuote = false;
        for (let char of line) {
          if (char === '"') { 
            inQuote = !inQuote; 
          } else if (char === separator && !inQuote) {
            parts.push(current);
            current = '';
          } else {
            current += char;
          }
        }
        parts.push(current);

        const rawDate = cleanVal(parts[dateIdx]);
        const rawDesc = cleanVal(parts[descIdx]);
        const rawAmount = cleanVal(parts[amountIdx]);
        const rawCat = catIdx > -1 ? cleanVal(parts[catIdx]) : '';
        const rawPm = pmIdx > -1 ? cleanVal(parts[pmIdx]) : '';

        // Se mancano dati essenziali
        if (!rawDate && !rawAmount) continue;

        // --- 4. Parsing Data Robusto ---
        let date = null;
        // ISO YYYY-MM-DD
        if (rawDate.match(/^\d{4}-\d{2}-\d{2}$/)) {
            date = rawDate;
        } 
        // Formati DD/MM/YYYY o DD-MM-YYYY o D/M/YY
        else {
            const dateParts = rawDate.match(/(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})/);
            if (dateParts) {
                let [_, d, m, y] = dateParts;
                if (y.length === 2) y = "20" + y; // Assume 20xx
                date = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
            }
        }

        if (!date) {
            errors.push(`Riga ${i+1}: Data non valida ("${rawDate}")`);
            continue;
        }

        // --- 5. Parsing Importo Robusto ---
        // Rimuovi tutto tranne numeri, virgole, punti e meno
        let amountStr = rawAmount.replace(/[^0-9.,-]/g, '');
        // Se il meno è alla fine (formato contabile: "12.00-") spostalo all'inizio
        if (amountStr.endsWith('-')) amountStr = '-' + amountStr.slice(0, -1);

        // Logica , vs .
        if (amountStr.includes(',') && amountStr.includes('.')) {
             // Se l'ultimo separatore è la virgola (es. 1.200,50), allora . è migliaia e , è decimale
             if (amountStr.lastIndexOf(',') > amountStr.lastIndexOf('.')) {
                 amountStr = amountStr.replace(/\./g, '').replace(',', '.');
             } else {
                 // Viceversa (es. 1,200.50)
                 amountStr = amountStr.replace(/,/g, '');
             }
        } else if (amountStr.includes(',')) {
             // Solo virgola (es. 12,50) -> diventa punto
             amountStr = amountStr.replace(',', '.');
        }

        const amount = parseFloat(amountStr);
        if (isNaN(amount)) {
            errors.push(`Riga ${i+1}: Importo non valido ("${rawAmount}")`);
            continue;
        }

        const description = rawDesc || "Spesa importata";
        const category = rawCat || "Altro";

        // --- 6. Controllo Duplicati ---
        const isDuplicate = expenses.some(e => 
           e.date === date && 
           Math.abs(e.amount - amount) < 0.01 && 
           e.description.toLowerCase().trim() === description.toLowerCase().trim()
        );

        if (isDuplicate) {
           skippedCount++;
           continue;
        }

        // --- 7. Mappatura Metodo Pagamento ---
        let pm = PaymentMethod.Contanti;
        const normPm = rawPm.toLowerCase();
        if (normPm.includes('flash')) pm = PaymentMethod.Flash;
        else if (normPm.includes('revolut')) pm = PaymentMethod.Revolut;
        else if (normPm.includes('q8')) pm = PaymentMethod.AppQ8;
        else if (normPm.includes('bancomat') || normPm.includes('card') || normPm.includes('carta')) pm = PaymentMethod.Bancomat;

        const expenseData = {
           date,
           description,
           amount,
           category,
           paymentMethod: pm,
           isSubscription: false
        };

        await db.addExpense(expenseData, session.user.id);
        importedCount++;
      }

      // Se non abbiamo fatto nulla, generiamo un errore
      if (importedCount === 0 && skippedCount === 0 && errors.length === 0) {
        errors.push("Il file sembra valido ma non ho trovato righe con Data e Importo. Controlla che i separatori siano corretti.");
      }

      // Ricarica dati
      if (importedCount > 0) {
        await fetchExpenses();
        setSuccessToast(`${importedCount} spese importate`);
        setTimeout(() => setSuccessToast(null), 4000);
      } 

      return { imported: importedCount, skipped: skippedCount, errors };

    } catch (err: any) {
      console.error(err);
      throw new Error("Errore lettura file: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleExportCSV = () => {
    if (expenses.length === 0) {
      alert("Nessuna spesa da esportare.");
      return;
    }

    try {
      const headers = ["Date", "Description", "Amount", "Category", "PaymentMethod", "IsSubscription"];
      const rows = expenses.map(e => {
        const safeDesc = e.description.replace(/"/g, '""');
        return [
          e.date,
          `"${safeDesc}"`,
          e.amount.toFixed(2),
          `"${e.category}"`,
          e.paymentMethod,
          e.isSubscription ? "true" : "false"
        ].join(",");
      });

      const csvContent = [headers.join(","), ...rows].join("\n");
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `mintflow_export_${format(new Date(), 'yyyyMMdd_HHmm')}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setSuccessToast("Esportazione completata!");
      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      console.error(err);
      alert("Errore esportazione: " + err.message);
    }
  };

  const requestDeleteExpense = useCallback((id: string) => {
    setExpenseToDelete(id);
  }, []);

  const confirmDeleteExpense = async () => {
    if (!expenseToDelete) return;

    try {
      setIsSyncing(true);
      await db.deleteExpense(expenseToDelete);
      setExpenses(prev => prev.filter(e => e.id !== expenseToDelete));
      setSuccessToast("Spesa eliminata.");
      setTimeout(() => setSuccessToast(null), 2000);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsSyncing(false);
      setExpenseToDelete(null);
    }
  };

  const handleClearData = async () => {
    if (window.confirm('Resettare tutte le spese dal cloud?')) {
      try {
        setIsSyncing(true);
        await db.clearAll(session.user.id);
        setExpenses([]);
      } catch (err: any) {
        alert("Errore: " + err.message);
      } finally {
        setIsSyncing(false);
      }
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex flex-col items-center justify-center gap-4">
        <div className="bg-emerald-500 p-5 rounded-3xl text-white shadow-2xl animate-pulse">
          <PiggyBank size={48} />
        </div>
        <div className="flex flex-col items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold">
          <Loader2 size={20} className="animate-spin" />
          <span>MintFlow Sync...</span>
        </div>
      </div>
    );
  }

  if (!session) return <Auth onSuccess={() => {}} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} lang={userSettings.language}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {/* Success Toast */}
        {successToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in slide-in-from-top-4 duration-300">
            <CheckCircle2 size={18} />
            <span className="font-bold text-sm">{successToast}</span>
          </div>
        )}

        {showNewMonthToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm bg-emerald-500 text-white p-6 rounded-[2rem] shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-4 duration-500">
            <div className="bg-white/20 p-3 rounded-2xl shrink-0"><PartyPopper size={24} /></div>
            <div>
              <p className="font-bold text-sm">Nuovo mese iniziato! 🚀</p>
              <p className="text-[10px] opacity-90 uppercase font-bold tracking-widest mt-1 flex items-center gap-1"><History size={10} /> Dati archiviati</p>
            </div>
            <button onClick={() => setShowNewMonthToast(false)} className="ml-auto opacity-50">✕</button>
          </div>
        )}

        <div className="flex justify-end items-center mb-4 px-2">
          <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-gray-400">
            {isSyncing ? <><Loader2 size={12} className="animate-spin text-emerald-500" /> <span className="text-emerald-500">Cloud Sync...</span></> : <><Cloud size={12} className="text-emerald-400" /> <span>Sincronizzato</span></>}
          </div>
        </div>

        {activeTab !== 'dashboard' && (
          <div className="mb-6">
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white capitalize">
               {activeTab === 'list' ? (userSettings.language === 'en' ? 'Your Expenses' : 'Le tue Spese') : 
                activeTab === 'ai' ? 'AI Insights' : 
                activeTab === 'ricariche' ? (userSettings.language === 'en' ? 'Wallets' : 'Portafogli') : 
                activeTab === 'subscriptions' ? (userSettings.language === 'en' ? 'Subscriptions' : 'Abbonamenti') : 
                (userSettings.language === 'en' ? 'Settings' : 'Impostazioni')}
            </h1>
          </div>
        )}

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
             <Loader2 size={48} className="text-emerald-500 animate-spin" />
             <p className="text-gray-400 font-medium">Caricamento...</p>
          </div>
        ) : (
          <>
            {activeTab === 'dashboard' && (
              <Dashboard 
                expenses={expenses} 
                budget={userSettings.monthlyBudget} 
                userName={userSettings.name} 
                currency={userSettings.currency} 
                wallets={userSettings.wallets}
                categories={userSettings.categories}
                lang={userSettings.language}
              />
            )}

            {activeTab === 'list' && (
              <div className="space-y-6">
                <div className="flex gap-3">
                  <button type="button" onClick={() => { setPrefill(null); setShowForm(true); }} className="flex-1 bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-lg active:scale-95"><Plus size={20} /> <span className="font-bold">{userSettings.language === 'en' ? 'Add' : 'Aggiungi'}</span></button>
                  <button type="button" onClick={() => setShowScanner(true)} className="flex-1 bg-white dark:bg-gray-800 border-2 border-emerald-100 dark:border-gray-700 text-emerald-600 dark:text-emerald-400 px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-sm active:scale-95"><ScanLine size={20} /> <span className="font-bold">Scan</span></button>
                </div>
                <ExpenseList expenses={expenses} onDelete={requestDeleteExpense} onEdit={(ex) => {setPrefill(ex); setShowForm(true);}} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
              </div>
            )}

            {activeTab === 'subscriptions' && (
              <SubscriptionsView expenses={expenses} onAddSub={() => { 
                const subCat = userSettings.categories.find(c => c.isSubscriptionDefault)?.name || 'Abbonamenti';
                setPrefill({ isSubscription: true, category: subCat }); 
                setShowForm(true); 
              }} onDelete={requestDeleteExpense} currency={userSettings.currency} />
            )}

            {activeTab === 'ricariche' && (
              <RicaricheView 
                onRefill={(wallet) => {
                  setPrefill({ 
                    description: `Ricarica ${wallet.name}`, 
                    category: 'Altro', 
                    paymentMethod: PaymentMethod.Bancomat, 
                    date: format(new Date(), 'yyyy-MM-dd') 
                  });
                  setShowForm(true);
                }} 
                onSaveExpense={handleSaveExpense}
                expenses={expenses} 
                currency={userSettings.currency} 
                wallets={userSettings.wallets} 
              />
            )}

            {activeTab === 'ai' && <AiInsights expenses={expenses} />}
            {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={handleClearData} onImport={handleImportCSV} onExport={handleExportCSV} expenses={expenses} email={session.user.email} />}
          </>
        )}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl relative animate-in zoom-in-95 duration-200">
              <button type="button" onClick={() => { setShowForm(false); setPrefill(null); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 p-2">✕</button>
              <h2 className="text-2xl font-bold mb-6 text-gray-800 dark:text-white">{prefill?.id ? 'Modifica' : 'Nuova Spesa'}</h2>
              <ExpenseForm 
                onSubmit={handleSaveExpense} 
                onCancel={() => { setShowForm(false); setPrefill(null); }} 
                initialData={prefill || undefined} 
                currency={userSettings.currency} 
                wallets={userSettings.wallets} 
                categories={userSettings.categories} 
                expenses={expenses}
              />
            </div>
          </div>
        )}

        {/* Delete Confirmation Modal */}
        {expenseToDelete && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-red-900/20 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-xs p-8 shadow-2xl text-center animate-in zoom-in-95 duration-300 border-4 border-red-100 dark:border-red-900/30">
              <div className="bg-red-100 dark:bg-red-900/30 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-red-600">
                <Trash2 size={32} />
              </div>
              <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">Elimina Spesa?</h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-8 leading-relaxed">
                Questa azione è irreversibile. Sei sicuro di voler procedere?
              </p>
              <div className="flex flex-col gap-3">
                <button 
                  onClick={confirmDeleteExpense}
                  disabled={isSyncing}
                  className="w-full py-4 bg-red-500 hover:bg-red-600 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-colors"
                >
                  {isSyncing ? <Loader2 className="animate-spin" size={18} /> : <Trash2 size={18} />} Elimina
                </button>
                <button 
                  onClick={() => setExpenseToDelete(null)}
                  className="w-full py-3 text-gray-400 font-bold hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
                >
                  Annulla
                </button>
              </div>
            </div>
          </div>
        )}

        {showScanner && <ReceiptScanner onDetected={(res) => { setPrefill({...res, date: format(new Date(), 'yyyy-MM-dd')}); setShowScanner(false); setShowForm(true); }} onClose={() => setShowScanner(false)} />}
      </div>
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { UserSettings, Expense, WalletConfig, CategoryConfig, PaymentMethod } from '../types';
import { User, DollarSign, Trash2, Download, Moon, Sun, LogOut, FileDown, History, CheckCircle2, ShieldCheck, Edit3, X, Mail, Globe, Lock, Wallet, Tag, ChevronRight, Plus, ChevronLeft, Save, Check, Upload, Loader2 } from 'lucide-react';
import { auth } from '../services/supabase';
import { format } from 'date-fns';
import { HistoryView } from './HistoryView';
import { translations } from '../utils/i18n';

const SettingsRow = ({ icon, label, onClick }: { icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button type="button" onClick={onClick} className="w-full flex items-center justify-between px-6 py-5 md:px-8 md:py-6 hover:bg-emerald-50 dark:hover:bg-gray-700/50 transition-all group">
    <div className="flex items-center gap-4">{icon}<span className="font-bold text-gray-700 dark:text-gray-200 text-sm md:text-base">{label}</span></div>
    <ChevronRight className="text-gray-300 group-hover:text-emerald-500 group-hover:translate-x-1 transition-all" size={20} />
  </button>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-md z-[110] flex items-center justify-center p-4">
      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{title}</h2>
          <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>
        </div>
        {children}
      </div>
    </div>
  );
};

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  onImport?: (file: File) => Promise<{ imported: number; skipped: number; errors: string[] }>;
  onExport?: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  onImport,
  onExport,
  expenses,
  email
}) => {
  const [view, setView] = useState<'main' | 'history' | 'wallets' | 'categories'>('main');
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  // States for adding new items
  const [isAdding, setIsAdding] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemColor, setNewItemColor] = useState('#10b981');

  // States for editing existing items
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editColor, setEditColor] = useState('');

  const [tempName, setTempName] = useState(settings.name);
  const [tempEmail, setTempEmail] = useState(email || '');
  const [isUpdating, setIsUpdating] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const lang = settings.language || 'it';
  const t = translations[lang].settings;
  const tNav = translations[lang].nav;

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 3000);
  };

  const handleUpdateProfile = async () => {
    setIsUpdating(true);
    try {
      if (tempName !== settings.name) {
        await auth.updateProfile(tempName);
        onUpdate({ ...settings, name: tempName });
      }
      if (tempEmail !== email) {
        await auth.updateEmail(tempEmail);
        showFeedback("Email inviata!");
      } else {
        showFeedback("Profilo aggiornato!");
      }
      setShowProfileModal(false);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdatePassword = async () => {
    if (newPassword.length < 6) return alert("Minimo 6 caratteri");
    setIsUpdating(true);
    try {
      await auth.updatePassword(newPassword);
      showFeedback("Password aggiornata!");
      setShowPasswordModal(false);
      setNewPassword('');
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDeleteAccount = async () => {
    if (window.confirm("Vuoi eliminare DEFINITIVAMENTE l'account?")) {
      try {
        setIsUpdating(true);
        await auth.deleteAccount();
      } catch (err: any) {
        await auth.signOut();
      } finally {
        setIsUpdating(false);
      }
    }
  };

  const handleAddItem = (type: 'wallet' | 'category') => {
    if (!newItemName.trim()) return;

    if (type === 'wallet') {
      const newWallet: WalletConfig = {
        id: 'w' + Date.now(),
        name: newItemName.trim(),
        method: newItemName.trim() as PaymentMethod,
        icon: 'credit-card'
      };
      onUpdate({ ...settings, wallets: [...settings.wallets, newWallet] });
    } else {
      const newCat: CategoryConfig = {
        id: 'c' + Date.now(),
        name: newItemName.trim(),
        color: newItemColor
      };
      onUpdate({ ...settings, categories: [...settings.categories, newCat] });
    }

    setNewItemName('');
    setIsAdding(false);
    showFeedback("Aggiunto con successo!");
  };

  const startEditing = (item: CategoryConfig) => {
    setEditingId(item.id);
    setEditName(item.name);
    setEditColor(item.color || '#10b981');
  };

  const saveEdit = () => {
    if (!editName.trim()) return;
    const newCats = settings.categories.map(c => 
      c.id === editingId ? { ...c, name: editName, color: editColor } : c
    );
    onUpdate({ ...settings, categories: newCats });
    setEditingId(null);
    showFeedback("Modifica salvata!");
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !onImport) return;

    if (!file.name.endsWith('.csv')) {
      alert('Seleziona un file .csv valido');
      return;
    }

    if (window.confirm(`Vuoi importare le spese da "${file.name}"?`)) {
      setIsImporting(true);
      try {
        const { imported, skipped, errors } = await onImport(file);

        let msg = '';
        if (imported > 0) msg += `Importazione riuscita: ${imported} spese aggiunte.\n`;
        if (skipped > 0) msg += `\n${skipped} spese erano duplicati e sono state saltate.`;

        // Se ci sono errori specifici, mostriamoli
        if (errors.length > 0) {
           msg += `\n\nAttenzione: ${errors.length} righe non sono state importate:\n`;
           // Mostra solo i primi 5 errori per non intasare l'alert
           msg += errors.slice(0, 5).join('\n');
           if (errors.length > 5) msg += `\n...e altri ${errors.length - 5} errori.`;
           msg += `\n\nControlla che il formato data sia corretto (es. 01/12/2025 o 2025-12-01) e che l'importo sia numerico.`;
        }

        if (imported === 0 && skipped > 0 && errors.length === 0) {
             alert("Ma hai già importato questo file? \nTutte le spese sembrano essere duplicati.");
        } else if (msg) {
             alert(msg);
        } else if (imported === 0 && skipped === 0 && errors.length === 0) {
             // Caso raro, ma gestito
             alert("Nessuna spesa trovata nel file. Formato sconosciuto o file vuoto.");
        }

      } catch (err: any) {
        alert("Errore critico durante l'importazione: " + err.message);
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    } else {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  if (view === 'history') return <HistoryView expenses={expenses} onClose={() => setView('main')} currency={settings.currency} />;

  if (view === 'wallets') return (
    <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[80] overflow-y-auto animate-in slide-in-from-right duration-300">
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6"><ChevronLeft /> {tNav.settings}</button>
        <h2 className="text-3xl font-bold dark:text-white mb-6">{t.manageWallets}</h2>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm space-y-4">
          {settings.wallets.map(w => (
            <div key={w.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-2xl relative">
              <div className="flex items-center gap-3 font-bold dark:text-white"><Wallet className="text-emerald-500" /> {w.name}</div>
              <button 
                type="button"
                onClick={() => {
                  onUpdate({ ...settings, wallets: settings.wallets.filter(x => x.id !== w.id) });
                }} 
                className="p-2.5 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-all flex items-center justify-center relative z-30"
              >
                <Trash2 size={18} className="pointer-events-none" />
              </button>
            </div>
          ))}

          {isAdding ? (
            <div className="space-y-3 p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <input 
                autoFocus
                type="text" 
                value={newItemName} 
                onChange={(e) => setNewItemName(e.target.value)}
                placeholder="Nome portafoglio..."
                className="w-full px-4 py-3 rounded-xl bg-white dark:bg-gray-700 border-none outline-none dark:text-white font-bold"
              />
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('wallet')} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold text-sm">Salva</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-3 bg-white dark:bg-gray-600 text-gray-400 rounded-xl font-bold text-sm">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 mt-4 transition-transform active:scale-95"><Plus size={20} /> Aggiungi</button>
          )}
        </div>
      </div>
    </div>
  );

  if (view === 'categories') return (
    <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[80] overflow-y-auto animate-in slide-in-from-right duration-300">
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6"><ChevronLeft /> {tNav.settings}</button>
        <h2 className="text-3xl font-bold dark:text-white mb-6">{t.manageCategories}</h2>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm space-y-4">
          {settings.categories.map(c => (
            <div key={c.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-2xl relative group min-h-[72px]">
              {editingId === c.id ? (
                <div className="flex-1 flex items-center gap-3 animate-in fade-in duration-200 w-full overflow-hidden">
                  <input 
                    type="color" 
                    value={editColor} 
                    onChange={(e) => setEditColor(e.target.value)}
                    className="w-10 h-10 border-none bg-transparent cursor-pointer rounded-full shrink-0"
                  />
                  <input 
                    autoFocus
                    type="text" 
                    value={editName} 
                    onChange={(e) => setEditName(e.target.value)}
                    className="flex-1 min-w-0 px-3 py-2 bg-white dark:bg-gray-600 rounded-xl border-none outline-none dark:text-white font-bold"
                  />
                  <div className="flex gap-1 ml-2 shrink-0">
                    <button onClick={saveEdit} className="p-2 bg-emerald-500 text-white rounded-full hover:bg-emerald-600"><Check size={18} /></button>
                    <button onClick={() => setEditingId(null)} className="p-2 bg-gray-200 dark:bg-gray-600 text-gray-500 rounded-full hover:bg-gray-300"><X size={18} /></button>
                  </div>
                </div>
              ) : (
                <>
                  <div className="flex items-center gap-3 font-bold dark:text-white">
                    <div 
                      className="w-8 h-8 rounded-full border border-gray-200 dark:border-gray-600 shadow-sm"
                      style={{ backgroundColor: c.color || '#10b981' }}
                    ></div>
                    <span>{c.name}</span>
                  </div>

                  <div className="flex items-center gap-2">
                    <button 
                      type="button"
                      onClick={() => startEditing(c)} 
                      className="p-2.5 text-blue-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-full transition-all flex items-center justify-center"
                    >
                      <Edit3 size={18} />
                    </button>

                    {!c.isSubscriptionDefault && (
                      <button 
                        type="button"
                        onClick={() => {
                          onUpdate({ ...settings, categories: settings.categories.filter(x => x.id !== c.id) });
                        }} 
                        className="p-2.5 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-all flex items-center justify-center"
                      >
                        <Trash2 size={18} />
                      </button>
                    )}
                  </div>
                </>
              )}
            </div>
          ))}

          {isAdding ? (
            <div className="space-y-3 p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <div className="flex items-center gap-3 bg-white dark:bg-gray-700 rounded-xl px-2">
                <input 
                  type="color" 
                  value={newItemColor} 
                  onChange={(e) => setNewItemColor(e.target.value)}
                  className="w-10 h-10 border-none bg-transparent cursor-pointer rounded-full shrink-0"
                />
                <input 
                  autoFocus
                  type="text" 
                  value={newItemName} 
                  onChange={(e) => setNewItemName(e.target.value)}
                  placeholder="Nome categoria..."
                  className="flex-1 px-2 py-3 bg-transparent border-none outline-none dark:text-white font-bold min-w-0"
                />
              </div>
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('category')} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold text-sm">Salva</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-3 bg-white dark:bg-gray-600 text-gray-400 rounded-xl font-bold text-sm">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 mt-4 transition-transform active:scale-95"><Plus size={20} /> Aggiungi</button>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {feedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 bg-emerald-500 text-white rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in zoom-in duration-300">
          <CheckCircle2 size={16} />
          <span className="font-bold text-xs uppercase tracking-wider">{feedback}</span>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 p-6 md:p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm relative overflow-hidden">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 md:mb-8">
          <div className="flex items-center gap-3 md:gap-4 overflow-hidden">
            <div className="bg-emerald-500 p-3 md:p-4 rounded-3xl text-white shrink-0">
              <User className="w-6 h-6 md:w-8 md:h-8" />
            </div>
            <div className="min-w-0 flex-1">
              <h3 className="text-lg md:text-xl font-bold text-gray-800 dark:text-white truncate">{t.profile}</h3>
              <p className="text-gray-400 text-xs md:text-sm truncate">{email}</p>
            </div>
          </div>
          <div className="flex gap-2 shrink-0 self-start sm:self-auto ml-12 sm:ml-0">
            <button type="button" onClick={() => setShowProfileModal(true)} className="flex items-center gap-2 px-3 py-2 md:px-4 md:py-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-xl font-bold text-[10px] md:text-xs hover:bg-emerald-100 transition-all whitespace-nowrap">
              <Edit3 size={14} /> {t.edit}
            </button>
            <button 
              type="button" 
              onClick={() => onUpdate({ ...settings, language: lang === 'it' ? 'en' : 'it' })} 
              className="flex items-center gap-2 px-3 py-2 md:px-4 md:py-2 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-xl font-bold text-[10px] md:text-xs hover:bg-blue-100 transition-all whitespace-nowrap"
            >
              <Globe size={14} /> {lang === 'it' ? 'ITA' : 'ENG'}
            </button>
          </div>
        </div>
        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 md:mb-3 ml-1">{t.displayName}</label>
          <div className="w-full px-5 py-3 md:px-6 md:py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 dark:text-white font-bold text-base md:text-lg truncate">{settings.name}</div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-hidden">
        <SettingsRow icon={<Lock className="text-emerald-500" size={20} />} label={t.changePassword} onClick={() => setShowPasswordModal(true)} />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow icon={<Wallet className="text-emerald-500" size={20} />} label={t.manageWallets} onClick={() => setView('wallets')} />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow icon={<Tag className="text-emerald-500" size={20} />} label={t.manageCategories} onClick={() => setView('categories')} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2"><DollarSign className="text-emerald-500" size={20} /> {t.monthlyBudget}</h3>
          <div className="space-y-4">
            <input type="number" value={settings.monthlyBudget} onChange={(e) => onUpdate({ ...settings, monthlyBudget: Number(e.target.value) })} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-black text-2xl" />
            <select value={settings.currency} onChange={(e) => onUpdate({ ...settings, currency: e.target.value })} className="w-full bg-gray-50 dark:bg-gray-700 dark:text-white px-4 py-3 rounded-2xl font-bold text-sm outline-none border-none">
              <option value="€">Euro (€)</option>
              <option value="$">Dollaro ($)</option>
              <option value="£">Sterlina (£)</option>
            </select>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">{settings.isDarkMode ? <Moon className="text-emerald-500" size={20} /> : <Sun className="text-emerald-500" size={20} />} {t.appearance}</h3>
          <div className="flex items-center justify-between p-6 rounded-2xl bg-gray-50 dark:bg-gray-700">
            <span className="font-bold text-gray-600 dark:text-gray-300">{settings.isDarkMode ? t.darkMode : t.lightMode}</span>
            <button type="button" onClick={() => onUpdate({ ...settings, isDarkMode: !settings.isDarkMode })} className={`w-14 h-8 rounded-full relative transition-colors p-1 ${settings.isDarkMode ? 'bg-emerald-500' : 'bg-gray-300'}`}>
              <div className={`w-6 h-6 bg-white rounded-full shadow-sm transition-all ${settings.isDarkMode ? 'translate-x-6' : 'translate-x-0'}`}></div>
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2"><FileDown className="text-emerald-500" size={20} /> {t.dataArchive}</h3>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          <button type="button" onClick={() => setView('history')} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><History size={20} /> <span className="text-xs md:text-sm">{t.history}</span></button>
          <button type="button" onClick={onExport} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><Download size={20} /> <span className="text-xs md:text-sm">{t.export}</span></button>

          {/* Import CSV Button */}
          <button 
            type="button" 
            onClick={() => fileInputRef.current?.click()} 
            disabled={isImporting}
            className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all relative overflow-hidden"
          >
            {isImporting ? <Loader2 size={20} className="animate-spin" /> : <Upload size={20} />} 
            <span className="text-xs md:text-sm">{t.import}</span>
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileChange}
              accept=".csv"
              className="hidden" 
            />
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-red-50 dark:border-red-900/10 shadow-sm">
        <h3 className="text-lg font-bold text-red-500 mb-6 flex items-center gap-2"><ShieldCheck size={20} /> {t.security}</h3>
        <div className="space-y-4">
          <button type="button" onClick={() => auth.signOut()} className="w-full flex items-center justify-center gap-3 p-5 bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-2xl font-bold hover:bg-gray-100 dark:hover:bg-gray-600 transition-all"><LogOut size={20} /> {t.logout}</button>
          <div className="flex flex-col gap-2 pt-4 border-t border-gray-100 dark:border-gray-700">
            <button type="button" onClick={handleDeleteAccount} className="w-full py-3 text-red-400 text-xs font-bold hover:text-red-600 transition-all flex items-center justify-center gap-2"><Trash2 size={14} /> {t.deleteAccount}</button>
            <button type="button" onClick={onClearData} className="w-full flex items-center justify-center gap-2 text-gray-400 text-[10px] font-bold uppercase tracking-wider hover:text-red-500 transition-all"><Trash2 size={10} /> {t.clearData}</button>
          </div>
        </div>
      </div>

      <div className="text-center pt-4"><p className="text-[10px] text-gray-400 font-bold uppercase tracking-[0.3em]">MintFlow v2.5 • AI Powered</p></div>

      <Modal isOpen={showProfileModal} onClose={() => setShowProfileModal(false)} title="Modifica Profilo">
        <div className="space-y-4">
          <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white" placeholder="Nome" />
          <input type="email" value={tempEmail} onChange={(e) => setTempEmail(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white" placeholder="Email" />
          <button type="button" onClick={handleUpdateProfile} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg mt-2">{isUpdating ? "..." : "Salva"}</button>
        </div>
      </Modal>

      <Modal isOpen={showPasswordModal} onClose={() => setShowPasswordModal(false)} title="Cambia Password">
        <div className="space-y-4">
          <input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white" placeholder="Minimo 6 caratteri" />
          <button type="button" onClick={handleUpdatePassword} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg mt-2">{isUpdating ? "..." : "Aggiorna"}</button>
        </div>
      </Modal>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { ReceiptScanner } from './components/ReceiptScanner';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
import { Auth } from './components/Auth';
import { Expense, UserSettings, PaymentMethod, WalletConfig, CategoryConfig } from './types';
import { Plus, ScanLine, Cloud, Loader2, PiggyBank, PartyPopper, History, CheckCircle2, Trash2, AlertTriangle } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { startOfMonth, format, isSameMonth, parseISO, isAfter, endOfMonth } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [showNewMonthToast, setShowNewMonthToast] = useState(false);
  const [successToast, setSuccessToast] = useState<string | null>(null);

  // Stato per gestire l'eliminazione
  const [expenseToDelete, setExpenseToDelete] = useState<string | null>(null);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultWallets: WalletConfig[] = [
      { id: 'w1', name: 'Prepagata Flash', method: PaymentMethod.Flash, icon: 'zap' },
      { id: 'w2', name: 'Prepagata Revolut', method: PaymentMethod.Revolut, icon: 'wallet' },
      { id: 'w3', name: 'App Q8', method: PaymentMethod.AppQ8, icon: 'fuel' }
    ];

    const defaultCategories: CategoryConfig[] = [
      { id: 'c1', name: 'Sigarette', color: '#ef4444' }, // Rosso
      { id: 'c2', name: 'Benzina', color: '#f97316' }, // Arancione
      { id: 'c3', name: 'Autostrada', color: '#eab308' }, // Giallo scuro
      { id: 'c4', name: 'Ricarica Chiavetta', color: '#84cc16' }, // Lime
      { id: 'c5', name: 'Svago', color: '#06b6d4' }, // Ciano
      { id: 'c6', name: 'Salute', color: '#ec4899' }, // Rosa
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true, color: '#8b5cf6' }, // Viola
      { id: 'c8', name: 'Altro', color: '#64748b' } // Grigio
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories,
      language: 'it'
    };

    if (!saved) return defaultSettings;

    try {
      const parsed = JSON.parse(saved);
      if (!parsed.categories) {
        parsed.categories = defaultCategories;
      } else {
        // Migration: assegna colori se mancano
        parsed.categories = parsed.categories.map((c: any, idx: number) => ({
          ...c,
          color: c.color || defaultCategories[idx % defaultCategories.length]?.color || '#10b981'
        }));
      }
      if (!parsed.language) {
        parsed.language = 'it';
      }
      return { ...defaultSettings, ...parsed };
    } catch {
      return defaultSettings;
    }
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  useEffect(() => {
    const initSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session?.user) {
        const metadata = session.user.user_metadata;
        const displayName = metadata.full_name || metadata.display_name || metadata.name || session.user.email?.split('@')[0] || 'Utente';
        setUserSettings(prev => ({ ...prev, name: displayName }));
      }
      setIsInitialLoading(false);
    };
    initSession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchExpenses = useCallback(async () => {
    if (!session?.user?.id) return;
    try {
      setIsLoading(true);
      const data = await db.getExpenses(session.user.id);
      setExpenses(data);

      // Check new month
      const today = new Date();
      const currentMonthKey = format(startOfMonth(today), 'yyyy-MM');
      const lastArchivedMonth = localStorage.getItem('mintflow_last_archived');
      if (today.getDate() === 1 && lastArchivedMonth !== currentMonthKey) {
        setShowNewMonthToast(true);
        localStorage.setItem('mintflow_last_archived', currentMonthKey);
        setTimeout(() => setShowNewMonthToast(false), 8000);
      }
    } catch (err) {
      console.error("Errore caricamento:", err);
    } finally {
      setIsLoading(false);
    }
  }, [session]);

  useEffect(() => {
    if (session?.user?.id) {
      fetchExpenses();
    }
  }, [session, fetchExpenses]);

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
    if (userSettings.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [userSettings]);

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      const expenseDate = parseISO(expenseData.date);
      const today = new Date();
      const isPast = !isSameMonth(expenseDate, today) && expenseDate < startOfMonth(today);
      const isFutureDate = isAfter(expenseDate, endOfMonth(today));

      let savedExpense: Expense | null = null;
      if (prefill?.id) {
        savedExpense = await db.updateExpense(prefill.id, expenseData);
        if (savedExpense) setExpenses(prev => prev.map(e => e.id === savedExpense!.id ? savedExpense! : e));
        setSuccessToast("Modifica salvata!");
      } else {
        savedExpense = await db.addExpense(expenseData, session.user.id);
        if (savedExpense) setExpenses(prev => [savedExpense!, ...prev]);
        setSuccessToast(isPast ? "Spesa salvata nello storico!" : isFutureDate ? "Spesa futura programmata!" : "Spesa aggiunta!");
      }

      setShowForm(false);
      setPrefill(null);

      // Se la spesa non è del mese corrente, portiamo l'utente sulla lista per fargliela vedere
      if (isPast || isFutureDate) {
        setActiveTab('list');
      }

      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      alert(`Errore Cloud: ${err.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = async (file: File): Promise<{ imported: number, skipped: number, errors: string[], debugInfo: string }> => {
    setIsSyncing(true);
    let importedCount = 0;
    let skippedCount = 0;
    const errors: string[] = [];
    let debugInfo = "";

    try {
      const text = await file.text();
      const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');

      if (lines.length === 0) throw new Error("Il file è vuoto");

      // --- 1. Rilevamento Separatore Migliorato ---
      // Conta le occorrenze di ; e , nelle prime righe per decidere
      const sample = lines.slice(0, 5).join('');
      const semiCount = (sample.match(/;/g) || []).length;
      const commaCount = (sample.match(/,/g) || []).length;
      const separator = semiCount >= commaCount ? ';' : ',';

      // --- DEBUG ALERT: Togli commento se vuoi vedere questo alert ---
      // alert(`DEBUG: Letto file. Righe: ${lines.length}. Separatore rilevato: "${separator}". Prima riga: ${lines[0]}`);

      // --- 2. Rilevamento Colonne (Header Mapping) ---
      const headers = lines[0].toLowerCase().split(separator).map(h => h.trim().replace(/^"|"$/g, ''));

      let dateIdx = -1;
      let descIdx = -1;
      let amountIdx = -1;
      let catIdx = -1;
      let pmIdx = -1;

      headers.forEach((h, i) => {
        if (h.includes('date') || h.includes('data') || h.includes('giorno')) dateIdx = i;
        else if (h.includes('desc') || h.includes('causale') || h.includes('testo') || h.includes('nome') || h.includes('oggett')) descIdx = i;
        else if (h.includes('amount') || h.includes('importo') || h.includes('euro') || h.includes('valore') || h.includes('prezzo')) amountIdx = i;
        else if (h.includes('cat')) catIdx = i;
        else if (h.includes('metodo') || h.includes('pagamento') || h.includes('payment')) pmIdx = i;
      });

      debugInfo = `Separatore: '${separator}'. Colonne rilevate -> Data: ${dateIdx}, Desc: ${descIdx}, Importo: ${amountIdx}. Header: ${headers.join(' | ')}`;

      // Se non abbiamo trovato header significativi, usiamo fallback posizionale (0, 1, 2)
      if (dateIdx === -1) { dateIdx = 0; debugInfo += " (Fallback Data=0)"; }
      if (descIdx === -1) { descIdx = 1; debugInfo += " (Fallback Desc=1)"; }
      if (amountIdx === -1) { amountIdx = 2; debugInfo += " (Fallback Importo=2)"; }

      // Helper per pulire valori
      const cleanVal = (val: string) => val ? val.replace(/^"|"$/g, '').replace(/""/g, '"').trim() : '';

      // Skip della prima riga SOLO se sembra un header
      const firstVal = lines[0].split(separator)[amountIdx];
      const hasHeader = (lines[0].toLowerCase().includes('data') || lines[0].toLowerCase().includes('date') || isNaN(parseFloat(firstVal?.replace(',', '.') || 'ABC')));
      const startIdx = hasHeader ? 1 : 0;

      for (let i = startIdx; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        // Split manuale per gestire virgolette
        const parts: string[] = [];
        let current = '';
        let inQuote = false;
        for (let char of line) {
          if (char === '"') { inQuote = !inQuote; } 
          else if (char === separator && !inQuote) { parts.push(current); current = ''; } 
          else { current += char; }
        }
        parts.push(current);

        const rawDate = cleanVal(parts[dateIdx]);
        const rawDesc = cleanVal(parts[descIdx]);
        const rawAmount = cleanVal(parts[amountIdx]);
        const rawCat = catIdx > -1 ? cleanVal(parts[catIdx]) : '';
        const rawPm = pmIdx > -1 ? cleanVal(parts[pmIdx]) : '';

        if (!rawDate && !rawAmount) {
           errors.push(`Riga ${i+1}: Saltata (Data e Importo vuoti). Raw: ${line.substring(0, 20)}...`);
           continue;
        }

        // --- Parsing Data ---
        let date = null;
        if (rawDate.match(/^\d{4}-\d{2}-\d{2}$/)) {
            date = rawDate;
        } else {
            // Cerca pattern dd/mm/yyyy o dd.mm.yyyy
            const dateParts = rawDate.match(/(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})/);
            if (dateParts) {
                let [_, d, m, y] = dateParts;
                if (y.length === 2) y = "20" + y;
                date = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
            }
        }

        if (!date) {
            errors.push(`Riga ${i+1}: Formato data non riconosciuto ("${rawDate}")`);
            continue;
        }

        // --- Parsing Importo ---
        let amountStr = rawAmount.replace(/[^0-9.,-]/g, '');
        if (amountStr.endsWith('-')) amountStr = '-' + amountStr.slice(0, -1);

        if (amountStr.includes(',') && amountStr.includes('.')) {
             if (amountStr.lastIndexOf(',') > amountStr.lastIndexOf('.')) {
                 amountStr = amountStr.replace(/\./g, '').replace(',', '.');
             } else {
                 amountStr = amountStr.replace(/,/g, '');
             }
        } else if (amountStr.includes(',')) {
             amountStr = amountStr.replace(',', '.');
        }

        const amount = parseFloat(amountStr);
        if (isNaN(amount)) {
            errors.push(`Riga ${i+1}: Importo non valido ("${rawAmount}")`);
            continue;
        }

        const description = rawDesc || "Spesa importata";
        const category = rawCat || "Altro";

        // --- Controllo Duplicati ---
        const isDuplicate = expenses.some(e => 
           e.date === date && 
           Math.abs(e.amount - amount) < 0.01 && 
           e.description.toLowerCase().trim() === description.toLowerCase().trim()
        );

        if (isDuplicate) {
           skippedCount++;
           errors.push(`Riga ${i+1}: Duplicato saltato (${date} - ${amount})`);
           continue;
        }

        // --- Metodo Pagamento ---
        let pm = PaymentMethod.Contanti;
        const normPm = rawPm.toLowerCase();
        if (normPm.includes('flash')) pm = PaymentMethod.Flash;
        else if (normPm.includes('revolut')) pm = PaymentMethod.Revolut;
        else if (normPm.includes('q8')) pm = PaymentMethod.AppQ8;
        else if (normPm.includes('bancomat') || normPm.includes('card') || normPm.includes('carta')) pm = PaymentMethod.Bancomat;

        await db.addExpense({
           date,
           description,
           amount,
           category,
           paymentMethod: pm,
           isSubscription: false
        }, session.user.id);

        importedCount++;
      }

      // Ricarica dati
      if (importedCount > 0) {
        await fetchExpenses();
        setSuccessToast(`${importedCount} spese importate`);
        setTimeout(() => setSuccessToast(null), 4000);
      } 

      return { imported: importedCount, skipped: skippedCount, errors, debugInfo };

    } catch (err: any) {
      console.error(err);
      throw new Error("Errore lettura file: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleExportCSV = () => {
    if (expenses.length === 0) {
      alert("Nessuna spesa da esportare.");
      return;
    }

    try {
      const headers = ["Date", "Description", "Amount", "Category", "PaymentMethod", "IsSubscription"];
      const rows = expenses.map(e => {
        const safeDesc = e.description.replace(/"/g, '""');
        return [
          e.date,
          `"${safeDesc}"`,
          e.amount.toFixed(2),
          `"${e.category}"`,
          e.paymentMethod,
          e.isSubscription ? "true" : "false"
        ].join(",");
      });

      const csvContent = [headers.join(","), ...rows].join("\n");
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `mintflow_export_${format(new Date(), 'yyyyMMdd_HHmm')}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setSuccessToast("Esportazione completata!");
      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      console.error(err);
      alert("Errore esportazione: " + err.message);
    }
  };

  const requestDeleteExpense = useCallback((id: string) => {
    setExpenseToDelete(id);
  }, []);

  const confirmDeleteExpense = async () => {
    if (!expenseToDelete) return;

    try {
      setIsSyncing(true);
      await db.deleteExpense(expenseToDelete);
      setExpenses(prev => prev.filter(e => e.id !== expenseToDelete));
      setSuccessToast("Spesa eliminata.");
      setTimeout(() => setSuccessToast(null), 2000);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsSyncing(false);
      setExpenseToDelete(null);
    }
  };

  const handleClearData = async () => {
    if (window.confirm('Resettare tutte le spese dal cloud?')) {
      try {
        setIsSyncing(true);
        await db.clearAll(session.user.id);
        setExpenses([]);
      } catch (err: any) {
        alert("Errore: " + err.message);
      } finally {
        setIsSyncing(false);
      }
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex flex-col items-center justify-center gap-4">
        <div className="bg-emerald-500 p-5 rounded-3xl text-white shadow-2xl animate-pulse">
          <PiggyBank size={48} />
        </div>
        <div className="flex flex-col items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold">
          <Loader2 size={20} className="animate-spin" />
          <span>MintFlow Sync...</span>
        </div>
      </div>
    );
  }

  if (!session) return <Auth onSuccess={() => {}} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} lang={userSettings.language}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {/* Success Toast */}
        {successToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in slide-in-from-top-4 duration-300">
            <CheckCircle2 size={18} />
            <span className="font-bold text-sm">{successToast}</span>
          </div>
        )}

        {showNewMonthToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] w-[90%] max-w-sm bg-emerald-500 text-white p-6 rounded-[2rem] shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-4 duration-500">
            <div className="bg-white/20 p-3 rounded-2xl shrink-0"><PartyPopper size={24} /></div>
            <div>
              <p className="font-bold text-sm">Nuovo mese iniziato! 🚀</p>
              <p className="text-[10px] opacity-90 uppercase font-bold tracking-widest mt-1 flex items-center gap-1"><History size={10} /> Dati archiviati</p>
            </div>
            <button onClick={() => setShowNewMonthToast(false)} className="ml-auto opacity-50">✕</button>
          </div>
        )}

        <div className="flex justify-end items-center mb-4 px-2">
          <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-gray-400">
            {isSyncing ? <><Loader2 size={12} className="animate-spin text-emerald-500" /> <span className="text-emerald-500">Cloud Sync...</span></> : <><Cloud size={12} className="text-emerald-400" /> <span>Sincronizzato</span></>}
          </div>
        </div>

        {activeTab !== 'dashboard' && (
          <div className="mb-6">
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white capitalize">
               {activeTab === 'list' ? (userSettings.language === 'en' ? 'Your Expenses' : 'Le tue Spese') : 
                activeTab === 'ai' ? 'AI Insights' : 
                activeTab === 'ricariche' ? (userSettings.language === 'en' ? 'Wallets' : 'Portafogli') : 
                activeTab === 'subscriptions' ? (userSettings.language === 'en' ? 'Subscriptions' : 'Abbonamenti') : 
                (userSettings.language === 'en' ? 'Settings' : 'Impostazioni')}
            </h1>
          </div>
        )}

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
             <Loader2 size={48} className="text-emerald-500 animate-spin" />
             <p className="text-gray-400 font-medium">Caricamento...</p>
          </div>
        ) : (
          <>
            {activeTab === 'dashboard' && (
              <Dashboard 
                expenses={expenses} 
                budget={userSettings.monthlyBudget} 
                userName={userSettings.name} 
                currency={userSettings.currency} 
                wallets={userSettings.wallets}
                categories={userSettings.categories}
                lang={userSettings.language}
              />
            )}

            {activeTab === 'list' && (
              <div className="space-y-6">
                <div className="flex gap-3">
                  <button type="button" onClick={() => { setPrefill(null); setShowForm(true); }} className="flex-1 bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-lg active:scale-95"><Plus size={20} /> <span className="font-bold">{userSettings.language === 'en' ? 'Add' : 'Aggiungi'}</span></button>
                  <button type="button" onClick={() => setShowScanner(true)} className="flex-1 bg-white dark:bg-gray-800 border-2 border-emerald-100 dark:border-gray-700 text-emerald-600 dark:text-emerald-400 px-4 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-sm active:scale-95"><ScanLine size={20} /> <span className="font-bold">Scan</span></button>
                </div>
                <ExpenseList expenses={expenses} onDelete={requestDeleteExpense} onEdit={(ex) => {setPrefill(ex); setShowForm(true);}} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
              </div>
            )}

            {activeTab === 'subscriptions' && (
              <SubscriptionsView expenses={expenses} onAddSub={() => { 
                const subCat = userSettings.categories.find(c => c.isSubscriptionDefault)?.name || 'Abbonamenti';
                setPrefill({ isSubscription: true, category: subCat }); 
                setShowForm(true); 
              }} onDelete={requestDeleteExpense} currency={userSettings.currency} />
            )}

            {activeTab === 'ricariche' && (
              <RicaricheView 
                onRefill={(wallet) => {
                  setPrefill({ 
                    description: `Ricarica ${wallet.name}`, 
                    category: 'Altro', 
                    paymentMethod: PaymentMethod.Bancomat, 
                    date: format(new Date(), 'yyyy-MM-dd') 
                  });
                  setShowForm(true);
                }} 
                onSaveExpense={handleSaveExpense}
                expenses={expenses} 
                currency={userSettings.currency} 
                wallets={userSettings.wallets} 
              />
            )}

            {activeTab === 'ai' && <AiInsights expenses={expenses} />}
            {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={handleClearData} onImport={handleImportCSV} onExport={handleExportCSV} expenses={expenses} email={session.user.email} />}
          </>
        )}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl relative animate-in zoom-in-95 duration-200">
              <button type="button" onClick={() => { setShowForm(false); setPrefill(null); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 p-2">✕</button>
              <h2 className="text-2xl font-bold mb-6 text-gray-800 dark:text-white">{prefill?.id ? 'Modifica' : 'Nuova Spesa'}</h2>
              <ExpenseForm 
                onSubmit={handleSaveExpense} 
                onCancel={() => { setShowForm(false); setPrefill(null); }} 
                initialData={prefill || undefined} 
                currency={userSettings.currency} 
                wallets={userSettings.wallets} 
                categories={userSettings.categories} 
                expenses={expenses}
              />
            </div>
          </div>
        )}

        {/* Delete Confirmation Modal */}
        {expenseToDelete && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-red-900/20 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-xs p-8 shadow-2xl text-center animate-in zoom-in-95 duration-300 border-4 border-red-100 dark:border-red-900/30">
              <div className="bg-red-100 dark:bg-red-900/30 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-red-600">
                <Trash2 size={32} />
              </div>
              <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">Elimina Spesa?</h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-8 leading-relaxed">
                Questa azione è irreversibile. Sei sicuro di voler procedere?
              </p>
              <div className="flex flex-col gap-3">
                <button 
                  onClick={confirmDeleteExpense}
                  disabled={isSyncing}
                  className="w-full py-4 bg-red-500 hover:bg-red-600 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-colors"
                >
                  {isSyncing ? <Loader2 className="animate-spin" size={18} /> : <Trash2 size={18} />} Elimina
                </button>
                <button 
                  onClick={() => setExpenseToDelete(null)}
                  className="w-full py-3 text-gray-400 font-bold hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
                >
                  Annulla
                </button>
              </div>
            </div>
          </div>
        )}

        {showScanner && <ReceiptScanner onDetected={(res) => { setPrefill({...res, date: format(new Date(), 'yyyy-MM-dd')}); setShowScanner(false); setShowForm(true); }} onClose={() => setShowScanner(false)} />}
      </div>
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { UserSettings, Expense, WalletConfig, CategoryConfig, PaymentMethod } from '../types';
import { User, DollarSign, Trash2, Download, Moon, Sun, LogOut, FileDown, History, CheckCircle2, ShieldCheck, Edit3, X, Mail, Globe, Lock, Wallet, Tag, ChevronRight, Plus, ChevronLeft, Save, Check, Upload, Loader2 } from 'lucide-react';
import { auth } from '../services/supabase';
import { format } from 'date-fns';
import { HistoryView } from './HistoryView';
import { translations } from '../utils/i18n';

const SettingsRow = ({ icon, label, onClick }: { icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button type="button" onClick={onClick} className="w-full flex items-center justify-between px-6 py-5 md:px-8 md:py-6 hover:bg-emerald-50 dark:hover:bg-gray-700/50 transition-all group">
    <div className="flex items-center gap-4">{icon}<span className="font-bold text-gray-700 dark:text-gray-200 text-sm md:text-base">{label}</span></div>
    <ChevronRight className="text-gray-300 group-hover:text-emerald-500 group-hover:translate-x-1 transition-all" size={20} />
  </button>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-md z-[110] flex items-center justify-center p-4">
      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{title}</h2>
          <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>
        </div>
        {children}
      </div>
    </div>
  );
};

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  onImport?: (file: File) => Promise<{ imported: number; skipped: number; errors: string[], debugInfo: string }>;
  onExport?: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  onImport,
  onExport,
  expenses,
  email
}) => {
  const [view, setView] = useState<'main' | 'history' | 'wallets' | 'categories'>('main');
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  // States for adding new items
  const [isAdding, setIsAdding] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemColor, setNewItemColor] = useState('#10b981');

  // States for editing existing items
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editColor, setEditColor] = useState('');

  const [tempName, setTempName] = useState(settings.name);
  const [tempEmail, setTempEmail] = useState(email || '');
  const [isUpdating, setIsUpdating] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const lang = settings.language || 'it';
  const t = translations[lang].settings;
  const tNav = translations[lang].nav;

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 3000);
  };

  const handleUpdateProfile = async () => {
    setIsUpdating(true);
    try {
      if (tempName !== settings.name) {
        await auth.updateProfile(tempName);
        onUpdate({ ...settings, name: tempName });
      }
      if (tempEmail !== email) {
        await auth.updateEmail(tempEmail);
        showFeedback("Email inviata!");
      } else {
        showFeedback("Profilo aggiornato!");
      }
      setShowProfileModal(false);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdatePassword = async () => {
    if (newPassword.length < 6) return alert("Minimo 6 caratteri");
    setIsUpdating(true);
    try {
      await auth.updatePassword(newPassword);
      showFeedback("Password aggiornata!");
      setShowPasswordModal(false);
      setNewPassword('');
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDeleteAccount = async () => {
    if (window.confirm("Vuoi eliminare DEFINITIVAMENTE l'account?")) {
      try {
        setIsUpdating(true);
        await auth.deleteAccount();
      } catch (err: any) {
        await auth.signOut();
      } finally {
        setIsUpdating(false);
      }
    }
  };

  const handleAddItem = (type: 'wallet' | 'category') => {
    if (!newItemName.trim()) return;

    if (type === 'wallet') {
      const newWallet: WalletConfig = {
        id: 'w' + Date.now(),
        name: newItemName.trim(),
        method: newItemName.trim() as PaymentMethod,
        icon: 'credit-card'
      };
      onUpdate({ ...settings, wallets: [...settings.wallets, newWallet] });
    } else {
      const newCat: CategoryConfig = {
        id: 'c' + Date.now(),
        name: newItemName.trim(),
        color: newItemColor
      };
      onUpdate({ ...settings, categories: [...settings.categories, newCat] });
    }

    setNewItemName('');
    setIsAdding(false);
    showFeedback("Aggiunto con successo!");
  };

  const startEditing = (item: CategoryConfig) => {
    setEditingId(item.id);
    setEditName(item.name);
    setEditColor(item.color || '#10b981');
  };

  const saveEdit = () => {
    if (!editName.trim()) return;
    const newCats = settings.categories.map(c => 
      c.id === editingId ? { ...c, name: editName, color: editColor } : c
    );
    onUpdate({ ...settings, categories: newCats });
    setEditingId(null);
    showFeedback("Modifica salvata!");
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !onImport) return;

    if (!file.name.endsWith('.csv')) {
      alert('Seleziona un file .csv valido');
      return;
    }

    if (window.confirm(`Vuoi importare le spese da "${file.name}"?`)) {
      setIsImporting(true);
      try {
        const { imported, skipped, errors, debugInfo } = await onImport(file);

        let msg = '';
        if (imported > 0) msg += `✅ IMPORTAZIONE RIUSCITA: ${imported} spese aggiunte.\n\n`;
        if (skipped > 0) msg += `⚠️ ${skipped} spese erano duplicati (stessa data, importo e descrizione) e sono state saltate.\n\n`;

        if (errors.length > 0) {
           msg += `❌ ERRORI (${errors.length} righe scartate):\n`;
           msg += errors.slice(0, 10).join('\n'); // Mostra i primi 10 errori
           if (errors.length > 10) msg += `\n...e altri ${errors.length - 10}.`;
           msg += `\n\n🔍 INFO DEBUG: ${debugInfo}`;
        }

        if (msg) {
             alert(msg);
        } else if (imported === 0 && skipped === 0 && errors.length === 0) {
             alert(`Nessuna spesa trovata. Il file sembra vuoto o il formato è sconosciuto.\nINFO DEBUG: ${debugInfo}`);
        }

      } catch (err: any) {
        alert("Errore critico durante l'importazione: " + err.message);
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    } else {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  if (view === 'history') return <HistoryView expenses={expenses} onClose={() => setView('main')} currency={settings.currency} />;

  if (view === 'wallets') return (
    <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[80] overflow-y-auto animate-in slide-in-from-right duration-300">
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6"><ChevronLeft /> {tNav.settings}</button>
        <h2 className="text-3xl font-bold dark:text-white mb-6">{t.manageWallets}</h2>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm space-y-4">
          {settings.wallets.map(w => (
            <div key={w.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-2xl relative">
              <div className="flex items-center gap-3 font-bold dark:text-white"><Wallet className="text-emerald-500" /> {w.name}</div>
              <button 
                type="button"
                onClick={() => {
                  onUpdate({ ...settings, wallets: settings.wallets.filter(x => x.id !== w.id) });
                }} 
                className="p-2.5 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-all flex items-center justify-center relative z-30"
              >
                <Trash2 size={18} className="pointer-events-none" />
              </button>
            </div>
          ))}

          {isAdding ? (
            <div className="space-y-3 p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <input 
                autoFocus
                type="text" 
                value={newItemName} 
                onChange={(e) => setNewItemName(e.target.value)}
                placeholder="Nome portafoglio..."
                className="w-full px-4 py-3 rounded-xl bg-white dark:bg-gray-700 border-none outline-none dark:text-white font-bold"
              />
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('wallet')} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold text-sm">Salva</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-3 bg-white dark:bg-gray-600 text-gray-400 rounded-xl font-bold text-sm">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 mt-4 transition-transform active:scale-95"><Plus size={20} /> Aggiungi</button>
          )}
        </div>
      </div>
    </div>
  );

  if (view === 'categories') return (
    <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[80] overflow-y-auto animate-in slide-in-from-right duration-300">
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6"><ChevronLeft /> {tNav.settings}</button>
        <h2 className="text-3xl font-bold dark:text-white mb-6">{t.manageCategories}</h2>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm space-y-4">
          {settings.categories.map(c => (
            <div key={c.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-2xl relative group min-h-[72px]">
              {editingId === c.id ? (
                <div className="flex-1 flex items-center gap-3 animate-in fade-in duration-200 w-full overflow-hidden">
                  <input 
                    type="color" 
                    value={editColor} 
                    onChange={(e) => setEditColor(e.target.value)}
                    className="w-10 h-10 border-none bg-transparent cursor-pointer rounded-full shrink-0"
                  />
                  <input 
                    autoFocus
                    type="text" 
                    value={editName} 
                    onChange={(e) => setEditName(e.target.value)}
                    className="flex-1 min-w-0 px-3 py-2 bg-white dark:bg-gray-600 rounded-xl border-none outline-none dark:text-white font-bold"
                  />
                  <div className="flex gap-1 ml-2 shrink-0">
                    <button onClick={saveEdit} className="p-2 bg-emerald-500 text-white rounded-full hover:bg-emerald-600"><Check size={18} /></button>
                    <button onClick={() => setEditingId(null)} className="p-2 bg-gray-200 dark:bg-gray-600 text-gray-500 rounded-full hover:bg-gray-300"><X size={18} /></button>
                  </div>
                </div>
              ) : (
                <>
                  <div className="flex items-center gap-3 font-bold dark:text-white">
                    <div 
                      className="w-8 h-8 rounded-full border border-gray-200 dark:border-gray-600 shadow-sm"
                      style={{ backgroundColor: c.color || '#10b981' }}
                    ></div>
                    <span>{c.name}</span>
                  </div>

                  <div className="flex items-center gap-2">
                    <button 
                      type="button"
                      onClick={() => startEditing(c)} 
                      className="p-2.5 text-blue-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-full transition-all flex items-center justify-center"
                    >
                      <Edit3 size={18} />
                    </button>

                    {!c.isSubscriptionDefault && (
                      <button 
                        type="button"
                        onClick={() => {
                          onUpdate({ ...settings, categories: settings.categories.filter(x => x.id !== c.id) });
                        }} 
                        className="p-2.5 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-all flex items-center justify-center"
                      >
                        <Trash2 size={18} />
                      </button>
                    )}
                  </div>
                </>
              )}
            </div>
          ))}

          {isAdding ? (
            <div className="space-y-3 p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <div className="flex items-center gap-3 bg-white dark:bg-gray-700 rounded-xl px-2">
                <input 
                  type="color" 
                  value={newItemColor} 
                  onChange={(e) => setNewItemColor(e.target.value)}
                  className="w-10 h-10 border-none bg-transparent cursor-pointer rounded-full shrink-0"
                />
                <input 
                  autoFocus
                  type="text" 
                  value={newItemName} 
                  onChange={(e) => setNewItemName(e.target.value)}
                  placeholder="Nome categoria..."
                  className="flex-1 px-2 py-3 bg-transparent border-none outline-none dark:text-white font-bold min-w-0"
                />
              </div>
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('category')} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold text-sm">Salva</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-3 bg-white dark:bg-gray-600 text-gray-400 rounded-xl font-bold text-sm">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 mt-4 transition-transform active:scale-95"><Plus size={20} /> Aggiungi</button>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {feedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 bg-emerald-500 text-white rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in zoom-in duration-300">
          <CheckCircle2 size={16} />
          <span className="font-bold text-xs uppercase tracking-wider">{feedback}</span>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 p-6 md:p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm relative overflow-hidden">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 md:mb-8">
          <div className="flex items-center gap-3 md:gap-4 overflow-hidden">
            <div className="bg-emerald-500 p-3 md:p-4 rounded-3xl text-white shrink-0">
              <User className="w-6 h-6 md:w-8 md:h-8" />
            </div>
            <div className="min-w-0 flex-1">
              <h3 className="text-lg md:text-xl font-bold text-gray-800 dark:text-white truncate">{t.profile}</h3>
              <p className="text-gray-400 text-xs md:text-sm truncate">{email}</p>
            </div>
          </div>
          <div className="flex gap-2 shrink-0 self-start sm:self-auto ml-12 sm:ml-0">
            <button type="button" onClick={() => setShowProfileModal(true)} className="flex items-center gap-2 px-3 py-2 md:px-4 md:py-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-xl font-bold text-[10px] md:text-xs hover:bg-emerald-100 transition-all whitespace-nowrap">
              <Edit3 size={14} /> {t.edit}
            </button>
            <button 
              type="button" 
              onClick={() => onUpdate({ ...settings, language: lang === 'it' ? 'en' : 'it' })} 
              className="flex items-center gap-2 px-3 py-2 md:px-4 md:py-2 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-xl font-bold text-[10px] md:text-xs hover:bg-blue-100 transition-all whitespace-nowrap"
            >
              <Globe size={14} /> {lang === 'it' ? 'ITA' : 'ENG'}
            </button>
          </div>
        </div>
        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 md:mb-3 ml-1">{t.displayName}</label>
          <div className="w-full px-5 py-3 md:px-6 md:py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 dark:text-white font-bold text-base md:text-lg truncate">{settings.name}</div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-hidden">
        <SettingsRow icon={<Lock className="text-emerald-500" size={20} />} label={t.changePassword} onClick={() => setShowPasswordModal(true)} />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow icon={<Wallet className="text-emerald-500" size={20} />} label={t.manageWallets} onClick={() => setView('wallets')} />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow icon={<Tag className="text-emerald-500" size={20} />} label={t.manageCategories} onClick={() => setView('categories')} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2"><DollarSign className="text-emerald-500" size={20} /> {t.monthlyBudget}</h3>
          <div className="space-y-4">
            <input type="number" value={settings.monthlyBudget} onChange={(e) => onUpdate({ ...settings, monthlyBudget: Number(e.target.value) })} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-black text-2xl" />
            <select value={settings.currency} onChange={(e) => onUpdate({ ...settings, currency: e.target.value })} className="w-full bg-gray-50 dark:bg-gray-700 dark:text-white px-4 py-3 rounded-2xl font-bold text-sm outline-none border-none">
              <option value="€">Euro (€)</option>
              <option value="$">Dollaro ($)</option>
              <option value="£">Sterlina (£)</option>
            </select>
          </div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">{settings.isDarkMode ? <Moon className="text-emerald-500" size={20} /> : <Sun className="text-emerald-500" size={20} />} {t.appearance}</h3>
          <div className="flex items-center justify-between p-6 rounded-2xl bg-gray-50 dark:bg-gray-700">
            <span className="font-bold text-gray-600 dark:text-gray-300">{settings.isDarkMode ? t.darkMode : t.lightMode}</span>
            <button type="button" onClick={() => onUpdate({ ...settings, isDarkMode: !settings.isDarkMode })} className={`w-14 h-8 rounded-full relative transition-colors p-1 ${settings.isDarkMode ? 'bg-emerald-500' : 'bg-gray-300'}`}>
              <div className={`w-6 h-6 bg-white rounded-full shadow-sm transition-all ${settings.isDarkMode ? 'translate-x-6' : 'translate-x-0'}`}></div>
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
        <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2"><FileDown className="text-emerald-500" size={20} /> {t.dataArchive}</h3>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          <button type="button" onClick={() => setView('history')} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><History size={20} /> <span className="text-xs md:text-sm">{t.history}</span></button>
          <button type="button" onClick={onExport} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><Download size={20} /> <span className="text-xs md:text-sm">{t.export}</span></button>

          {/* Import CSV Button */}
          <button 
            type="button" 
            onClick={() => fileInputRef.current?.click()} 
            disabled={isImporting}
            className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all relative overflow-hidden"
          >
            {isImporting ? <Loader2 size={20} className="animate-spin" /> : <Upload size={20} />} 
            <span className="text-xs md:text-sm">{t.import}</span>
            <input 
              type="file" 
              ref={fileInputRef}
              onClick={(e) => (e.target as HTMLInputElement).value = ''} // FIX CRITICO: Resetta il valore al click per forzare onChange anche se il file è lo stesso
              onChange={handleFileChange}
              accept=".csv"
              className="hidden" 
            />
          </button>
        </div>
      </div>

