import React, { useMemo } from 'react';
import { Expense, PaymentMethod, WalletConfig, CategoryConfig } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, ResponsiveContainer 
} from 'recharts';
import { Wallet, Calendar, Target, Zap, Fuel, CreditCard, Clock, ChevronRight } from 'lucide-react';
import { format, startOfMonth, endOfMonth, isWithinInterval, subMonths, isAfter } from 'date-fns';
import { it, enUS } from 'date-fns/locale';
import { translations } from '../utils/i18n';

interface DashboardProps {
  expenses: Expense[];
  budget: number;
  userName?: string;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
  lang?: 'it' | 'en';
}

export const Dashboard: React.FC<DashboardProps> = ({ expenses, budget, userName = 'Utente', currency = '€', wallets, categories, lang = 'it' }) => {
  const t = translations[lang].dashboard;
  const currentMonth = new Date();
  const currentMonthStart = startOfMonth(currentMonth);
  const currentMonthEnd = endOfMonth(currentMonth);

  const currentMonthExpenses = useMemo(() => {
    return expenses.filter(e => 
      isWithinInterval(new Date(e.date), { start: currentMonthStart, end: currentMonthEnd })
    );
  }, [expenses]);

  const futureExpenses = useMemo(() => {
    return expenses.filter(e => isAfter(new Date(e.date), currentMonthEnd));
  }, [expenses, currentMonthEnd]);

  const budgetExpenses = useMemo(() => {
    return currentMonthExpenses.filter(e => 
      e.paymentMethod === PaymentMethod.Contanti || e.paymentMethod === PaymentMethod.Bancomat
    );
  }, [currentMonthExpenses]);

  const totalCurrentMonth = budgetExpenses.reduce((sum, e) => sum + e.amount, 0);

  const lastMonthStart = startOfMonth(subMonths(currentMonth, 1));
  const lastMonthEnd = endOfMonth(subMonths(currentMonth, 1));
  const totalLastMonth = expenses
    .filter(e => 
      isWithinInterval(new Date(e.date), { start: lastMonthStart, end: lastMonthEnd }) &&
      (e.paymentMethod === PaymentMethod.Contanti || e.paymentMethod === PaymentMethod.Bancomat)
    )
    .reduce((sum, e) => sum + e.amount, 0);

  const diff = totalLastMonth > 0 ? ((totalCurrentMonth - totalLastMonth) / totalLastMonth) * 100 : 0;
  const budgetProgress = Math.min((totalCurrentMonth / budget) * 100, 100);

  const balances = useMemo(() => {
    return wallets.map(w => {
      // Calcolo entrate: Ricariche o Aggiustamenti (se non pagati dal wallet stesso)
      const totalRecharged = expenses
        .filter(e => {
          const desc = e.description.toLowerCase();
          const name = w.name.toLowerCase();
          const isInflow = desc.includes(`ricarica ${name}`) || desc.includes(`aggiustamento ${name}`);
          return isInflow && e.paymentMethod !== w.method;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      // Calcolo uscite: Pagati col wallet (escluse ricariche self-loop che non dovrebbero esistere, ma per sicurezza)
      // Nota: un 'aggiustamento' negativo avrà metodo = wallet, quindi rientra qui.
      const totalSpent = expenses
        .filter(e => e.paymentMethod === w.method && !e.description.toLowerCase().includes('ricarica'))
        .reduce((sum, e) => sum + e.amount, 0);

      return {
        ...w,
        value: Math.max(0, totalRecharged - totalSpent),
        icon: w.icon === 'zap' ? <Zap size={14} /> : w.icon === 'fuel' ? <Fuel size={14} /> : <CreditCard size={14} />,
        color: w.icon === 'zap' ? 'text-emerald-500' : 'text-blue-500'
      };
    });
  }, [expenses, wallets]);

  const categoryData = useMemo(() => {
    const data: Record<string, number> = {};
    currentMonthExpenses.forEach(e => {
      data[e.category] = (data[e.category] || 0) + e.amount;
    });
    return Object.entries(data)
      .map(([name, value]) => ({ name, value }))
      .filter(item => item.value > 0);
  }, [currentMonthExpenses]);

  // Helper per ottenere il colore della categoria
  const getCategoryColor = (catName: string) => {
    return categories.find(c => c.name === catName)?.color || '#9ca3af'; // Grigio default
  };

  const formatValue = (val: number) => `${currency}${val.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`;
  const isDark = document.documentElement.classList.contains('dark');
  const dateLocale = lang === 'en' ? enUS : it;

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="mb-2">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{t.hello}, {userName}! 👋</h2>
        <p className="text-gray-500 dark:text-gray-400 text-sm">{t.subtitle}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="md:col-span-2 bg-emerald-500 dark:bg-emerald-600 p-8 rounded-[2rem] text-white shadow-xl shadow-emerald-200/50 dark:shadow-none relative overflow-hidden">
          <div className="flex justify-between items-start mb-6">
            <div>
              <p className="text-emerald-50 text-xs font-bold uppercase tracking-wider mb-1">{t.spentThisMonth}</p>
              <h2 className="text-4xl font-black">{formatValue(totalCurrentMonth)}</h2>
            </div>
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm">
              <CreditCard size={24} />
            </div>
          </div>
          <div className="space-y-2">
            <div className="flex justify-between text-xs font-medium text-emerald-50">
              <span>{t.target}: {currency}{budget.toLocaleString('it-IT')}</span>
              <span>{Math.round(budgetProgress)}%</span>
            </div>
            <div className="h-2 w-full bg-white/20 rounded-full overflow-hidden">
              <div className="h-full bg-white transition-all duration-1000" style={{ width: `${budgetProgress}%` }}></div>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl"><Target size={20} /></div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold">{t.vsLastMonth}</p>
              <p className={`font-bold ${diff <= 0 ? 'text-emerald-600' : 'text-red-500'}`}>{diff <= 0 ? '-' : '+'}{Math.abs(diff).toFixed(1)}%</p>
            </div>
          </div>
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl"><Calendar size={20} /></div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold">{t.month}</p>
              <p className="font-bold dark:text-white capitalize">{format(currentMonth, "MMMM yyyy", { locale: dateLocale })}</p>
            </div>
          </div>
        </div>
      </div>

      {futureExpenses.length > 0 && (
        <div className="bg-emerald-50 dark:bg-emerald-900/10 p-5 rounded-[2rem] border border-emerald-200 dark:border-emerald-800 flex items-center justify-between group cursor-default">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-3 rounded-2xl text-white">
              <Clock size={20} />
            </div>
            <div>
              <p className="text-emerald-600 dark:text-emerald-400 font-bold text-sm">{t.plannedExpenses}</p>
              <p className="text-[10px] text-emerald-500/70 dark:text-emerald-500/50 font-bold uppercase tracking-wider">{t.plannedCount(futureExpenses.length)}</p>
            </div>
          </div>
          <p className="text-xl font-black text-emerald-600 dark:text-emerald-400">
            {currency}{futureExpenses.reduce((s, e) => s + e.amount, 0).toLocaleString('it-IT', { minimumFractionDigits: 2 })}
          </p>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-x-auto">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4 ml-2">{t.walletBalances}</h3>
        <div className="flex gap-4 px-2">
          {balances.map((wallet) => (
            <div key={wallet.name} className="flex-shrink-0 w-40 p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50">
              <div className="flex justify-between items-center mb-2">
                <div className={wallet.color}>{wallet.icon}</div>
                <span className="text-[8px] font-bold text-gray-400 uppercase">{wallet.name}</span>
              </div>
              <p className="font-bold dark:text-white">{currency}{wallet.value.toFixed(2)}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm flex flex-col">
          <h3 className="text-lg font-bold dark:text-white mb-6 self-start">{t.expenseDistribution}</h3>
          <div className="w-full h-[300px]">
            {categoryData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={categoryData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                    {categoryData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={getCategoryColor(entry.name)} strokeWidth={2} stroke={isDark ? '#1f2937' : '#fff'} />
                    ))}
                  </Pie>
                  <Tooltip 
                    contentStyle={{ 
                      borderRadius: '12px', border: 'none', 
                      backgroundColor: isDark ? '#1f2937' : '#ffffff', color: isDark ? '#ffffff' : '#000000',
                      boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)'
                    }} 
                  />
                </PieChart>
              </ResponsiveContainer>
            ) : <div className="h-full flex items-center justify-center text-gray-400">{t.noData}</div>}
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold dark:text-white mb-6">{t.topCategories}</h3>
          <div className="space-y-4">
            {categoryData.length > 0 ? (
              categoryData.sort((a,b) => b.value - a.value).slice(0, 5).map((entry, index) => (
                <div key={entry.name} className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-3 h-3 rounded-full border border-gray-100 dark:border-gray-600 shadow-sm" style={{ backgroundColor: getCategoryColor(entry.name) }}></div>
                    <span className="text-sm dark:text-gray-300">{entry.name}</span>
                  </div>
                  <span className="text-sm font-bold dark:text-white">{formatValue(entry.value)}</span>
                </div>
              ))
            ) : (
              <div className="text-center py-10 text-gray-400 text-sm">{t.noExpenses} {format(currentMonth, 'MMMM', { locale: dateLocale })}</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { ReceiptScanner } from './components/ReceiptScanner';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
import { Auth } from './components/Auth';
import { Expense, UserSettings, PaymentMethod, WalletConfig, CategoryConfig } from './types';
import { Plus, ScanLine, Cloud, Loader2, PiggyBank, PartyPopper, History, CheckCircle2, Trash2, AlertTriangle } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { startOfMonth, format, isSameMonth, parseISO, isAfter, endOfMonth } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [showNewMonthToast, setShowNewMonthToast] = useState(false);
  const [successToast, setSuccessToast] = useState<string | null>(null);

  // Stato per gestire l'eliminazione
  const [expenseToDelete, setExpenseToDelete] = useState<string | null>(null);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultWallets: WalletConfig[] = [
      { id: 'w1', name: 'Prepagata Flash', method: PaymentMethod.Flash, icon: 'zap' },
      { id: 'w2', name: 'Prepagata Revolut', method: PaymentMethod.Revolut, icon: 'wallet' },
      { id: 'w3', name: 'App Q8', method: PaymentMethod.AppQ8, icon: 'fuel' }
    ];

    const defaultCategories: CategoryConfig[] = [
      { id: 'c1', name: 'Sigarette', color: '#ef4444' }, // Rosso
      { id: 'c2', name: 'Benzina', color: '#f97316' }, // Arancione
      { id: 'c3', name: 'Autostrada', color: '#eab308' }, // Giallo scuro
      { id: 'c4', name: 'Ricarica Chiavetta', color: '#84cc16' }, // Lime
      { id: 'c5', name: 'Svago', color: '#06b6d4' }, // Ciano
      { id: 'c6', name: 'Salute', color: '#ec4899' }, // Rosa
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true, color: '#8b5cf6' }, // Viola
      { id: 'c8', name: 'Altro', color: '#64748b' } // Grigio
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories,
      language: 'it'
    };

    if (!saved) return defaultSettings;

    try {
      const parsed = JSON.parse(saved);
      if (!parsed.categories) {
        parsed.categories = defaultCategories;
      } else {
        // Migration: assegna colori se mancano
        parsed.categories = parsed.categories.map((c: any, idx: number) => ({
          ...c,
          color: c.color || defaultCategories[idx % defaultCategories.length]?.color || '#10b981'
        }));
      }
      if (!parsed.language) {
        parsed.language = 'it';
      }
      return { ...defaultSettings, ...parsed };
    } catch {
      return defaultSettings;
    }
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  useEffect(() => {
    const initSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session?.user) {
        const metadata = session.user.user_metadata;
        const displayName = metadata.full_name || metadata.display_name || metadata.name || session.user.email?.split('@')[0] || 'Utente';
        setUserSettings(prev => ({ ...prev, name: displayName }));
      }
      setIsInitialLoading(false);
    };
    initSession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchExpenses = useCallback(async () => {
    if (!session?.user?.id) return;
    try {
      setIsLoading(true);
      const data = await db.getExpenses(session.user.id);
      setExpenses(data);

      // Check new month
      const today = new Date();
      const currentMonthKey = format(startOfMonth(today), 'yyyy-MM');
      const lastArchivedMonth = localStorage.getItem('mintflow_last_archived');
      if (today.getDate() === 1 && lastArchivedMonth !== currentMonthKey) {
        setShowNewMonthToast(true);
        localStorage.setItem('mintflow_last_archived', currentMonthKey);
        setTimeout(() => setShowNewMonthToast(false), 8000);
      }
    } catch (err) {
      console.error("Errore caricamento:", err);
    } finally {
      setIsLoading(false);
    }
  }, [session]);

  useEffect(() => {
    if (session?.user?.id) {
      fetchExpenses();
    }
  }, [session, fetchExpenses]);

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
    if (userSettings.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [userSettings]);

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      const expenseDate = parseISO(expenseData.date);
      const today = new Date();
      const isPast = !isSameMonth(expenseDate, today) && expenseDate < startOfMonth(today);
      const isFutureDate = isAfter(expenseDate, endOfMonth(today));

      let savedExpense: Expense | null = null;
      if (prefill?.id) {
        savedExpense = await db.updateExpense(prefill.id, expenseData);
        if (savedExpense) setExpenses(prev => prev.map(e => e.id === savedExpense!.id ? savedExpense! : e));
        setSuccessToast("Modifica salvata!");
      } else {
        savedExpense = await db.addExpense(expenseData, session.user.id);
        if (savedExpense) setExpenses(prev => [savedExpense!, ...prev]);
        setSuccessToast(isPast ? "Spesa salvata nello storico!" : isFutureDate ? "Spesa futura programmata!" : "Spesa aggiunta!");
      }

      setShowForm(false);
      setPrefill(null);

      // Se la spesa non è del mese corrente, portiamo l'utente sulla lista per fargliela vedere
      if (isPast || isFutureDate) {
        setActiveTab('list');
      }

      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      alert(`Errore Cloud: ${err.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = async (file: File): Promise<{ imported: number, skipped: number, errors: string[], debugInfo: string }> => {
    if (!session?.user?.id) {
      throw new Error("Utente non autenticato. Impossibile salvare su Supabase.");
    }

    setIsSyncing(true);
    let importedCount = 0;
    let skippedCount = 0;
    const errors: string[] = [];
    let debugInfo = "";

    try {
      const text = await file.text();
      // Rimuoviamo BOM se presente e dividiamo le righe
      const cleanText = text.replace(/^\uFEFF/, ''); 
      const lines = cleanText.split(/\r?\n/).filter(line => line.trim() !== '');

      if (lines.length === 0) throw new Error("Il file è vuoto");

      // --- 1. Rilevamento Separatore Migliorato ---
      // Conta le occorrenze di ; e , nelle prime righe per decidere
      const sample = lines.slice(0, 5).join('');
      const semiCount = (sample.match(/;/g) || []).length;
      const commaCount = (sample.match(/,/g) || []).length;
      const separator = semiCount >= commaCount ? ';' : ',';

      // --- 2. Rilevamento Colonne (Header Mapping) ---
      const headers = lines[0].toLowerCase().split(separator).map(h => h.trim().replace(/^"|"$/g, ''));

      let dateIdx = -1;
      let descIdx = -1;
      let amountIdx = -1;
      let catIdx = -1;
      let pmIdx = -1;

      headers.forEach((h, i) => {
        if (h.includes('date') || h.includes('data') || h.includes('giorno')) dateIdx = i;
        else if (h.includes('desc') || h.includes('causale') || h.includes('testo') || h.includes('nome') || h.includes('oggett')) descIdx = i;
        else if (h.includes('amount') || h.includes('importo') || h.includes('euro') || h.includes('valore') || h.includes('prezzo')) amountIdx = i;
        else if (h.includes('cat')) catIdx = i;
        else if (h.includes('metodo') || h.includes('pagamento') || h.includes('payment')) pmIdx = i;
      });

      debugInfo = `Separatore: '${separator}'. Colonne rilevate -> Data: ${dateIdx}, Desc: ${descIdx}, Importo: ${amountIdx}. Header: ${headers.join(' | ')}`;

      // Se non abbiamo trovato header significativi, usiamo fallback posizionale (0, 1, 2)
      if (dateIdx === -1) { dateIdx = 0; debugInfo += " (Fallback Data=0)"; }
      if (descIdx === -1) { descIdx = 1; debugInfo += " (Fallback Desc=1)"; }
      if (amountIdx === -1) { amountIdx = 2; debugInfo += " (Fallback Importo=2)"; }

      // Helper per pulire valori
      const cleanVal = (val: string) => val ? val.replace(/^"|"$/g, '').replace(/""/g, '"').trim() : '';

      // Skip della prima riga SOLO se sembra un header
      const firstVal = lines[0].split(separator)[amountIdx];
      const hasHeader = (lines[0].toLowerCase().includes('data') || lines[0].toLowerCase().includes('date') || isNaN(parseFloat(firstVal?.replace(',', '.') || 'ABC')));
      const startIdx = hasHeader ? 1 : 0;

      for (let i = startIdx; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        try {
          // Split manuale per gestire virgolette
          const parts: string[] = [];
          let current = '';
          let inQuote = false;
          for (let char of line) {
            if (char === '"') { inQuote = !inQuote; } 
            else if (char === separator && !inQuote) { parts.push(current); current = ''; } 
            else { current += char; }
          }
          parts.push(current);

          const rawDate = cleanVal(parts[dateIdx]);
          const rawDesc = cleanVal(parts[descIdx]);
          const rawAmount = cleanVal(parts[amountIdx]);
          const rawCat = catIdx > -1 ? cleanVal(parts[catIdx]) : '';
          const rawPm = pmIdx > -1 ? cleanVal(parts[pmIdx]) : '';

          if (!rawDate && !rawAmount) {
             errors.push(`Riga ${i+1}: Saltata (Data e Importo vuoti).`);
             continue;
          }

          // --- Parsing Data ---
          let date = null;
          if (rawDate.match(/^\d{4}-\d{2}-\d{2}$/)) {
              date = rawDate;
          } else {
              // Cerca pattern dd/mm/yyyy o dd.mm.yyyy
              const dateParts = rawDate.match(/(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})/);
              if (dateParts) {
                  let [_, d, m, y] = dateParts;
                  if (y.length === 2) y = "20" + y;
                  date = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
              }
          }

          if (!date) {
              errors.push(`Riga ${i+1}: Formato data non riconosciuto ("${rawDate}")`);
              continue;
          }

          // --- Parsing Importo ---
          let amountStr = rawAmount.replace(/[^0-9.,-]/g, '');
          if (amountStr.endsWith('-')) amountStr = '-' + amountStr.slice(0, -1);

          if (amountStr.includes(',') && amountStr.includes('.')) {
               if (amountStr.lastIndexOf(',') > amountStr.lastIndexOf('.')) {
                   amountStr = amountStr.replace(/\./g, '').replace(',', '.');
               } else {
                   amountStr = amountStr.replace(/,/g, '');
               }
          } else if (amountStr.includes(',')) {
               amountStr = amountStr.replace(',', '.');
          }

          const amount = parseFloat(amountStr);
          if (isNaN(amount)) {
              errors.push(`Riga ${i+1}: Importo non valido ("${rawAmount}")`);
              continue;
          }

          const description = rawDesc || "Spesa importata";
          const category = rawCat || "Altro";

          // --- Controllo Duplicati ---
          const isDuplicate = expenses.some(e => 
             e.date === date && 
             Math.abs(e.amount - amount) < 0.01 && 
             e.description.toLowerCase().trim() === description.toLowerCase().trim()
          );

          if (isDuplicate) {
             skippedCount++;
             // Non lo contiamo come errore grave, ma lo logghiamo
             // errors.push(`Riga ${i+1}: Duplicato rilevato e saltato.`);
             continue;
          }

          // --- Metodo Pagamento ---
          let pm = PaymentMethod.Contanti;
          const normPm = rawPm.toLowerCase();
          if (normPm.includes('flash')) pm = PaymentMethod.Flash;
          else if (normPm.includes('revolut')) pm = PaymentMethod.Revolut;
          else if (normPm.includes('q8')) pm = PaymentMethod.AppQ8;
          else if (normPm.includes('bancomat') || normPm.includes('card') || normPm.includes('carta')) pm = PaymentMethod.Bancomat;

          // --- SALVATAGGIO SU SUPABASE ---
          // Eseguiamo qui l'addExpense. Se fallisce, il catch interno catturerà l'errore per questa riga.
          await db.addExpense({
             date,
             description,
             amount,
             category,
             paymentMethod: pm,
             isSubscription: false
          }, session.user.id);

          importedCount++;

        } catch (rowErr: any) {
          console.error(`Errore importazione riga ${i+1}:`, rowErr);
          errors.push(`Riga ${i+1}: Errore salvataggio DB - ${rowErr.message || 'Errore sconosciuto'}`);
        }
      }

      // Ricarica dati
      if (importedCount > 0) {
        await fetchExpenses();
        setSuccessToast(`${importedCount} spese importate`);
        setTimeout(() => setSuccessToast(null), 4000);
      } 

      return { imported: importedCount, skipped: skippedCount, errors, debugInfo };

    } catch (err: any) {
      console.error(err);
      throw new Error("Errore lettura file globale: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleExportCSV = () => {
    if (expenses.length === 0) {
      alert("Nessuna spesa da esportare.");
      return;
    }

    try {
      const headers = ["Date", "Description", "Amount", "Category", "PaymentMethod", "IsSubscription"];
      const rows = expenses.map(e => {
        const safeDesc = e.description.replace(/"/g, '""');
        return [
          e.date,
          `"${safeDesc}"`,
          e.amount.toFixed(2),
          `"${e.category}"`,
          e.paymentMethod,
          e.isSubscription ? "true" : "false"
        ].join(",");
      });

      const csvContent = [headers.join(","), ...rows].join("\n");
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `mintflow_export_${format(new Date(), 'yyyyMMdd_HHmm')}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setSuccessToast("Esportazione completata!");
      setTimeout(() => setSuccessToast(null), 3000);
