    orange: 'bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400',
    purple: 'bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400'
  };
  return (
    <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-50 dark:border-gray-700 shadow-sm flex flex-col h-full relative group">
      <button 
        onClick={onEdit} 
        className="absolute top-4 right-4 p-2 text-gray-300 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-gray-700 rounded-xl transition-all opacity-0 group-hover:opacity-100"
        title="Modifica saldo manualmente"
      >
        <Edit2 size={16} />
      </button>

      <div className="flex justify-between items-start mb-4">
        <div className={`p-3 rounded-2xl ${colorClasses[color as keyof typeof colorClasses]}`}>{icon}</div>
        <div className="text-right pr-2">
          <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest truncate max-w-[100px]">{name}</p>
          <p className="text-lg font-black text-gray-800 dark:text-white leading-none">{currency}{balance.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
        </div>
      </div>
      <button onClick={onRefill} className="mt-auto w-full flex items-center justify-center gap-1.5 py-3 bg-emerald-500 hover:bg-emerald-600 text-white rounded-2xl text-[10px] font-bold transition-all shadow-md active:scale-95">
        <Plus size={14} /> {name.toUpperCase() === 'CONTANTI' ? 'PRELIEVO' : 'RICARICA'}
      </button>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CategoryConfig, Expense, PaymentMethod, WalletConfig } from '../types';
import { SmartCategorizer } from './SmartCategorizer';
import { Loader2, Save, Repeat, Building, CreditCard, Banknote, Fuel, AlertTriangle, Check, Zap, Copy } from 'lucide-react';
import { isSameMonth, isAfter, startOfMonth, parseISO, startOfToday } from 'date-fns';

interface ExpenseFormProps {
  onSubmit: (expense: Omit<Expense, 'id'>) => Promise<void> | void;
  onCancel: () => void;
  initialData?: Partial<Expense>;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
  expenses?: Expense[];
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ 
  onSubmit, 
  onCancel, 
  initialData, 
  currency = '€', 
  wallets, 
  categories,
  expenses
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<string>('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.Contanti);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [isSubscription, setIsSubscription] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Stato per il modale di conferma personalizzato
  const [showConfirmModal, setShowConfirmModal] = useState<{show: boolean, type: 'future' | 'past' | 'duplicate' | null}>({
    show: false,
    type: null
  });

  useEffect(() => {
    if (initialData) {
      if (initialData.description !== undefined) setDescription(initialData.description);
      if (initialData.amount !== undefined) setAmount(initialData.amount.toString());
      if (initialData.category !== undefined) setCategory(initialData.category);
      if (initialData.paymentMethod !== undefined) setPaymentMethod(initialData.paymentMethod);
      if (initialData.date !== undefined) setDate(initialData.date);
      if (initialData.isSubscription !== undefined) setIsSubscription(initialData.isSubscription || false);
    } else {
      setCategory(categories[categories.length - 1]?.name || 'Altro');
    }
  }, [initialData, categories]);

  const validateAndProcess = () => {
    const parsedAmount = parseFloat(amount.replace(',', '.'));
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      alert("Inserisci un importo valido");
      return;
    }

    const selectedDate = parseISO(date);
    const today = startOfToday();

    // Controllo Duplicati
    if (expenses) {
      const isDuplicate = expenses.some(e => 
        e.id !== initialData?.id && // Ignora se stessi in caso di modifica
        e.amount === parsedAmount && 
        e.date === date && 
        e.description.toLowerCase().trim() === description.toLowerCase().trim()
      );

      if (isDuplicate) {
        setShowConfirmModal({ show: true, type: 'duplicate' });
        return;
      }
    }

    // Controllo data futura: Qualsiasi data strettamente successiva ad oggi
    if (isAfter(selectedDate, today)) {
      setShowConfirmModal({ show: true, type: 'future' });
      return;
    }

    // Controllo data passata (mesi precedenti)
    const startOfThisMonth = startOfMonth(today);
    if (!isSameMonth(selectedDate, today) && selectedDate < startOfThisMonth) {
      setShowConfirmModal({ show: true, type: 'past' });
      return;
    }

    executeSubmit();
  };

  const executeSubmit = async () => {
    setIsSubmitting(true);
    const parsedAmount = parseFloat(amount.replace(',', '.'));
    try {
      await onSubmit({
        description: description.trim() || 'Spesa senza nome',
        amount: parsedAmount,
        category: category || 'Altro',
        paymentMethod,
        date,
        isSubscription
      });
    } catch (err: any) {
      console.error("Errore salvataggio:", err);
      alert("Errore: " + err.message);
    } finally {
      setIsSubmitting(false);
      setShowConfirmModal({ show: false, type: null });
    }
  };

  const getPaymentIcon = (method: PaymentMethod) => {
    const wallet = wallets.find(w => w.method === method);
    if (wallet) {
      if (method === PaymentMethod.Contanti) return <Banknote size={16} />;
      return wallet.icon === 'zap' ? <Zap size={16} /> : wallet.icon === 'fuel' ? <Fuel size={16} /> : <CreditCard size={16} />;
    }
    return method === PaymentMethod.Contanti ? <Banknote size={16} /> : <Building size={16} />;
  };

  // Creazione lista univoca metodi (Bancomat + tutti i portafogli configurati)
  const availableMethods = Array.from(new Set([
    PaymentMethod.Bancomat,
    ...wallets.map(w => w.method)
  ]));

  return (
    <div className="relative">
      <form onSubmit={(e) => { e.preventDefault(); validateAndProcess(); }} className="space-y-5">
        <div>
          <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Descrizione</label>
          <input 
            type="text" 
            value={description} 
            onChange={(e) => setDescription(e.target.value)} 
            placeholder="Cosa hai acquistato?" 
            className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" 
            required 
          />
          <SmartCategorizer description={description} onSuggest={setCategory} categories={categories} />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Importo</label>
            <input 
              type="text" 
              inputMode="decimal" 
              value={amount} 
              onChange={(e) => setAmount(e.target.value)} 
              placeholder={`0.00 ${currency}`} 
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-bold text-xl" 
              required 
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Data</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)} 
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-white outline-none font-medium" 
              required 
            />
          </div>
        </div>

        <button type="button" onClick={() => setIsSubscription(!isSubscription)} className={`w-full flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isSubscription ? 'bg-emerald-50 border-emerald-500 text-emerald-600' : 'bg-gray-50 border-transparent text-gray-400'}`}>
          <div className="flex items-center gap-2 font-bold text-sm"><Repeat size={18} /> Abbonamento Ricorrente</div>
          <div className={`w-10 h-6 rounded-full relative transition-colors ${isSubscription ? 'bg-emerald-500' : 'bg-gray-300'}`}><div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${isSubscription ? 'left-5' : 'left-1'}`}></div></div>
        </button>

        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Metodo di Pagamento</label>
          <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
            {availableMethods.map((m) => (
              <button key={m} type="button" onClick={() => setPaymentMethod(m)} className={`flex items-center gap-2 px-3 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${paymentMethod === m ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
                {getPaymentIcon(m)} <span className="truncate">{wallets.find(w => w.method === m)?.name || m}</span>
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Categoria</label>
          <div className="grid grid-cols-2 gap-2 max-h-32 overflow-y-auto p-1 custom-scrollbar">
            {categories.map((cat) => (
              <button key={cat.id} type="button" onClick={() => setCategory(cat.name)} className={`px-4 py-3 rounded-xl text-xs font-bold border-2 transition-all ${category === cat.name ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-white dark:bg-gray-800 border-emerald-50 dark:border-gray-700 text-gray-500'}`}>
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div className="flex gap-4 pt-4">
          <button type="button" onClick={onCancel} className="flex-1 px-6 py-4 rounded-2xl border-2 border-gray-100 dark:border-gray-700 text-gray-400 font-bold hover:bg-gray-50 transition-colors">Annulla</button>
          <button type="submit" disabled={isSubmitting} className="flex-1 px-6 py-4 rounded-2xl bg-emerald-500 text-white font-bold shadow-xl shadow-emerald-100 dark:shadow-none disabled:opacity-70 flex items-center justify-center gap-2 active:scale-95 transition-transform">
            {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />} Salva
          </button>
        </div>
      </form>

      {/* MODALE DI CONFERMA PERSONALIZZATO */}
      {showConfirmModal.show && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-emerald-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-xs p-8 shadow-2xl text-center animate-in zoom-in-95 duration-300 border-4 border-emerald-500">
            <div className="bg-emerald-100 dark:bg-emerald-900/30 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-emerald-600">
              {showConfirmModal.type === 'duplicate' ? <Copy size={32} /> : <AlertTriangle size={32} />}
            </div>
            <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
              {showConfirmModal.type === 'future' ? 'Data Futura' : showConfirmModal.type === 'duplicate' ? 'Possibile Duplicato' : 'Data Passata'}
            </h3>
            <p className="text-sm text-gray-500 dark:text-gray-400 mb-8 leading-relaxed font-medium">
              {showConfirmModal.type === 'future' 
                ? 'Questa è una data futura, sei sicuro di voler aggiungere?' 
                : showConfirmModal.type === 'duplicate'
                ? 'Sembra che tu abbia già inserito una spesa identica in questa data. Vuoi procedere comunque?'
                : 'Questa è una data passata, verrà aggiunta allo storico'}
            </p>
            <div className="flex flex-col gap-3">
              <button 
                onClick={executeSubmit}
                disabled={isSubmitting}
                className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 hover:bg-emerald-600 transition-colors"
              >
                {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />}
                {showConfirmModal.type === 'future' ? 'Si' : showConfirmModal.type === 'duplicate' ? 'Salva comunque' : 'Va bene!'}
              </button>
              <button 
                onClick={() => setShowConfirmModal({ show: false, type: null })}
                className="w-full py-3 text-gray-400 font-bold hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
              >
                {showConfirmModal.type === 'future' ? 'No' : 'Annulla'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Zap, Wallet, Fuel, Plus, Clock, Info, CreditCard, Edit2, X, Check, Loader2, Banknote } from 'lucide-react';
import { Expense, PaymentMethod, WalletConfig } from '../types';
import { format, isBefore, startOfToday, parseISO } from 'date-fns';
import { it } from 'date-fns/locale';

interface RicaricheViewProps {
  onRefill: (wallet: WalletConfig) => void;
  onSaveExpense: (expense: Omit<Expense, 'id'>) => Promise<void>;
  expenses: Expense[];
  currency?: string;
  wallets: WalletConfig[];
}

export const RicaricheView: React.FC<RicaricheViewProps> = ({ onRefill, onSaveExpense, expenses, currency = '€', wallets }) => {
  const [editingWallet, setEditingWallet] = useState<WalletConfig | null>(null);
  const [newBalance, setNewBalance] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const balances = useMemo(() => {
    const today = startOfToday();

    return wallets.map(w => {
      // Ricariche (entrate) + Aggiustamenti Positivi
      const totalRecharged = expenses
        .filter(e => {
          const desc = e.description.toLowerCase();
          const name = w.name.toLowerCase();
          const isInflow = desc.includes(`ricarica ${name}`) || desc.includes(`aggiustamento ${name}`);
          return isInflow && e.paymentMethod !== w.method;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      // Spese (uscite) - Vengono scalate SOLO se la data è OGGI o FUTURA (successiva a ieri)
      const totalSpent = expenses
        .filter(e => {
          const isWalletMethod = e.paymentMethod === w.method;
          const isNotRefill = !e.description.toLowerCase().includes('ricarica');
          const expenseDate = parseISO(e.date);
          // Se la data è prima di oggi, non scaliamo il saldo
          const isNotPast = !isBefore(expenseDate, today);

          return isWalletMethod && isNotRefill && isNotPast;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      return {
        ...w,
        balance: Math.max(0, totalRecharged - totalSpent)
      };
    });
  }, [expenses, wallets]);

  const refillExpenses = useMemo(() => {
    return expenses.filter(e => 
      e.description.toLowerCase().includes('ricarica') || e.description.toLowerCase().includes('deposito')
    ).slice(0, 10);
  }, [expenses]);

  const handleEditClick = (wallet: WalletConfig) => {
    const current = balances.find(b => b.id === wallet.id)?.balance || 0;
    setNewBalance(current.toFixed(2));
    setEditingWallet(wallet);
  };

  const handleBalanceUpdate = async () => {
    if (!editingWallet) return;
    const target = parseFloat(newBalance.replace(',', '.'));
    if (isNaN(target) || target < 0) {
      alert("Inserisci un importo valido");
      return;
    }

    const current = balances.find(b => b.id === editingWallet.id)?.balance || 0;
    const diff = target - current;

    if (Math.abs(diff) < 0.01) {
      setEditingWallet(null);
      return;
    }

    setIsSubmitting(true);
    try {
      const isPositive = diff > 0;

      // Logica intelligente per la fonte dell'aggiustamento:
      // Se sto aggiungendo soldi ai contanti, la fonte è "Bancomat" (prelievo)
      // Se sto aggiungendo a un wallet elettronico, la fonte è "Contanti" (versamento)
      let sourceMethod = editingWallet.method === PaymentMethod.Contanti ? PaymentMethod.Bancomat : PaymentMethod.Contanti;

      await onSaveExpense({
        description: `Aggiustamento ${editingWallet.name}`,
        amount: Math.abs(diff),
        category: 'Altro',
        paymentMethod: isPositive ? sourceMethod : editingWallet.method,
        date: format(new Date(), 'yyyy-MM-dd'),
        isSubscription: false
      });
      setEditingWallet(null);
    } catch (err: any) {
      alert("Errore aggiornamento: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const getWalletIcon = (w: WalletConfig) => {
    if (w.method === PaymentMethod.Contanti) return <Banknote size={20} />;
    if (w.icon === 'zap') return <Zap size={20} />;
    if (w.icon === 'fuel') return <Fuel size={20} />;
    if (w.icon === 'credit-card') return <CreditCard size={20} />;
    return <Wallet size={20} />;
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 relative">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-xl font-bold text-gray-800 dark:text-white mb-2">I tuoi Portafogli</h2>
          <p className="text-gray-500 dark:text-gray-400 text-sm">Il saldo considera solo le spese da oggi in avanti.</p>
        </div>
        <div className="hidden md:flex items-center gap-1 text-[10px] font-bold text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 px-3 py-1.5 rounded-full border border-emerald-100 dark:border-emerald-800 uppercase tracking-widest">
          <Info size={12} /> Smart Balance
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {balances.map((w) => (
          <WalletCard 
            key={w.id}
            name={w.name} 
            balance={w.balance} 
            icon={getWalletIcon(w)} 
            onRefill={() => onRefill(w)} 
            onEdit={() => handleEditClick(w)}
            color={w.method === PaymentMethod.Contanti ? 'emerald' : w.icon === 'zap' ? 'emerald' : w.icon === 'fuel' ? 'orange' : w.icon === 'credit-card' ? 'purple' : 'blue'} 
            currency={currency} 
          />
        ))}
      </div>

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <div className="flex items-center gap-2 mb-6">
          <Clock className="text-emerald-500" size={20} />
          <h3 className="text-lg font-bold text-gray-800 dark:text-white">Movimenti Portafogli</h3>
        </div>
        <div className="space-y-3">
          {refillExpenses.length > 0 ? (
            refillExpenses.map((expense) => (
              <div key={expense.id} className="flex items-center justify-between p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50 hover:bg-emerald-50 dark:hover:bg-gray-700 transition-colors">
                <div className="flex items-center gap-4">
                   <div className="w-10 h-10 rounded-xl bg-white dark:bg-gray-800 flex items-center justify-center text-emerald-500 shadow-sm"><Plus size={18} /></div>
                   <div>
                     <p className="font-bold text-gray-800 dark:text-white text-sm">{expense.description}</p>
                     <p className="text-[10px] text-gray-400 dark:text-gray-500 font-medium uppercase tracking-tight">
                       {format(new Date(expense.date), 'dd MMMM yyyy', { locale: it })} • {expense.paymentMethod}
                     </p>
                   </div>
                </div>
                <span className="font-bold text-emerald-600 dark:text-emerald-400">+{currency}{expense.amount.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</span>
              </div>
            ))
          ) : (
            <div className="text-center py-10"><p className="text-gray-400 dark:text-gray-500 text-sm">Nessuna ricarica registrata.</p></div>
          )}
        </div>
      </div>

      {editingWallet && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold dark:text-white">Modifica Saldo</h3>
              <button onClick={() => setEditingWallet(null)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>

            <div className="bg-emerald-50 dark:bg-emerald-900/20 p-4 rounded-2xl mb-6 flex items-center gap-3">
              <div className="p-2 bg-white dark:bg-gray-700 rounded-xl text-emerald-500 shadow-sm">
                {getWalletIcon(editingWallet)}
              </div>
              <div>
                <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Portafoglio</p>
                <p className="font-bold text-emerald-700 dark:text-emerald-400">{editingWallet.name}</p>
              </div>
            </div>

            <div className="mb-6">
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nuovo Saldo Attuale</label>
              <input 
                autoFocus
                type="number" 
                inputMode="decimal"
                value={newBalance} 
                onChange={(e) => setNewBalance(e.target.value)} 
                className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-black text-2xl" 
              />
              <p className="text-[10px] text-gray-400 mt-2 ml-1">*Verrà creata una transazione di aggiustamento</p>
            </div>

            <button 
              onClick={handleBalanceUpdate}
              disabled={isSubmitting}
              className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 hover:bg-emerald-600 transition-colors"
            >
              {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Check size={20} />} Salva Saldo
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const WalletCard = ({ name, balance, icon, onRefill, onEdit, color, currency }: any) => {
  const colorClasses = {
    emerald: 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400',
    blue: 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400',
    orange: 'bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400',
    purple: 'bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400'
  };
  return (
    <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-50 dark:border-gray-700 shadow-sm flex flex-col h-full relative group">
      <button 
        onClick={onEdit} 
        className="absolute top-4 right-4 p-2 text-gray-300 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-gray-700 rounded-xl transition-all opacity-0 group-hover:opacity-100"
        title="Modifica saldo manualmente"
      >
        <Edit2 size={16} />
      </button>

      <div className="flex justify-between items-start mb-4">
        <div className={`p-3 rounded-2xl ${colorClasses[color as keyof typeof colorClasses]}`}>{icon}</div>
        <div className="text-right pr-2">
          <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest truncate max-w-[100px]">{name}</p>
          <p className="text-lg font-black text-gray-800 dark:text-white leading-none">{currency}{balance.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
        </div>
      </div>
      <button onClick={onRefill} className="mt-auto w-full flex items-center justify-center gap-1.5 py-3 bg-emerald-500 hover:bg-emerald-600 text-white rounded-2xl text-[10px] font-bold transition-all shadow-md active:scale-95">
        <Plus size={14} /> {name.toUpperCase() === 'CONTANTI' ? 'PRELIEVO' : 'RICARICA'}
      </button>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { ReceiptScanner } from './components/ReceiptScanner';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
import { Auth } from './components/Auth';
import { Expense, UserSettings, PaymentMethod, WalletConfig, CategoryConfig, ProfileType } from './types';
import { Plus, ScanLine, Cloud, Loader2, PiggyBank, PartyPopper, History, CheckCircle2, Trash2, AlertTriangle, Target, ArrowRight } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { startOfMonth, format, isSameMonth, parseISO, isAfter, endOfMonth, getDate } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [allExpenses, setAllExpenses] = useState<Expense[]>([]); // Tutte le spese
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [successToast, setSuccessToast] = useState<string | null>(null);
  const [showBudgetPrompt, setShowBudgetPrompt] = useState(false);

  const [expenseToDelete, setExpenseToDelete] = useState<string | null>(null);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultWallets: WalletConfig[] = [
      { id: 'w1', name: 'Prepagata Flash', method: PaymentMethod.Flash, icon: 'zap' },
      { id: 'w2', name: 'Prepagata Revolut', method: PaymentMethod.Revolut, icon: 'credit-card' },
      { id: 'w3', name: 'App Q8', method: PaymentMethod.AppQ8, icon: 'fuel' },
      { id: 'w0', name: 'Contanti', method: PaymentMethod.Contanti, icon: 'wallet' }
    ];

    const defaultCategories: CategoryConfig[] = [
      { id: 'c1', name: 'Sigarette', color: '#ef4444' },
      { id: 'c2', name: 'Benzina', color: '#f97316' },
      { id: 'c3', name: 'Autostrada', color: '#eab308' },
      { id: 'c4', name: 'Ricarica Chiavetta', color: '#84cc16' },
      { id: 'c5', name: 'Svago', color: '#06b6d4' },
      { id: 'c6', name: 'Salute', color: '#ec4899' },
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true, color: '#8b5cf6' },
      { id: 'c8', name: 'Altro', color: '#64748b' }
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      jointBudget: 1500, // Default per cointestato
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories,
      language: 'it',
      currentProfile: 'personal'
    };

    if (!saved) return defaultSettings;

    try {
      const parsed = JSON.parse(saved);
      // Ensure jointBudget and currentProfile exist for old saved data
      const merged = { 
        ...defaultSettings, 
        ...parsed,
        currentProfile: parsed.currentProfile || 'personal',
        jointBudget: parsed.jointBudget || defaultSettings.jointBudget
      };

      // Assicuriamoci che il wallet contanti sia presente se non c'è (alla fine)
      if (!merged.wallets.some(w => w.method === PaymentMethod.Contanti)) {
          merged.wallets = [...merged.wallets, defaultWallets[3]];
      }

      return merged;
    } catch {
      return defaultSettings;
    }
  });

  // Filtra spese in base al profilo attivo
  const expenses = useMemo(() => {
    return allExpenses.filter(e => (e.profile || 'personal') === userSettings.currentProfile);
  }, [allExpenses, userSettings.currentProfile]);

  // Budget attuale in base al profilo
  const currentBudget = userSettings.currentProfile === 'personal' 
    ? userSettings.monthlyBudget 
    : (userSettings.jointBudget || 1500);

  // Salva le impostazioni ogni volta che cambiano
  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
  }, [userSettings]);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  // Controllo budget mensile o nuovo utente
  useEffect(() => {
    if (session && !isInitialLoading) {
      const today = new Date();

      // Determina l'ultima data di aggiornamento corretta in base al profilo
      const lastUpdateStr = userSettings.currentProfile === 'personal' 
        ? userSettings.lastBudgetUpdate 
        : userSettings.lastJointBudgetUpdate;

      const lastUpdate = lastUpdateStr ? parseISO(lastUpdateStr) : null;

      // Mostra il prompt se:
      // 1. Mai impostato (nuovo utente/profilo)
      // 2. L'ultimo aggiornamento è di un mese precedente a quello attuale (chiede 1 volta al mese, qualsiasi giorno sia)
      if (!lastUpdate || !isSameMonth(lastUpdate, today)) {
        setShowBudgetPrompt(true);
      }
    }
  }, [session, isInitialLoading, userSettings.currentProfile, userSettings.lastBudgetUpdate, userSettings.lastJointBudgetUpdate]);

  useEffect(() => {
    const initSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session?.user) {
        const metadata = session.user.user_metadata;
        const displayName = metadata.full_name || metadata.display_name || metadata.name || session.user.email?.split('@')[0] || 'Utente';
        setUserSettings(prev => ({ ...prev, name: displayName }));
      }
      setIsInitialLoading(false);
    };
    initSession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchExpenses = useCallback(async () => {
    if (!session?.user?.id) return;
    try {
      setIsLoading(true);
      const data = await db.getExpenses(session.user.id);
      setAllExpenses(data);
    } catch (err) {
      console.error("Errore caricamento:", err);
    } finally {
      setIsLoading(false);
    }
  }, [session]);

  useEffect(() => {
    if (session?.user?.id) {
      fetchExpenses();
    }
  }, [session, fetchExpenses]);

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);

      // Assicura che la spesa sia associata al profilo corrente
      const dataToSave = {
        ...expenseData,
        profile: userSettings.currentProfile
      };

      let savedExpense: Expense | null = null;

      if (prefill?.id) {
        savedExpense = await db.updateExpense(prefill.id, dataToSave);
        if (savedExpense) {
            setAllExpenses(prev => prev.map(e => e.id === savedExpense!.id ? savedExpense! : e));
        }
      } else {
        savedExpense = await db.addExpense(dataToSave, session.user.id);
        if (savedExpense) {
            setAllExpenses(prev => [savedExpense!, ...prev]);
        }
      }
      setShowForm(false);
      setPrefill(null);
      setSuccessToast("Operazione completata!");
      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      alert(`Errore Cloud: ${err.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSetMonthlyBudget = (amount: number) => {
    const now = new Date().toISOString();

    setUserSettings(prev => {
        if (prev.currentProfile === 'personal') {
            return {
                ...prev,
                monthlyBudget: amount,
                lastBudgetUpdate: now
            };
        } else {
            return {
                ...prev,
                jointBudget: amount,
                lastJointBudgetUpdate: now
            };
        }
    });

    setShowBudgetPrompt(false);
    setSuccessToast("Budget impostato con successo!");
    setTimeout(() => setSuccessToast(null), 3000);
  };

  const handleSwitchProfile = (profile: ProfileType) => {
    setUserSettings(prev => ({ ...prev, currentProfile: profile }));
    setActiveTab('dashboard'); // Torna alla dashboard quando cambi profilo
    setSuccessToast(`Profilo ${profile === 'personal' ? 'Personale' : 'Cointestato'} Attivo`);
    setTimeout(() => setSuccessToast(null), 2000);
  };

  const handleImportCSV = async (file: File): Promise<{ imported: number, skipped: number, errors: string[], debugInfo: string }> => {
    if (!session?.user?.id) throw new Error("Utente non autenticato.");

    setIsSyncing(true);
    let importedCount = 0;
    let skippedCount = 0;
    const errors: string[] = [];

    try {
      const text = await file.text();
      const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
      if (lines.length < 1) throw new Error("File vuoto");

      const separator = lines[0].includes(';') ? ';' : ',';
      const headers = lines[0].toLowerCase().split(separator).map(h => h.trim());

      const dateIdx = headers.findIndex(h => h.includes('dat') || h.includes('giorno'));
      const descIdx = headers.findIndex(h => h.includes('desc') || h.includes('causale') || h.includes('testo'));
      const amountIdx = headers.findIndex(h => h.includes('importo') || h.includes('euro') || h.includes('valore') || h.includes('amount'));
      const catIdx = headers.findIndex(h => h.includes('cat'));

      const startLine = (dateIdx === -1 && amountIdx === -1) ? 0 : 1;

      for (let i = startLine; i < lines.length; i++) {
        const parts = lines[i].split(separator).map(p => p.trim().replace(/^"|"$/g, ''));

        try {
          const rawDate = parts[dateIdx === -1 ? 0 : dateIdx];
          const rawDesc = parts[descIdx === -1 ? 1 : descIdx];
          const rawAmount = parts[amountIdx === -1 ? 2 : amountIdx];
          const category = catIdx > -1 ? parts[catIdx] : 'Altro';

          if (!rawDate || !rawAmount) continue;

          // Date Parsing
          let date = "";
          const dateMatch = rawDate.match(/(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})/);
          if (dateMatch) {
            let [_, d, m, y] = dateMatch;
            if (y.length === 2) y = "20" + y;
            date = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
          } else if (rawDate.match(/^\d{4}-\d{2}-\d{2}$/)) {
            date = rawDate;
          }

          // Amount Parsing
          const amount = parseFloat(rawAmount.replace(',', '.').replace(/[^0-9.-]/g, ''));

          if (!date || isNaN(amount)) {
            errors.push(`Riga ${i+1}: Dati non validi (Data: ${rawDate}, Importo: ${rawAmount})`);
            continue;
          }

          // Duplicate check
          const isDuplicate = allExpenses.some(e => e.date === date && Math.abs(e.amount - amount) < 0.01 && e.description === rawDesc && e.profile === userSettings.currentProfile);
          if (isDuplicate) {
            skippedCount++;
            continue;
          }

          await db.addExpense({
            date,
            description: rawDesc || "Importato",
            amount,
            category: category,
            paymentMethod: PaymentMethod.Contanti,
            isSubscription: false,
            profile: userSettings.currentProfile
          }, session.user.id);

          importedCount++;
        } catch (e: any) {
          errors.push(`Riga ${i+1}: ${e.message}`);
        }
      }

      if (importedCount > 0) await fetchExpenses();
      return { imported: importedCount, skipped: skippedCount, errors, debugInfo: `Sep: ${separator}` };
    } finally {
      setIsSyncing(false);
    }
  };

  const handleExportCSV = () => {
    const headers = ["Data", "Descrizione", "Importo", "Categoria", "Metodo", "Profilo"];
    const rows = expenses.map(e => [e.date, e.description, e.amount, e.category, e.paymentMethod, e.profile || 'personal']);
    const csv = [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `spese_${userSettings.currentProfile}_${format(new Date(), 'yyyyMMdd')}.csv`;
    a.click();
  };

  if (isInitialLoading) return <div className="min-h-screen flex items-center justify-center bg-mint-50"><Loader2 className="animate-spin text-emerald-500" size={48} /></div>;
  if (!session) return <Auth onSuccess={() => {}} />;

  return (
    <Layout 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        lang={userSettings.language}
        currentProfile={userSettings.currentProfile}
        onSwitchProfile={handleSwitchProfile}
    >
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {successToast && <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4">{successToast}</div>}

        {activeTab === 'dashboard' && <Dashboard expenses={expenses} budget={currentBudget} userName={userSettings.name} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} lang={userSettings.language} />}
        {activeTab === 'list' && (
          <div className="space-y-6">
            <div className="flex gap-3">
              <button onClick={() => { setPrefill(null); setShowForm(true); }} className="flex-1 bg-emerald-500 text-white py-4 rounded-2xl flex items-center justify-center gap-2 font-bold shadow-lg"><Plus size={20} /> Aggiungi</button>
            </div>
            <ExpenseList expenses={expenses} onDelete={id => setExpenseToDelete(id)} onEdit={ex => { setPrefill(ex); setShowForm(true); }} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
          </div>
        )}
        {activeTab === 'ricariche' && <RicaricheView onRefill={w => { 
            const sourceMethod = w.method === PaymentMethod.Contanti ? PaymentMethod.Bancomat : PaymentMethod.Contanti;
            setPrefill({ description: `Ricarica ${w.name}`, category: 'Altro', paymentMethod: sourceMethod, date: format(new Date(), 'yyyy-MM-dd') }); 
            setShowForm(true); 
        }} onSaveExpense={handleSaveExpense} expenses={expenses} currency={userSettings.currency} wallets={userSettings.wallets} />}
        {activeTab === 'ai' && <AiInsights expenses={expenses} />}
        {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={() => {}} onImport={handleImportCSV} onExport={handleExportCSV} expenses={expenses} email={session.user.email} />}
        {activeTab === 'subscriptions' && <SubscriptionsView expenses={expenses} onAddSub={() => { setPrefill({ isSubscription: true }); setShowForm(true); }} onDelete={id => setExpenseToDelete(id)} currency={userSettings.currency} />}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-md p-8 shadow-2xl relative">
              <button onClick={() => setShowForm(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600">✕</button>
              <h2 className="text-2xl font-bold mb-6 text-gray-800 dark:text-white">{prefill?.id ? 'Modifica' : 'Nuova Spesa'}</h2>
              <ExpenseForm onSubmit={handleSaveExpense} onCancel={() => setShowForm(false)} initialData={prefill || undefined} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} expenses={expenses} />
            </div>
          </div>
        )}

        {showBudgetPrompt && (
          <BudgetPromptModal 
            onConfirm={handleSetMonthlyBudget} 
            initialValue={currentBudget} 
            currency={userSettings.currency}
            isNewUser={userSettings.currentProfile === 'personal' ? !userSettings.lastBudgetUpdate : !userSettings.lastJointBudgetUpdate}
            profileType={userSettings.currentProfile}
          />
        )}

        {expenseToDelete && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-black/20 backdrop-blur-sm">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-xs p-8 shadow-2xl text-center">
              <div className="bg-red-100 text-red-600 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4"><Trash2 size={32} /></div>
              <h3 className="text-xl font-bold mb-2">Elimina?</h3>
              <div className="flex flex-col gap-3 mt-6">
                <button onClick={async () => { await db.deleteExpense(expenseToDelete); setAllExpenses(prev => prev.filter(e => e.id !== expenseToDelete)); setExpenseToDelete(null); }} className="w-full py-4 bg-red-500 text-white rounded-2xl font-bold">Elimina</button>
                <button onClick={() => setExpenseToDelete(null)} className="w-full py-3 text-gray-400 font-bold">Annulla</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

